-- Generated by scripts/build-professions-migration.mjs. Do not edit by hand.
-- Profession: embedded-ai · tiers 0 · 400 cards

insert into public.professions (id, name, tagline, description, icon, accent, gradient, planned_cards, position)
values ('embedded-ai', 'Embedded AI Engineering', 'Make machine learning run on tiny, power-sipping chips.', 'From bits, volts and your first C program to the systems that run neural networks on microcontrollers, phones and custom chips: embedded systems, signal processing, deep learning, model compression, ML compilers and accelerators, up to today''s research on efficient AI. It follows the syllabi of leading university courses and the field''s standard books.', 'chip', '#0FA3A3', array['#16C2C2', '#3B82F6']::text[], 5000, 1)
on conflict (id) do update set name = excluded.name, tagline = excluded.tagline, description = excluded.description,
  icon = excluded.icon, accent = excluded.accent, gradient = excluded.gradient, planned_cards = excluded.planned_cards,
  position = excluded.position;

insert into public.profession_tiers (profession_id, tier, slug, name, milestone, summary, planned_cards) values
  ('embedded-ai', 0, 'foundations', 'Foundations', null, 'You can write and debug small Python and C programs, use the command line and Git, read binary and hex, and work out voltages, currents, power and battery life with the right units.', 400),
  ('embedded-ai', 1, 'core-engineering', 'Core engineering', null, 'You understand how software meets hardware: memory and pointers in C, core data structures, small analog and digital circuits, how a RISC-V processor with caches runs code, number formats, and safe multithreading. You can estimate cost, timing and power at each of these layers.', 600),
  ('embedded-ai', 2, 'embedded-systems', 'Embedded systems', 'Junior engineer', 'You can bring up, program, debug and ship firmware for a microcontroller: boot it from scratch, handle interrupts, peripherals and sensors, run tasks under an RTOS, save power and update it securely. You can also work on an embedded Linux board with an AI accelerator.', 600),
  ('embedded-ai', 3, 'math-signals', 'Math and signals for ML', null, 'You can do the math that models are built on (vectors, gradients, probabilities and bits) and turn raw sensor signals into clean features that a small model can use.', 500),
  ('embedded-ai', 4, 'ml-deep-learning', 'ML and deep learning', 'Bachelor''s', 'You can build, train and debug classic models and modern neural networks (CNNs, sequence models and transformers) in PyTorch, and explain how today''s LLMs and diffusion models are trained and run.', 650),
  ('embedded-ai', 5, 'efficient-ml-tinyml', 'Efficient ML and TinyML', 'Master''s', 'You can measure what a model costs in operations, memory, energy and time, shrink it with pruning, quantization, efficient architectures and distillation, and deploy and benchmark it on microcontrollers and edge chips.', 750),
  ('embedded-ai', 6, 'ml-systems', 'ML systems: compilers, runtimes, accelerators', null, 'You can make ML code run fast on CPUs, GPUs, NPUs and FPGAs: measure where time goes, compile and tune kernels, plan memory, and reason about how an accelerator moves data. You can split a model across a device''s processors and predict the result before deploying.', 750),
  ('embedded-ai', 7, 'phd-core', 'Advanced / PhD core', 'Quals', 'You can answer qualifying-exam questions on how processors and memory systems work and on accelerator research topics: sparsity, number formats, hardware–model co-design, on-device training, emerging hardware and security. You can evaluate a design with sound methodology and reproduce a published result.', 500),
  ('embedded-ai', 8, 'research-frontier', 'Research frontier', 'PhD', 'You can read and critique current research on compressing and running large models on devices, and you know the state of low-bit formats, edge chips and benchmarks as of late 2026. You can tell which open problems remain and judge vendor claims against first principles.', 250)
on conflict (profession_id, tier) do update set slug = excluded.slug, name = excluded.name, milestone = excluded.milestone,
  summary = excluded.summary, planned_cards = excluded.planned_cards;

insert into public.profession_modules (id, profession_id, tier, position, title, summary, planned_cards, refs, practice) values
  ('embedded-ai/digital-representation', 'embedded-ai', 0, 0, 'Digital representation', 'Read and convert the binary and hex numbers, byte sizes and text codes that computers use.', 50, array['CS50x 2026, Week 0 (Scratch) and Week 4 (Memory) lectures', 'Bryant & O''Hallaron, CS:APP 3e, ch. 2 (Representing and Manipulating Information)', 'Harris & Harris, Digital Design and Computer Architecture RISC-V ed., ch. 1 (From Zero to One)']::text[], '[]'::jsonb),
  ('embedded-ai/engineering-numeracy', 'embedded-ai', 0, 1, 'Engineering numeracy', 'Do the everyday maths of engineering: powers, logarithms, unit prefixes, unit checks and graphs.', 50, array['OpenStax College Algebra 2e, ch. 1 (Prerequisites), ch. 3–4 (Functions; Linear Functions) and ch. 6 (Exponential and Logarithmic Functions)', 'OpenStax University Physics Vol. 1, ch. 1 (Units and Measurement)']::text[], '[]'::jsonb),
  ('embedded-ai/electricity-basics', 'embedded-ai', 0, 2, 'Electricity basics', 'Calculate voltage, current, resistance, power and battery life for simple circuits.', 55, array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2 (Theory), ch. 3 (Basic Electronic Components), ch. 7 (Hands-on Electronics)', 'OpenStax University Physics Vol. 2, §9.4–9.5 and §10.2–10.4']::text[], '[{"title":"PhET Circuit Construction Kit: DC (build series and parallel circuits and check Ohm''s law)","url":"https://phet.colorado.edu/en/simulations/circuit-construction-kit-dc"}]'::jsonb),
  ('embedded-ai/python-1', 'embedded-ai', 0, 3, 'Python I', 'Write small Python programs that make decisions, repeat work, use functions and handle files and errors.', 70, array['CS50P (Harvard), Lectures 0–6 and 9', 'CS50x 2026, Week 6 (Python)', 'The Python Tutorial (docs.python.org), ch. 3–8 and 15']::text[], '[{"title":"CS50P problem sets 0–6","url":"https://cs50.harvard.edu/python/psets/"}]'::jsonb),
  ('embedded-ai/python-2-numpy', 'embedded-ai', 0, 4, 'Python II and NumPy', 'Build your own Python classes and crunch arrays of numbers quickly with NumPy, then plot the results.', 55, array['CS50P, Lecture 8 (Object-Oriented Programming)', 'NumPy User Guide: the absolute basics for beginners; NumPy fundamentals', 'Dive into Deep Learning (d2l.ai), ch. 2 (Preliminaries)', 'Matplotlib documentation: Quick start guide']::text[], '[{"title":"NumPy: the absolute basics for beginners (work through every example)","url":"https://numpy.org/doc/stable/user/absolute_beginners.html"},{"title":"NumPy tutorials (start with the Moore''s Law application: fit and plot real data)","url":"https://numpy.org/numpy-tutorials/"}]'::jsonb),
  ('embedded-ai/developer-tooling', 'embedded-ai', 0, 5, 'Developer tooling', 'Work confidently in a terminal, manage Python environments, track code with Git and read error messages.', 45, array['MIT Missing Semester 2026: Introduction to the Shell; Command-line Environment; Debugging and Profiling; Version Control and Git; Packaging and Shipping Code', 'Pro Git 2e (git-scm.com), ch. 2 (Git Basics) and ch. 3 (Git Branching)', 'The Python Tutorial, ch. 12 (Virtual Environments and Packages)']::text[], '[{"title":"Missing Semester 2026: shell lecture exercises","url":"https://missing.csail.mit.edu/2026/course-shell/"},{"title":"Learn Git Branching (interactive branching, merging and rebasing levels)","url":"https://learngitbranching.js.org/"}]'::jsonb),
  ('embedded-ai/c-1', 'embedded-ai', 0, 6, 'C I', 'Write, compile and debug small C programs that use integers, functions, arrays and strings.', 75, array['Kernighan & Ritchie, The C Programming Language 2e, ch. 1–4', 'CS50x 2026, Week 1 (C) and Week 2 (Arrays)', 'Bryant & O''Hallaron, CS:APP 3e, ch. 7 (Linking)']::text[], '[{"title":"CS50x Problem Set 1 (Mario, Cash or Credit)","url":"https://cs50.harvard.edu/x/psets/1/"},{"title":"CS50x problem sets index (continue with Problem Set 2)","url":"https://cs50.harvard.edu/x/psets/"}]'::jsonb),
  ('embedded-ai/c-2-memory', 'embedded-ai', 1, 7, 'C II: memory', 'Control memory directly in C with pointers, structs, dynamic allocation and bit masks, and avoid undefined behaviour.', 90, array['Kernighan & Ritchie 2e, ch. 5 (Pointers and Arrays) and ch. 6 (Structures)', 'Bryant & O''Hallaron, CS:APP 3e, ch. 3 (§3.7–3.9) and ch. 9 (§9.9, §9.11)', 'CS50x 2026, Week 4 (Memory)']::text[], '[{"title":"CS50x Problem Set 4 (Volume, Filter, Recover)","url":"https://cs50.harvard.edu/x/psets/4/"}]'::jsonb),
  ('embedded-ai/data-structures-algorithms', 'embedded-ai', 1, 8, 'Data structures and algorithms', 'Pick and build the right data structure and algorithm, and estimate how its cost grows with input size.', 80, array['Cormen, Leiserson, Rivest & Stein, Introduction to Algorithms (CLRS) 4e, ch. 2–3, 6–8, 10–13, 16, 20', 'CS50x 2026, Week 3 (Algorithms) and Week 5 (Data Structures)']::text[], '[{"title":"CS50x Speller: build a fast hash-table spell checker in C","url":"https://cs50.harvard.edu/x/psets/5/speller/"}]'::jsonb),
  ('embedded-ai/modern-cpp-embedded', 'embedded-ai', 1, 9, 'Modern C++ for embedded', 'Use modern C++ features safely on small devices that have no heap and no exceptions.', 60, array['Stroustrup, A Tour of C++ 3e, ch. 1–8, 10, 12–13, 15–16', 'Embedded Template Library (etlcpp.com) documentation']::text[], '[{"title":"Compiler Explorer: compare the assembly generated for C and C++ versions of the same code","url":"https://godbolt.org/"}]'::jsonb),
  ('embedded-ai/circuits-analog', 'embedded-ai', 1, 10, 'Circuits and analog', 'Analyse and design the small analog circuits around a microcontroller: dividers, RC filters, transistor switches, op-amps and power supplies.', 65, array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2–5, 8, 9, 11', 'OpenStax University Physics Vol. 2, ch. 10 (Direct-Current Circuits)']::text[], '[{"title":"Falstad Circuit Simulator: build dividers, RC filters, MOSFET switches and op-amp stages","url":"https://www.falstad.com/circuit/"}]'::jsonb),
  ('embedded-ai/digital-logic', 'embedded-ai', 1, 11, 'Digital logic', 'Design logic circuits, from gates and adders to clocked state machines, and reason about their timing and power.', 70, array['Harris & Harris, Digital Design and Computer Architecture RISC-V ed., ch. 1–3 and 5', 'MIT 6.191 Computation Structures (Fall 2026), L01–L09 and Labs 1–3']::text[], '[{"title":"Nand2Tetris Projects 1–3: build gates, an ALU and memory from NAND","url":"https://www.nand2tetris.org/course"}]'::jsonb),
  ('embedded-ai/computer-organization', 'embedded-ai', 1, 12, 'Computer organization', 'Explain how a processor runs RISC-V programs and how pipelines, caches and virtual memory set its performance.', 90, array['Harris & Harris, DDCA RISC-V ed., ch. 6 (Architecture), ch. 7 (Microarchitecture), ch. 8 (Memory Systems)', 'Patterson & Hennessy, Computer Organization and Design RISC-V ed., ch. 1, 2, 4, 5', 'MIT 6.191 (Fall 2026), L10–L19 and Labs 4–7', 'Bryant & O''Hallaron, CS:APP 3e, ch. 6 (The Memory Hierarchy)']::text[], '[{"title":"RARS: write and single-step RISC-V assembly programs","url":"https://github.com/TheThirdOne/rars"},{"title":"Nand2Tetris Projects 4–6: machine language, a CPU and an assembler","url":"https://www.nand2tetris.org/course"}]'::jsonb),
  ('embedded-ai/number-formats', 'embedded-ai', 1, 13, 'Number formats', 'Choose and use fixed-point and floating-point formats, and control rounding, overflow and accumulator size.', 55, array['Goldberg 1991, ''What Every Computer Scientist Should Know About Floating-Point Arithmetic'' (ACM Computing Surveys)', 'Harris & Harris, DDCA RISC-V ed., ch. 5 (Digital Building Blocks: number systems)', 'Bryant & O''Hallaron, CS:APP 3e, §2.4 Floating Point', 'White, Making Embedded Systems 2e, ch. 12 (Math)']::text[], '[{"title":"Float Toy: flip the bits of half, single and double precision floats","url":"https://evanw.github.io/float-toy/"}]'::jsonb),
  ('embedded-ai/operating-systems', 'embedded-ai', 1, 14, 'Operating systems', 'Explain how an operating system shares the CPU and talks to devices, and write correct multithreaded code with locks.', 60, array['Arpaci-Dusseau & Arpaci-Dusseau, Operating Systems: Three Easy Pieces (OSTEP), ch. 4–8, 26–33, 36', 'Bryant & O''Hallaron, CS:APP 3e, §8.1 and §12.3–12.5', 'MIT 6.191 (Fall 2026), L16 OS; L19 Exceptions, I/O; L20 Synchronization']::text[], '[{"title":"OSTEP homework simulators (scheduling, threads and locks)","url":"https://github.com/remzi-arpacidusseau/ostep-homework"},{"title":"OSTEP projects (start with the concurrency projects)","url":"https://github.com/remzi-arpacidusseau/ostep-projects"}]'::jsonb),
  ('embedded-ai/hdl-fpga-basics', 'embedded-ai', 1, 15, 'HDL and FPGA basics', 'Describe simple hardware in SystemVerilog, test it in simulation and map it onto an FPGA.', 30, array['Harris & Harris, DDCA RISC-V ed., ch. 4 (Hardware Description Languages)', 'Harris & Harris, DDCA RISC-V ed., ch. 5 (Digital Building Blocks: logic arrays) and Appendix A (Digital System Implementation)', 'Arm Education, Introduction to Very Large-Scale Integration Design (HDL/RTL and EDA tools)']::text[], '[{"title":"HDLBits: Verilog practice problems with simulation feedback","url":"https://hdlbits.01xz.net/"}]'::jsonb),
  ('embedded-ai/mcu-architecture', 'embedded-ai', 2, 16, 'MCU architecture', 'Choose a microcontroller and find your way around its cores, memory map, buses and clocks using its datasheets.', 75, array['Yiu, The Definitive Guide to ARM Cortex-M3 and Cortex-M4 Processors 3e, ch. 1–6 and 9', 'Yiu, Definitive Guide to Arm Cortex-M23 and Cortex-M33 Processors, ch. 1 and 3', 'Valvano, Embedded Systems: Introduction to ARM Cortex-M Microcontrollers (Vol. 1), ch. 3', 'Valvano, Embedded Systems: Real-Time Operating Systems for ARM Cortex-M Microcontrollers (Vol. 3), ch. 1', 'White, Making Embedded Systems 2e, ch. 3']::text[], '[]'::jsonb),
  ('embedded-ai/bare-metal-toolchain', 'embedded-ai', 2, 17, 'Bare-metal and toolchain', 'Build, link and boot firmware from scratch, and drive pins by writing hardware registers.', 75, array['White, Making Embedded Systems 2e, ch. 2–4', 'Valvano, Vol. 1, ch. 4 (Introduction to Input/Output) and ch. 5 (Modular Programming)', 'Yiu, Cortex-M3/M4 3e, ch. 2 (Introduction to Embedded Software Development)', 'GNU ld manual, ch. 3 (Linker Scripts)', 'Bryant & O''Hallaron, CS:APP 3e, ch. 7 (Linking)']::text[], '[{"title":"Bare-metal programming guide: from an empty folder to blinky, SysTick and UART without a vendor framework","url":"https://github.com/cpq/bare-metal-programming-guide"},{"title":"CMake Tutorial (steps 1–4), then add a cross-compilation toolchain file","url":"https://cmake.org/cmake/help/latest/guide/tutorial/index.html"}]'::jsonb),
  ('embedded-ai/interrupts-timers-dma', 'embedded-ai', 2, 18, 'Interrupts, timers, DMA', 'Make firmware react to events on time using interrupts, timers, PWM and DMA.', 65, array['Yiu, Cortex-M3/M4 3e, ch. 7 (Exceptions and Interrupts), ch. 8 (Exception Handling in Detail) and §9.5 (The SysTick timer)', 'White, Making Embedded Systems 2e, ch. 4 (Outputs, Inputs, and Timers) and ch. 5 (Interrupts)', 'Valvano, Vol. 1, ch. 9 (Interrupt Programming and Real-time Systems)', 'Valvano, Vol. 3, ch. 7 (High-Speed Interfacing)']::text[], '[{"title":"Zephyr PWM Blinky sample: drive an LED with hardware PWM","url":"https://docs.zephyrproject.org/latest/samples/basic/blinky_pwm/README.html"}]'::jsonb),
  ('embedded-ai/peripherals-connectivity', 'embedded-ai', 2, 19, 'Peripherals and connectivity', 'Talk to sensors, chips and other devices over UART, SPI, I2C, I2S, CAN, USB and wireless links.', 65, array['White, Making Embedded Systems 2e, ch. 7 (Communicating with Peripherals), ch. 8 (Putting Together a System), ch. 10 (Building Connected Devices)', 'Valvano, Vol. 1, ch. 8 (Serial and Parallel Port Interfacing) and ch. 11 (Communication Systems)', 'Arm Education, Embedded Systems Essentials with Arm: Get Practical with Hardware (serial communication modules)', 'Arm Education, Build Your First IoT Application on Arm (connectivity modules)']::text[], '[{"title":"Zephyr UART echo sample: interrupt-driven UART receive","url":"https://docs.zephyrproject.org/latest/samples/drivers/uart/echo_bot/README.html"},{"title":"Zephyr Heart-rate Monitor (Peripheral) sample: a BLE GATT peripheral","url":"https://docs.zephyrproject.org/latest/samples/bluetooth/peripheral_hr/README.html"}]'::jsonb),
  ('embedded-ai/sensors-acquisition', 'embedded-ai', 2, 20, 'Sensors and acquisition', 'Turn real-world signals from ADCs, IMUs, microphones and cameras into clean, correctly sampled data.', 60, array['Lee & Seshia, Introduction to Embedded Systems 2e, ch. 7 (Sensors and Actuators)', 'White, Making Embedded Systems 2e, ch. 8 (Putting Together a System)', 'Valvano, Real-Time Interfacing ebook (ECE445L), ch. 2 (Digital Sampling) and ch. 5 (Audio)', 'Scherz & Monk 4e, ch. 6 (Sensors)']::text[], '[{"title":"Zephyr ADC with devicetree sample: read channels and convert to millivolts","url":"https://docs.zephyrproject.org/latest/samples/drivers/adc/adc_dt/README.html"}]'::jsonb),
  ('embedded-ai/rtos', 'embedded-ai', 2, 21, 'RTOS', 'Structure firmware as prioritised tasks with FreeRTOS or Zephyr and check that every deadline is met.', 90, array['FreeRTOS Kernel Book (github.com/FreeRTOS/FreeRTOS-Kernel-Book), ch. 1–13', 'Zephyr Project documentation: Kernel Services; Devicetree guide; Configuration System (Kconfig)', 'Valvano, Vol. 3 (Real-Time Operating Systems for ARM Cortex-M), ch. 3–5', 'Lee & Seshia 2e, ch. 12 (Scheduling)', 'Yiu, Cortex-M3/M4 3e, ch. 10 (OS Support Features)']::text[], '[{"title":"RTOS sensor project (capstone), step 1: install Zephyr and build Blinky for your board","url":"https://docs.zephyrproject.org/latest/develop/getting_started/index.html"},{"title":"RTOS sensor project, step 2: read an MPU6050 IMU over I2C (start from this sample and add a devicetree overlay for your board)","url":"https://docs.zephyrproject.org/latest/samples/sensor/mpu6050/README.html"},{"title":"RTOS sensor project, step 3: stream samples over UART with interrupt-driven I/O (adapt the UART echo sample)","url":"https://docs.zephyrproject.org/latest/samples/drivers/uart/echo_bot/README.html"},{"title":"RTOS sensor project, step 4: split acquisition, processing and output into threads that hand off with semaphores and queues (see Basic Synchronization)","url":"https://docs.zephyrproject.org/latest/samples/synchronization/README.html"},{"title":"RTOS sensor project, FreeRTOS variant: build the same pipeline starting from the FreeRTOS Kernel Quick Start Guide","url":"https://www.freertos.org/Documentation/01-FreeRTOS-quick-start/01-Beginners-guide/02-Quick-start-guide"},{"title":"FreeRTOS Kernel Book and its examples (tasks, queues, mutexes, interrupts)","url":"https://github.com/FreeRTOS/FreeRTOS-Kernel-Book"}]'::jsonb),
  ('embedded-ai/embedded-linux-edge-socs', 'embedded-ai', 2, 22, 'Embedded Linux and edge SoCs', 'Bring up and develop on Linux-based edge computers such as Raspberry Pi and Jetson, and understand their AI accelerators.', 60, array['Simmonds & Vasquez, Mastering Embedded Linux Programming 3e, ch. 3–7, 11, 13, 19', 'mlsysbook.ai, Machine Learning Systems Vol. I, ch. 2 (System Paradigms) and ch. 11 (Hardware Acceleration)', 'Buildroot user manual; Yocto Project Quick Build']::text[], '[{"title":"Buildroot quick start: build a minimal image for QEMU or a Raspberry Pi defconfig","url":"https://buildroot.org/downloads/manual/manual.html"},{"title":"Yocto Project Quick Build: build an image and boot it in QEMU","url":"https://docs.yoctoproject.org/brief-yoctoprojectqs/index.html"}]'::jsonb),
  ('embedded-ai/low-power-design', 'embedded-ai', 2, 23, 'Low-power design', 'Make a battery-powered device last by budgeting, reducing and measuring its power use.', 60, array['White, Making Embedded Systems 2e, ch. 13 (Reducing Power Consumption)', 'Warden & Situnayake, TinyML, ch. 15 (Optimizing Latency) and ch. 16 (Optimizing Energy Usage)', 'Yiu, Cortex-M3/M4 3e, ch. 9 (Low Power and System Control Features)', 'FreeRTOS Kernel Book, ch. 11 (Low Power Support)']::text[], '[]'::jsonb),
  ('embedded-ai/debug-test-secure-firmware', 'embedded-ai', 2, 24, 'Debug, test, secure firmware', 'Find bugs on real hardware, test firmware automatically, and ship updates that boot securely.', 50, array['White, Making Embedded Systems 2e, ch. 9 (Getting Into Trouble) and ch. 10 (Building Connected Devices)', 'Yiu, Cortex-M3/M4 3e, ch. 11 (Memory Protection Unit) and ch. 12 (Fault Exceptions and Fault Handling)', 'Yiu, Definitive Guide to Arm Cortex-M23 and Cortex-M33 Processors, ch. 7, 16, 18, 22', 'MIT Missing Semester 2026: Debugging and Profiling; Code Quality']::text[], '[{"title":"Unity: unit-test a ring buffer or a sensor-conversion module on your PC","url":"https://github.com/ThrowTheSwitch/Unity"},{"title":"MCUboot documentation: sign an image and run a test upgrade","url":"https://docs.mcuboot.com/"}]'::jsonb),
  ('embedded-ai/linear-algebra', 'embedded-ai', 3, 25, 'Linear algebra', 'Work with vectors, matrices and tensors: multiply them, count what that costs, and compress a matrix with the SVD.', 110, array['Strang, Introduction to Linear Algebra (6th ed., 2023), ch. 1–4, 6–7', 'Deisenroth, Faisal & Ong, Mathematics for Machine Learning (MML, 2020), ch. 2–4', 'Zhang et al., Dive into Deep Learning (D2L), §2.1 and §2.3']::text[], '[]'::jsonb),
  ('embedded-ai/calculus-optimization', 'embedded-ai', 3, 26, 'Calculus and optimization', 'Take derivatives of the functions inside a model, follow the gradient downhill, and know when that search is guaranteed to work.', 95, array['MML, ch. 5 (Vector Calculus) and ch. 7 (Continuous Optimization)', 'D2L, §2.4–2.5, §22.3–22.4 and ch. 12']::text[], '[{"title":"micrograd: build a tiny reverse-mode autodiff engine","url":"https://github.com/karpathy/micrograd"}]'::jsonb),
  ('embedded-ai/probability-statistics', 'embedded-ai', 3, 27, 'Probability and statistics', 'Reason about uncertainty: compute probabilities, use Bayes'' rule, fit parameters to data, and put error bars on a measured accuracy.', 90, array['Blitzstein & Hwang, Introduction to Probability (2nd ed., 2019), ch. 1–10', 'MML, ch. 6 and §8.3', 'D2L, §2.6 and §22.6–22.10']::text[], '[]'::jsonb),
  ('embedded-ai/information-theory', 'embedded-ai', 3, 28, 'Information theory', 'Measure information in bits, see why cross-entropy is the standard loss, and estimate how few bits a model''s weights really need.', 40, array['MacKay, Information Theory, Inference, and Learning Algorithms (2003), ch. 1–2, 4–6', 'D2L, §22.11']::text[], '[]'::jsonb),
  ('embedded-ai/signals-dsp', 'embedded-ai', 3, 29, 'Signals and DSP', 'Turn sensor readings into clean digital signals: sample without aliasing, convolve, filter, and see a signal''s frequencies with the FFT.', 85, array['Smith, The Scientist and Engineer''s Guide to Digital Signal Processing, ch. 3, 5–12, 14–21', 'Oppenheim & Willsky, Signals and Systems (2nd ed., 1997), ch. 1–7, 10']::text[], '[]'::jsonb),
  ('embedded-ai/sensor-feature-extraction', 'embedded-ai', 3, 30, 'Sensor feature extraction', 'Turn raw audio, images and motion data into the small feature arrays that tiny models expect, one window at a time.', 50, array['Warden & Situnayake, TinyML (O''Reilly, 2019), ch. 7–12', 'Edge Impulse docs: processing blocks (spectrogram, MFE, MFCC, image, spectral analysis)', 'Smith, DSP Guide, ch. 22']::text[], '[{"title":"Edge Impulse: end-to-end motion recognition with spectral features","url":"https://docs.edgeimpulse.com/tutorials/end-to-end/motion-recognition"}]'::jsonb),
  ('embedded-ai/numerical-computing', 'embedded-ai', 3, 31, 'Numerical computing', 'Keep results accurate in finite precision and see how convolutions are turned into fast matrix multiplies.', 30, array['Goldberg, What Every Computer Scientist Should Know About Floating-Point Arithmetic (ACM Computing Surveys, 1991)', 'Goodfellow, Bengio & Courville, Deep Learning (2016), ch. 4', 'Sze, Chen, Yang & Emer, Efficient Processing of Deep Neural Networks: A Tutorial and Survey (Proc. IEEE, 2017)', 'Lavin & Gray, Fast Algorithms for Convolutional Neural Networks (CVPR 2016)']::text[], '[]'::jsonb),
  ('embedded-ai/ml-fundamentals', 'embedded-ai', 4, 32, 'ML fundamentals', 'Frame a learning problem, split the data honestly, fit simple linear models, and judge a classifier with the right metric.', 80, array['Géron, Hands-On Machine Learning with Scikit-Learn, Keras & TensorFlow (3rd ed., 2022), ch. 1–4', 'Prince, Understanding Deep Learning (UDL, MIT Press 2023), ch. 1–2, 8–9', 'D2L, ch. 3–4']::text[], '[]'::jsonb),
  ('embedded-ai/classical-ml-on-devices', 'embedded-ai', 4, 33, 'Classical ML on devices', 'Use small classic models (nearest neighbors, trees, SVMs, k-means and PCA) that often fit a microcontroller''s budget better than a neural network.', 50, array['Géron (3rd ed.), ch. 5–9', 'MML, ch. 10–12', 'Edge Impulse docs: K-means and GMM anomaly-detection blocks']::text[], '[]'::jsonb),
  ('embedded-ai/neural-network-basics', 'embedded-ai', 4, 34, 'Neural-network basics', 'Build a neural network from layers and activations, pick a loss, and compute every gradient with backpropagation.', 80, array['UDL, ch. 3–7', 'D2L, ch. 5', 'Stanford CS231n course notes: Backpropagation; Neural Networks Parts 1–3']::text[], '[{"title":"micrograd: an autograd engine and small MLP built from scratch","url":"https://github.com/karpathy/micrograd"},{"title":"Stanford CS231n notes: minimal neural network case study","url":"https://cs231n.github.io/"}]'::jsonb),
  ('embedded-ai/training-deep-networks', 'embedded-ai', 4, 35, 'Training deep networks', 'Train deep networks reliably: choose an optimizer and learning-rate schedule, normalize and regularize, use mixed precision, and debug runs that fail.', 75, array['D2L, ch. 12, §5.6, §8.5 and §14.1', 'UDL, ch. 6, 9 and 11', 'Micikevicius et al., Mixed Precision Training (ICLR 2018)']::text[], '[]'::jsonb),
  ('embedded-ai/pytorch-in-practice', 'embedded-ai', 4, 36, 'PyTorch in practice', 'Write real PyTorch (tensors, autograd, modules and a training loop) and export the trained model for deployment.', 70, array['PyTorch tutorials: Learn the Basics', 'PyTorch docs: Autograd mechanics; torch.export; torch.onnx; Automatic Mixed Precision', 'LiteRT docs: post-training quantization', 'Géron (3rd ed.), ch. 10']::text[], '[{"title":"PyTorch tutorial: Learn the Basics (tensors to a full training loop)","url":"https://docs.pytorch.org/tutorials/beginner/basics/intro.html"}]'::jsonb),
  ('embedded-ai/cnns-vision', 'embedded-ai', 4, 37, 'CNNs and vision', 'Build convolutional networks for images, count their parameters and operations, and use the efficient blocks and detectors that run on edge devices.', 90, array['Stanford CS231n course notes: Convolutional Neural Networks; Transfer Learning', 'D2L, ch. 7–8 and §14.1–14.8', 'UDL, ch. 10–11']::text[], '[{"title":"MLPerf Tiny reference training code (image classification on CIFAR-10)","url":"https://github.com/mlcommons/tiny/tree/master/benchmark"}]'::jsonb),
  ('embedded-ai/sequence-audio-models', 'embedded-ai', 4, 38, 'Sequence and audio models', 'Model signals that unfold over time and build the small keyword-spotting networks that listen continuously on microcontrollers.', 40, array['D2L, ch. 9–10', 'Warden & Situnayake, TinyML, ch. 7–8', 'mlsysbook.ai Vol. I, §6.5']::text[], '[{"title":"MLPerf Tiny keyword-spotting reference training (DS-CNN on Speech Commands)","url":"https://github.com/mlcommons/tiny/tree/master/benchmark/training/keyword_spotting"}]'::jsonb),
  ('embedded-ai/transformers', 'embedded-ai', 4, 39, 'Transformers', 'Understand attention and the transformer block, and work out what a transformer costs in operations and memory, including the KV cache.', 90, array['UDL, ch. 12', 'Stanford CS224n (Winter 2026), lectures ''Transformers'' and ''Pretraining''', 'D2L, ch. 11', 'Vaswani et al., Attention Is All You Need (NeurIPS 2017)']::text[], '[{"title":"The Annotated Transformer (line-by-line implementation)","url":"https://nlp.seas.harvard.edu/annotated-transformer/"},{"title":"nanoGPT: train and fine-tune a small GPT","url":"https://github.com/karpathy/nanoGPT"}]'::jsonb),
  ('embedded-ai/generative-ai-llms', 'embedded-ai', 4, 40, 'Generative AI and LLMs', 'Follow how a large language model is built (tokens, pretraining, scaling, fine-tuning and preference tuning), how it generates text, and how diffusion models generate images.', 75, array['Raschka, Build a Large Language Model (From Scratch) (Manning, 2024), ch. 1–7 and App. E', 'UDL, ch. 12, 15, 17–18', 'Stanford CS224n (Winter 2026), lectures ''Pretraining (Scaling, Systems, Data)'' and ''Post-training (RLHF, SFT, DPO)''']::text[], '[{"title":"Raschka, LLMs-from-scratch: build, pretrain and fine-tune a GPT","url":"https://github.com/rasbt/LLMs-from-scratch"}]'::jsonb),
  ('embedded-ai/efficiency-metrics', 'embedded-ai', 5, 41, 'Efficiency metrics', 'Measure what a model costs in operations, memory, energy and time, and use a simple roofline to see what limits its speed.', 85, array['MIT 6.5940 (Fall 2024) Lectures 1–2: Introduction; Basics of Deep Learning', 'Sze, Chen, Yang & Emer, Efficient Processing of Deep Neural Networks: A Tutorial and Survey (Proc. IEEE, 2017)', 'Horowitz, Computing''s Energy Problem (and What We Can Do About It) (ISSCC 2014)', 'Williams, Waterman & Patterson, Roofline: An Insightful Visual Performance Model for Multicore Architectures (CACM, 2009)', 'mlsysbook.ai Vol. I, ch. 11 (§11.5–11.7)']::text[], '[]'::jsonb),
  ('embedded-ai/tinyml-workflow', 'embedded-ai', 5, 42, 'TinyML workflow and applications', 'Take a TinyML idea from data to a working device for keyword spotting, person detection, gestures and anomaly detection, using the Edge Impulse workflow.', 70, array['Warden & Situnayake, TinyML (O''Reilly, 2019), ch. 1, 7–12 and 14', 'HarvardX TinyML Professional Certificate (Fundamentals, Applications and Deploying TinyML; courseware at github.com/tinyMLx/courseware)', 'Edge Impulse docs: impulse design, EON Tuner, EON Compiler']::text[], '[{"title":"Edge Impulse tutorial: keyword spotting (collect, train, deploy)","url":"https://docs.edgeimpulse.com/tutorials/end-to-end/keyword-spotting"},{"title":"Edge Impulse tutorial: motion (gesture) recognition","url":"https://docs.edgeimpulse.com/tutorials/end-to-end/motion-recognition"},{"title":"HarvardX TinyML Colab notebooks","url":"https://github.com/tinyMLx/colabs"}]'::jsonb),
  ('embedded-ai/pruning-sparsity', 'embedded-ai', 5, 43, 'Pruning and sparsity', 'Remove the weights and channels a network does not need, and know which kinds of sparsity actually make it smaller or faster on real hardware.', 85, array['MIT 6.5940 (Fall 2024 and Fall 2026) Lectures 3–4: Pruning and Sparsity', 'Han et al., Learning both Weights and Connections for Efficient Neural Networks (NIPS 2015)', 'Han, Mao & Dally, Deep Compression (ICLR 2016)', 'mlsysbook.ai Vol. I, §10.2.1 and §10.4.2']::text[], '[{"title":"MIT 6.5940 (Fall 2024) Lab 1: Pruning (Colab)","url":"https://colab.research.google.com/drive/1Fagq3JQBzCizodyxpHKvWDzfCC7F1RWN"},{"title":"PyTorch tutorial: pruning with torch.nn.utils.prune","url":"https://docs.pytorch.org/tutorials/intermediate/pruning_tutorial.html"}]'::jsonb),
  ('embedded-ai/quantization-1', 'embedded-ai', 5, 44, 'Quantization I', 'Store and compute with 8-bit integers instead of 32-bit floats: the scale and zero-point math, calibration, and integer-only kernels.', 100, array['Jacob et al., Quantization and Training of Neural Networks for Efficient Integer-Arithmetic-Only Inference (CVPR 2018)', 'Nagel et al., A White Paper on Neural Network Quantization (arXiv 2106.08295, 2021)', 'MIT 6.5940 Lecture 5: Quantization (Part I)', 'LiteRT docs: quantization specification; post-training quantization']::text[], '[{"title":"MIT 6.5940 (Fall 2024) Lab 2: Quantization (Colab)","url":"https://colab.research.google.com/drive/11IBla1q1McoZ2oCANCGHns8VtzG5nCMP"}]'::jsonb),
  ('embedded-ai/quantization-2', 'embedded-ai', 5, 45, 'Quantization II', 'Go below 8 bits and train for it: quantization-aware training, mixed precision, 4-bit and binary weights, FP8, and quantizing LLMs.', 70, array['MIT 6.5940 Lecture 6: Quantization (Part II), and Fall 2024 Lecture 13: Efficient LLM Deployment', 'Nagel et al. (2021), §4', 'Micikevicius et al., FP8 Formats for Deep Learning (arXiv 2209.05433, 2022)']::text[], '[{"title":"MIT 6.5940 (Fall 2024) Lab 4: LLM compression (Colab)","url":"https://colab.research.google.com/drive/16H9RvSg4XIF35X3fLGQUVwAE9ccvDj14"},{"title":"TensorFlow Model Optimization guide: quantization-aware training","url":"https://www.tensorflow.org/model_optimization/guide/quantization/training"}]'::jsonb),
  ('embedded-ai/efficient-architectures-nas', 'embedded-ai', 5, 46, 'Efficient architectures and NAS', 'Design networks that are efficient by construction, and let a search find the best architecture for a given device''s latency and memory.', 80, array['MIT 6.5940 Lectures 7–8: Neural Architecture Search (Parts I–II), and Lecture 10: MCUNet', 'Howard et al., MobileNets (arXiv 1704.04861, 2017); Sandler et al., MobileNetV2 (CVPR 2018)', 'Tan & Le, EfficientNet (ICML 2019)', 'Cai et al., Once-for-All (ICLR 2020)', 'Lin et al., MCUNet: Tiny Deep Learning on IoT Devices (NeurIPS 2020)', 'mlsysbook.ai Vol. I, §10.2.4–10.2.5']::text[], '[{"title":"MIT 6.5940 (Fall 2024) Lab 3: Neural architecture search (Colab)","url":"https://colab.research.google.com/drive/1xKReLBHVS6bkFbYkfi-Ky3C4loQmG6Yc"},{"title":"Once-for-All: pretrained supernets and specialization code","url":"https://github.com/mit-han-lab/once-for-all"}]'::jsonb),
  ('embedded-ai/distillation-low-rank', 'embedded-ai', 5, 47, 'Distillation and low-rank', 'Train a small student network to imitate a large teacher, and split big weight matrices into smaller low-rank pieces.', 40, array['MIT 6.5940 Lecture 9: Knowledge Distillation', 'Hinton, Vinyals & Dean, Distilling the Knowledge in a Neural Network (arXiv 1503.02531, 2015)', 'mlsysbook.ai Vol. I, §10.2.2–10.2.3', 'Hu et al., LoRA: Low-Rank Adaptation of Large Language Models (ICLR 2022)']::text[], '[]'::jsonb),
  ('embedded-ai/mcu-inference-engines', 'embedded-ai', 5, 48, 'MCU inference engines', 'Run quantized models on microcontrollers: how LiteRT for Microcontrollers manages memory, how optimized kernels and code generators speed it up, and how to fit models into tiny SRAM.', 110, array['MIT 6.5940 Lectures 10–11: MCUNet; TinyEngine and Parallel Processing', 'David et al., TensorFlow Lite Micro: Embedded Machine Learning on TinyML Systems (MLSys 2021)', 'LiteRT for Microcontrollers docs: overview; get started', 'CMSIS-NN (GitHub: ARM-software/CMSIS-NN)', 'Lin et al., MCUNetV2: Memory-Efficient Patch-based Inference for Tiny Deep Learning (NeurIPS 2021)', 'Arm Ethos-U Vela compiler (PyPI: ethos-u-vela)']::text[], '[{"title":"Capstone: keyword spotting on a Cortex-M board, starting from the TFLM micro_speech example","url":"https://github.com/tensorflow/tflite-micro/tree/main/tensorflow/lite/micro/examples/micro_speech"},{"title":"Capstone hardware path: micro_speech on the Arduino Nano 33 BLE Sense (Cortex-M4F)","url":"https://github.com/tensorflow/tflite-micro-arduino-examples/tree/main/examples/micro_speech"},{"title":"Capstone alternative: Edge Impulse keyword-spotting tutorial (deploy to a Cortex-M board)","url":"https://docs.edgeimpulse.com/tutorials/end-to-end/keyword-spotting"},{"title":"TinyEngine: MIT''s memory-efficient MCU inference library","url":"https://github.com/mit-han-lab/tinyengine"}]'::jsonb),
  ('embedded-ai/edge-soc-deployment', 'embedded-ai', 5, 49, 'Phone and edge-SoC deployment', 'Deploy models on phones and edge boards through the main runtimes, sending each part of the model to the CPU, GPU or NPU that can run it.', 70, array['ExecuTorch docs: How ExecuTorch works; Backends overview; .pte file format', 'LiteRT docs: overview; delegates', 'ONNX Runtime docs: execution providers; quantization', 'coremltools docs: converting PyTorch models', 'NVIDIA TensorRT docs: quick start guide', 'mlsysbook.ai Vol. I, §11.10 and §13.7–13.8']::text[], '[{"title":"ExecuTorch: getting started (export to .pte and run)","url":"https://docs.pytorch.org/executorch/stable/getting-started.html"}]'::jsonb),
  ('embedded-ai/benchmarking', 'embedded-ai', 5, 50, 'Benchmarking', 'Measure accuracy, latency and energy the way MLPerf does, and report results that others can trust and reproduce.', 40, array['Banbury et al., MLPerf Tiny Benchmark (arXiv 2106.07597, 2021)', 'mlsysbook.ai Vol. I, ch. 12 (Benchmarking)', 'MLCommons Inference rules: scenarios (github.com/mlcommons/inference_policies)']::text[], '[{"title":"MLPerf Tiny benchmark repository (reference models, training and runner)","url":"https://github.com/mlcommons/tiny"}]'::jsonb),
  ('embedded-ai/cpu-performance', 'embedded-ai', 6, 51, 'CPU performance engineering', 'You will be able to find where a program spends its time on a CPU and speed up ML kernels with vector instructions, cache-friendly loops and a well-structured matrix multiply.', 85, array['Hennessy, Patterson & Kozyrakis, Computer Architecture: A Quantitative Approach, 7th ed. (Dec 2025), ch. 1, 2, 4 and App. B, G', 'Bryant & O''Hallaron, Computer Systems: A Programmer''s Perspective, 3rd ed., ch. 1, 5, 6 (§1.9.1, §5.7–5.9, §5.14, §6.6)', 'MIT 6.172 Performance Engineering of Software Systems (OCW, Fall 2018)', 'MIT 6.5930 reading list (Spring 2026): Kernel Computation lectures (CPU, Vectorization, Memory)']::text[], '[{"title":"How to Optimize GEMM: step-by-step tutorial","url":"https://github.com/flame/how-to-optimize-gemm/wiki"},{"title":"BLIS framework (study its micro-kernels)","url":"https://github.com/flame/blis"},{"title":"CMSIS-NN int8 kernels for Cortex-M","url":"https://github.com/ARM-software/CMSIS-NN"},{"title":"MIT 6.172 Performance Engineering (OCW) projects","url":"https://ocw.mit.edu/courses/6-172-performance-engineering-of-software-systems-fall-2018/"}]'::jsonb),
  ('embedded-ai/gpus-parallel-programming', 'embedded-ai', 6, 52, 'GPUs and parallel programming', 'You will be able to write and tune GPU kernels in CUDA and Triton by reasoning about warps, memory access patterns, occupancy and tensor cores.', 80, array['Hwu, Kirk & El Hajj, Programming Massively Parallel Processors, 4th ed. (2022), ch. 1–6, 10–11, 16, 20', 'NVIDIA CUDA Programming Guide and CUDA C++ Best Practices Guide (docs.nvidia.com/cuda)', 'Hennessy, Patterson & Kozyrakis, CA:AQA 7e, ch. 4 (GPUs)', 'Tillet, Kung & Cox, Triton, MAPL 2019']::text[], '[{"title":"Triton tutorials: vector add, fused softmax, matrix multiplication","url":"https://triton-lang.org/main/getting-started/tutorials/index.html"},{"title":"How to optimize a CUDA matmul kernel, step by step","url":"https://siboehm.com/articles/22/CUDA-MMM"},{"title":"CUDA Programming Guide","url":"https://docs.nvidia.com/cuda/cuda-programming-guide/"},{"title":"GPU MODE lecture series","url":"https://github.com/gpu-mode/lectures"}]'::jsonb),
  ('embedded-ai/framework-internals', 'embedded-ai', 6, 53, 'Framework internals', 'You will be able to explain what a PyTorch-style framework does between a line of model code and a running kernel, and how trained models are saved for deployment.', 55, array['CMU 10-414/714 Deep Learning Systems (dlsyscourse.org), lectures 4–5, 7, 9, 12–13, 23', 'Janapa Reddi et al., Machine Learning Systems (mlsysbook.ai) Vol. I, ch. 7 (ML Frameworks)', 'Ansel et al., PyTorch 2, ASPLOS 2024']::text[], '[{"title":"CMU Deep Learning Systems assignments: build the needle framework","url":"https://dlsyscourse.org/assignments/"},{"title":"MiniTorch: build a tensor library with autodiff","url":"https://minitorch.github.io/"},{"title":"micrograd: a tiny autograd engine","url":"https://github.com/karpathy/micrograd"}]'::jsonb),
  ('embedded-ai/ml-compilers', 'embedded-ai', 6, 54, 'ML compilers', 'You will be able to explain how ML compilers turn a model graph into fast code for a specific device, and use TVM, MLIR-based tools, XLA, IREE and ExecuTorch.', 110, array['Chen et al., Machine Learning Compilation course notes (mlc.ai, 2022), ch. 1–7', 'Chen et al., TVM: An Automated End-to-End Optimizing Compiler for Deep Learning, OSDI 2018', 'Lattner et al., MLIR: Scaling Compiler Infrastructure for Domain Specific Computation, CGO 2021', 'Ragan-Kelley et al., Halide, PLDI 2013', 'Zheng et al., Ansor, OSDI 2020', 'Stanford CS217 (Winter 2026), Compilers and software stack lectures (parts 1–2)']::text[], '[{"title":"MLC course (2022): episodes, notebooks and exercises","url":"https://mlc.ai/summer22/schedule"},{"title":"Apache TVM documentation (Relax, TensorIR, MetaSchedule)","url":"https://tvm.apache.org/docs/"},{"title":"Halide tutorials","url":"https://halide-lang.org/"},{"title":"IREE: MLIR-based compiler and runtime","url":"https://iree.org/"}]'::jsonb),
  ('embedded-ai/memory-planning', 'embedded-ai', 6, 55, 'Memory planning', 'You will be able to fit a model''s working memory into a small RAM by planning when each tensor lives, where it is stored and how data streams in.', 45, array['MIT 6.5940 TinyML and Efficient Deep Learning Computing (Fall 2024 and Fall 2026), L10 MCUNet and L11 TinyEngine and Parallel Processing', 'Lin et al., MCUNetV2: Memory-Efficient Patch-based Inference for Tiny Deep Learning, NeurIPS 2021', 'Lin et al., MCUNet: Tiny Deep Learning on IoT Devices, NeurIPS 2020']::text[], '[{"title":"TinyEngine (MCUNet inference engine) source","url":"https://github.com/mit-han-lab/tinyengine"},{"title":"ExecuTorch memory planning documentation","url":"https://docs.pytorch.org/executorch/stable/compiler-memory-planning.html"},{"title":"TensorFlow Lite Micro (study the arena planner)","url":"https://github.com/tensorflow/tflite-micro"}]'::jsonb),
  ('embedded-ai/accelerator-fundamentals', 'embedded-ai', 6, 56, 'Accelerator fundamentals', 'You will be able to explain why custom ML chips beat general-purpose processors and how their compute arrays, on-chip memories and interconnects are built.', 85, array['Sze, Chen, Yang & Emer, Efficient Processing of Deep Neural Networks (2020), ch. 1, 3, 5 and 7', 'Jouppi et al., In-Datacenter Performance Analysis of a Tensor Processing Unit, ISCA 2017', 'Hennessy, Patterson & Kozyrakis, CA:AQA 7e, ch. 7 (Domain-Specific Architectures)', 'Stanford CS217 Hardware Accelerators for Machine Learning (Winter 2026): systolic arrays, vector and scalar units, memory systems, interconnects', 'MIT 6.5930/1 Hardware Architecture for Deep Learning (Spring 2026 reading list): Accelerator Architecture']::text[], '[{"title":"SCALE-Sim v3 systolic-array simulator","url":"https://github.com/scalesim-project/scale-sim-v3"},{"title":"Gemmini systolic-array generator","url":"https://github.com/ucb-bar/gemmini"}]'::jsonb),
  ('embedded-ai/dataflow-mapping', 'embedded-ai', 6, 57, 'Dataflow and mapping', 'You will be able to describe any layer as a loop nest, reason about how a chip reuses data, and search for the schedule that minimizes energy and time, using Timeloop.', 100, array['Sze et al., ch. 2, 5 and 6', 'MIT 6.5930/1 Hardware Architecture for Deep Learning (Spring 2026), L03–L07, L13 and recitations (AccelForge tutorial, looptree)', 'Parashar et al., Timeloop: A Systematic Approach to DNN Accelerator Evaluation, ISPASS 2019', 'Wu, Emer & Sze, Accelergy, ICCAD 2019', 'Kwon et al., MAESTRO, MICRO 2019']::text[], '[{"title":"Capstone, step 1a: compile a model with Apache TVM","url":"https://tvm.apache.org/docs/"},{"title":"Capstone, step 1b (alternative): export and lower the model with ExecuTorch","url":"https://docs.pytorch.org/executorch/stable/getting-started.html"},{"title":"Capstone, step 2: map one of its conv layers in Timeloop (exercises)","url":"https://github.com/Accelergy-Project/timeloop-accelergy-exercises"},{"title":"AccelForge (Timeloop successor) documentation","url":"https://accelergy-project.github.io/accelforge/"}]'::jsonb),
  ('embedded-ai/edge-npus', 'embedded-ai', 6, 58, 'Edge NPUs and SoCs', 'You will be able to compare the neural accelerators in microcontrollers and phones, prepare a model for one, and tell advertised TOPS from real performance.', 75, array['Arm Newsroom, Arm Ethos-U85 (9 Apr 2024); Arm Ethos-U55 and Ethos-U65 product pages (arm.com)', 'STMicroelectronics press release P4665, STM32N6 (10 Dec 2024)', 'Janapa Reddi et al., mlsysbook.ai Vol. I, ch. 11 (Hardware Acceleration)', 'Sze et al., ch. 3']::text[], '[{"title":"Arm Ethos-U Vela compiler","url":"https://pypi.org/project/ethos-u-vela/"},{"title":"ExecuTorch Arm Ethos-U backend","url":"https://docs.pytorch.org/executorch/stable/backends-arm-ethos-u.html"},{"title":"ST Edge AI Developer Cloud: benchmark on real STM32 boards","url":"https://stedgeai-dc.st.com/"},{"title":"Qualcomm AI Hub: profile on Snapdragon devices","url":"https://aihub.qualcomm.com/"}]'::jsonb),
  ('embedded-ai/fpga-acceleration', 'embedded-ai', 6, 59, 'FPGA acceleration', 'You will be able to build ML accelerators on FPGAs with high-level synthesis and choose between streaming designs, overlays and existing tools such as FINN, hls4ml and Vitis AI.', 65, array['Kastner, Matai & Neuendorffer, Parallel Programming for FPGAs (arXiv:1805.03648), ch. 1, 2, 7 and 12', 'AMD Vitis HLS User Guide (UG1399)', 'Umuroglu et al., FINN: A Framework for Fast, Scalable Binarized Neural Network Inference, FPGA 2017', 'Duarte et al., Fast inference of deep neural networks in FPGAs for particle physics (hls4ml), JINST 13, P07027, 2018', 'Stanford CS217 (Winter 2026): HLS lectures and labs on cloud FPGAs']::text[], '[{"title":"Parallel Programming for FPGAs: book source and examples","url":"https://github.com/KastnerRG/pp4fpgas"},{"title":"Vitis HLS introductory examples","url":"https://github.com/Xilinx/Vitis-HLS-Introductory-Examples"},{"title":"FINN dataflow compiler","url":"https://github.com/Xilinx/finn"},{"title":"hls4ml","url":"https://github.com/fastmachinelearning/hls4ml"}]'::jsonb),
  ('embedded-ai/deployment-co-optimization', 'embedded-ai', 6, 60, 'Deployment co-optimization', 'You will be able to split a model across a device''s processors, make its integer arithmetic match the hardware exactly, and predict latency before you deploy.', 50, array['Janapa Reddi et al., mlsysbook.ai Vol. I, ch. 10 (Model Compression), ch. 11 (Hardware Acceleration), ch. 12 (Benchmarking)', 'Stanford CS217 Hardware Accelerators for Machine Learning (Winter 2026): compilers and software stack, HW1 and HW3', 'TOSA specification v1.1.0 (arm.github.io/tosa-specification)', 'ExecuTorch documentation: backend delegation and partitioners']::text[], '[{"title":"nn-Meter latency predictor","url":"https://github.com/microsoft/nn-Meter"},{"title":"Qualcomm AI Hub: per-layer profiling on devices","url":"https://aihub.qualcomm.com/"}]'::jsonb),
  ('embedded-ai/graduate-architecture', 'embedded-ai', 7, 61, 'Graduate architecture', 'You will be able to answer qualifying-exam questions on how modern processors execute instructions out of order, predict branches, keep caches coherent, order memory operations and use DRAM.', 90, array['Hennessy, Patterson & Kozyrakis, Computer Architecture: A Quantitative Approach, 7th ed. (Dec 2025), ch. 1–5 and App. B, C', 'Nagarajan, Sorin, Hill & Wood, A Primer on Memory Consistency and Cache Coherence, 2nd ed. (2020)', 'University of Wisconsin–Madison Computer Architecture PhD qualifying exam, Fall 2020 (six questions)', 'Georgia Tech PhD CS computer architecture body of knowledge: CS 6290 and CS 7290 (advanced microarchitecture)']::text[], '[{"title":"Learning gem5 tutorial","url":"https://www.gem5.org/documentation/learning_gem5/introduction/"},{"title":"ChampSim: branch-predictor and prefetcher studies","url":"https://github.com/ChampSim/ChampSim"}]'::jsonb),
  ('embedded-ai/sparse-accelerators', 'embedded-ai', 7, 62, 'Sparse accelerators', 'You will be able to design and evaluate hardware that skips work on zeros, from compressed formats to load balancing, and model it with Sparseloop.', 60, array['Sze et al., §8.1–8.3', 'MIT 6.5930/1 (Spring 2026), L07 Sparsity and L08–L10 Sparse Architectures 1–3', 'Wu et al., Sparseloop: An Analytical Approach to Sparse Tensor Accelerator Modeling, MICRO 2022']::text[], '[{"title":"Timeloop and Sparseloop source","url":"https://github.com/Accelergy-Project/timeloop"}]'::jsonb),
  ('embedded-ai/numerics-co-design', 'embedded-ai', 7, 63, 'Numerics co-design', 'You will be able to choose and justify number formats for ML hardware, from block floating point to OCP MX and NVFP4, including how accumulators, rounding and outliers affect accuracy.', 60, array['Sze et al., ch. 7', 'OCP Microscaling Formats (MX) Specification v1.0 (Sep 2023), §5–6', 'Rouhani et al., Microscaling Data Formats for Deep Learning, arXiv:2310.10537, 2023', 'MIT 6.5930 (Spring 2026), L12 Numeric Precision', 'Stanford CS217 (Winter 2026), Quantization lecture and HW2 (MXFP prologue vs epilogue cost)']::text[], '[{"title":"microxcaling: MX format emulation library (PyTorch)","url":"https://github.com/microsoft/microxcaling"}]'::jsonb),
  ('embedded-ai/hw-algorithm-co-design', 'embedded-ai', 7, 64, 'Hardware/algorithm co-design', 'You will be able to search jointly over model and hardware designs, use fast cost models to guide the search, and present results as honest trade-off curves.', 55, array['Sze et al., ch. 3 and ch. 9', 'Harvard CS249r / Janapa Reddi et al., mlsysbook.ai Vol. I, ch. 10 and 12; Vol. II, ch. 5 and 6', 'Georgia Tech ECE/CS 8803 HML, Hardware Software Co-Design for Machine Learning Systems (Spring 2025): Labs 2–5', 'Lin et al., MCUNet, NeurIPS 2020']::text[], '[{"title":"Once-for-All: hardware-aware NAS","url":"https://github.com/mit-han-lab/once-for-all"},{"title":"ASTRA-sim distributed ML system simulator","url":"https://astra-sim.github.io/"},{"title":"SCALE-Sim v3 for accelerator design-space sweeps","url":"https://github.com/scalesim-project/scale-sim-v3"}]'::jsonb),
  ('embedded-ai/on-device-training', 'embedded-ai', 7, 65, 'On-device training', 'You will be able to make a model keep learning on the device itself by cutting the memory cost of training, from bias-only updates to training in 256 KB and federated learning.', 70, array['MIT 6.5940 TinyML and Efficient Deep Learning Computing (Fall 2024), L21 On-Device Training and Transfer Learning', 'Zhu et al., PockEngine: Sparse and Efficient Fine-tuning in a Pocket, MICRO 2023', 'Lin et al., On-Device Training Under 256KB Memory, NeurIPS 2022', 'Cai et al., TinyTL, NeurIPS 2020', 'Janapa Reddi et al., mlsysbook.ai Vol. II, ch. 11 (Edge Intelligence)']::text[], '[{"title":"tiny-training: on-device training under 256 KB","url":"https://github.com/mit-han-lab/tiny-training"},{"title":"Flower federated learning framework","url":"https://flower.ai/"}]'::jsonb),
  ('embedded-ai/emerging-technologies', 'embedded-ai', 7, 66, 'Emerging technologies', 'You will be able to judge new kinds of ML hardware (analog and in-memory compute, neuromorphic chips, chiplets, approximate computing) by their real system-level gains.', 50, array['Sze et al., ch. 10', 'MIT 6.5930 (Spring 2026), L11 Advanced Technologies', 'Stanford CS217 (Winter 2026), Memory-centric computing lectures (parts 1–2)']::text[], '[{"title":"DNN+NeuroSim compute-in-memory simulator","url":"https://github.com/neurosim/DNN_NeuroSim_V1.4"},{"title":"Lava neuromorphic computing framework","url":"https://github.com/lava-nc/lava"}]'::jsonb),
  ('embedded-ai/trustworthy-embedded-ai', 'embedded-ai', 7, 67, 'Trustworthy embedded AI', 'You will be able to analyse how an embedded ML system can be attacked or fail, protect it with hardware and software measures, and account for its privacy and carbon costs.', 50, array['Janapa Reddi et al., mlsysbook.ai Vol. II, ch. 13 (Security & Privacy), ch. 14 (Robust AI), ch. 15 (Sustainable AI), ch. 16 (Responsible AI)', 'Georgia Tech CS 7292 Reliability and Security in Computer Architecture (body-of-knowledge elective)']::text[], '[{"title":"Adversarial Robustness Toolbox","url":"https://github.com/Trusted-AI/adversarial-robustness-toolbox"},{"title":"CodeCarbon: measure the emissions of ML workloads","url":"https://codecarbon.io/"}]'::jsonb),
  ('embedded-ai/modeling-evaluation', 'embedded-ai', 7, 68, 'Modeling and evaluation', 'You will be able to choose the right simulator or model for a hardware question, run gem5 and Chipyard/Gemmini, estimate power, and report results with statistical care.', 40, array['Berkeley EE 290-2 Hardware for Machine Learning (Shao; Spring 2020–2024 offerings; FireSim-based labs)', 'Genc et al., Gemmini, DAC 2021', 'Amid et al., Chipyard: Integrated Design, Simulation, and Implementation Framework for Custom SoCs, IEEE Micro 40(4), 2020', 'Lowe-Power et al., The gem5 Simulator: Version 20.0+, arXiv:2007.03152, 2020']::text[], '[{"title":"Chipyard documentation","url":"https://chipyard.readthedocs.io/"},{"title":"Gemmini","url":"https://github.com/ucb-bar/gemmini"},{"title":"FireSim","url":"https://github.com/firesim/firesim"}]'::jsonb),
  ('embedded-ai/research-practice', 'embedded-ai', 7, 69, 'Research practice', 'You will be able to read papers efficiently, know where the field publishes, review a paper, and reproduce a published result.', 25, array['Keshav, How to Read a Paper, ACM SIGCOMM Computer Communication Review 37(3), 2007', 'Systems Research Artifacts guides for authors and evaluators (sysartifacts.github.io)', 'cTuning Artifact Evaluation (ctuning.org/ae)', 'Georgia Tech PhD CS computer architecture oral examination (present an external paper)']::text[], '[{"title":"Reproduce one paper''s result: artifact packaging guide","url":"https://sysartifacts.github.io/packaging-guide.html"},{"title":"Reproduce one paper''s result: artifact evaluator guide","url":"https://sysartifacts.github.io/evaluator-guide.html"},{"title":"cTuning artifact evaluation (MICRO, ASPLOS, MLSys): checklist and badges","url":"https://ctuning.org/ae/"},{"title":"ML Reproducibility Challenge","url":"https://reproml.org/"}]'::jsonb),
  ('embedded-ai/llm-compression', 'embedded-ai', 8, 70, 'LLM compression', 'You will be able to compress large language models to 8, 4 or fewer than 2 bits per weight and explain the trade-offs of each leading method.', 70, array['MIT 6.5940 (Fall 2026) L13 LLM Quantization and Deployment and L14 LLM Post Training; (Fall 2024) L13 Efficient LLM Deployment and L14 LLM Post Training', 'Frantar et al., GPTQ, ICLR 2023', 'Lin et al., AWQ, MLSys 2024', 'Xiao et al., SmoothQuant, ICML 2023', 'Lin et al., QServe, MLSys 2025', 'Ashkboos et al., QuaRot, NeurIPS 2024; Liu et al., SpinQuant, ICLR 2025', 'Ma et al., The Era of 1-bit LLMs (BitNet b1.58), arXiv:2402.17764, 2024']::text[], '[{"title":"AWQ and TinyChat code","url":"https://github.com/mit-han-lab/llm-awq"},{"title":"GPTQ reference implementation","url":"https://github.com/IST-DASLab/gptq"},{"title":"torchao: PyTorch quantization library","url":"https://github.com/pytorch/ao"}]'::jsonb),
  ('embedded-ai/on-device-llm-runtimes', 'embedded-ai', 8, 71, 'On-device LLM runtimes', 'You will be able to explain and tune how LLMs run on phones, laptops and boards: why generation is memory-bound, how runtimes manage the KV cache, and how the main open runtimes differ.', 60, array['MIT 6.5940 (Fall 2026), L13 LLM Quantization and Deployment and L15 Long Context LLM', 'Kwon et al., PagedAttention (vLLM), SOSP 2023', 'Dao et al., FlashAttention, NeurIPS 2022', 'Leviathan, Kalman & Matias, Fast Inference from Transformers via Speculative Decoding, ICML 2023', 'Project documentation: llama.cpp and GGUF, MLC LLM, LiteRT-LM, ExecuTorch, bitnet.cpp', 'Janapa Reddi et al., mlsysbook.ai Vol. II, ch. 10 (Serving at Scale) and Inference Foundations appendix']::text[], '[{"title":"llama.cpp","url":"https://github.com/ggml-org/llama.cpp"},{"title":"ExecuTorch LLM getting started","url":"https://docs.pytorch.org/executorch/stable/llm/getting-started.html"},{"title":"MLC LLM","url":"https://llm.mlc.ai/"},{"title":"LiteRT-LM","url":"https://github.com/google-ai-edge/LiteRT-LM"},{"title":"bitnet.cpp","url":"https://github.com/microsoft/BitNet"}]'::jsonb),
  ('embedded-ai/small-on-device-models', 'embedded-ai', 8, 72, 'Small on-device models', 'You will be able to explain how today''s small language models are built to run on phones, using Llama 3.2, Gemma 3n and Apple''s on-device model as worked examples.', 35, array['Meta AI blog, Llama 3.2 announcement (25 Sep 2024) and quantized Llama 3.2 1B/3B models (24 Oct 2024)', 'Google Developers Blog, Introducing Gemma 3n: The developer guide (26 Jun 2025)', 'Apple, Apple Intelligence Foundation Language Models Tech Report 2025 (arXiv:2507.13575)', 'Devvrit et al., MatFormer: Nested Transformer for Elastic Inference, NeurIPS 2024']::text[], '[{"title":"Google AI Edge Gallery: run Gemma models on a phone","url":"https://github.com/google-ai-edge/gallery"}]'::jsonb),
  ('embedded-ai/formats-new-silicon', 'embedded-ai', 8, 73, 'Formats and new silicon', 'You will be able to explain the newest low-bit number formats and the latest CPU, NPU and microcontroller hardware for on-device AI, and check vendor claims against first principles.', 35, array['OCP Microscaling Formats (MX) Specification v1.0 (Sep 2023)', 'NVIDIA Technical Blog, Introducing NVFP4 for Efficient and Accurate Low-Precision Inference (24 Jun 2025)', 'Arm Newsroom, Lumex CSS announcement (10 Sep 2025) and Arm Ethos-U85 (9 Apr 2024)', 'STMicroelectronics press release P4665, STM32N6 (10 Dec 2024)', 'TOSA specification v1.1.0 (arm.github.io/tosa-specification)']::text[], '[{"title":"KleidiAI micro-kernels","url":"https://github.com/ARM-software/kleidiai"},{"title":"microxcaling: MX format emulation","url":"https://github.com/microsoft/microxcaling"},{"title":"ExecuTorch Arm Ethos-U backend","url":"https://docs.pytorch.org/executorch/stable/backends-arm-ethos-u.html"}]'::jsonb),
  ('embedded-ai/efficient-generative-vision', 'embedded-ai', 8, 74, 'Efficient generative vision', 'You will be able to explain how vision transformers and image generators are made fast enough for devices: cheaper attention, fewer tokens, fewer sampling steps and 4-bit diffusion.', 25, array['MIT 6.5940 (Fall 2026) L16 Vision Transformer and L17–L18 Diffusion Model; (Fall 2024) L16–L18', 'Cai et al., EfficientViT, ICCV 2023', 'Bolya et al., Token Merging: Your ViT But Faster, ICLR 2023', 'Li et al., SVDQuant, ICLR 2025']::text[], '[{"title":"Nunchaku: SVDQuant inference engine","url":"https://github.com/nunchaku-tech/nunchaku"},{"title":"ToMe: token merging","url":"https://github.com/facebookresearch/ToMe"}]'::jsonb),
  ('embedded-ai/benchmarks-open-problems', 'embedded-ai', 8, 75, 'Benchmarks and open problems', 'You will be able to read industry benchmark results for edge AI critically and explain the field''s main open problems as of late 2026.', 25, array['MLCommons MLPerf Inference (Edge) results and announcements: v5.1 (Sep 2025), v6.0 (Apr 2026), v6.1 (Sep 2026)', 'MLCommons MLPerf Tiny benchmark page and v1.3 results (Sep 2025)', 'MLCommons MLPerf Client benchmark page (v2.0)', 'Banbury et al., MLPerf Tiny Benchmark, NeurIPS Datasets and Benchmarks Track 2021', 'Reddi et al., MLPerf Inference Benchmark, ISCA 2020']::text[], '[{"title":"MLPerf Tiny reference implementations","url":"https://github.com/mlcommons/tiny"},{"title":"MLPerf Client","url":"https://github.com/mlcommons/mlperf_client"},{"title":"MLPerf Inference reference implementations","url":"https://github.com/mlcommons/inference"}]'::jsonb)
on conflict (id) do update set tier = excluded.tier, position = excluded.position, title = excluded.title,
  summary = excluded.summary, planned_cards = excluded.planned_cards, refs = excluded.refs, practice = excluded.practice;

create temporary table profession_card_rows_0d4cbcc197 (like public.profession_cards);
insert into profession_card_rows_0d4cbcc197 (id, profession_id, module_id, position, kind, difficulty, checkpoint, title, body, answer, accepted_answers, answer_display, search_query, refs, tags, as_of, retired) values
  ('embedded-ai/digital-bit-definition', 'embedded-ai', 'embedded-ai/digital-representation', 0, 'definition', 1, false, 'What is a **bit**?', 'A binary digit: a single 0 or 1, the smallest piece of information a computer can store.

The word is short for "binary digit". One bit answers one yes-or-no question: on or off, true or false, 1 or 0.

Example: A light switch is one bit: up means 1, down means 0. A row of 8 switches can show many more patterns than one switch can.

Key idea: Everything a computer stores (numbers, text, photos, music) is built from long rows of bits.', null, '{}'::text[], null, 'bit binary digit definition computer', array['CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-why-two-states', 'embedded-ai', 'embedded-ai/digital-representation', 1, 'concept', 1, false, 'Why does digital hardware store information as bits with only two states?', 'Two states are easy to tell apart reliably, so small electrical disturbances can''t turn one into the other.

Inside a chip, a wire carries a signal that is either high or low. If a wire had to tell ten different levels apart, a little electrical noise could push one level into the next. Two levels, far apart, are almost never confused.

Example: It is easier to tell a lit room from a dark one than to tell ten shades of gray apart in poor light.

Watch out: Two states per bit does not mean computers can only count to 1. Many bits side by side represent large numbers, as the next cards show.', null, '{}'::text[], null, 'why computers use binary two states reliable', array['CS:APP 3e, §2.1 Information Storage', 'Harris & Harris, DDCA RISC-V ed., ch. 1']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-binary-base-2', 'embedded-ai', 'embedded-ai/digital-representation', 2, 'definition', 1, false, 'What does **binary** (base 2) mean when writing numbers?', 'Numbers written with only the digits 0 and 1, where each place is worth twice the place to its right.

Counting in binary goes 0, 1, 10, 11, 100, 101, 110, 111. Decimal runs out of digits after 9 and carries to 10; binary runs out after 1 and carries to 10.

Example: The binary number `10` means two, not ten. `11` means three.

Watch out: `101` could be binary or decimal. Context tells you which base is meant, and code uses markers such as the `0x` prefix, which a later unit shows.', null, '{}'::text[], null, 'binary base 2 number system 0 and 1', array['CS:APP 3e, §2.1 Information Storage', 'CS50x 2026, Week 0 notes: Computer Science and Problem Solving']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-place-value', 'embedded-ai', 'embedded-ai/digital-representation', 3, 'concept', 1, false, 'What is the **place value** of the bit in position $i$ of a binary number, when position 0 is the rightmost bit?', '$2^i$

A place value is what a digit is worth because of where it sits. In decimal, $472 = 4\times 10^2 + 7\times 10^1 + 2\times 10^0$: the places are worth 100, 10 and 1.

In binary the places are worth 1, 2, 4, 8, 16, and so on. For an 8-bit number, from the left (position 7) to the right (position 0), they are 128, 64, 32, 16, 8, 4, 2, 1.

Tip: Write those eight numbers above the bits when you convert by hand, then add only the place values that sit above a 1.', null, '{}'::text[], null, 'binary place value power of two position', array['CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-unsigned-integer', 'embedded-ai', 'embedded-ai/digital-representation', 4, 'definition', 1, false, 'What is an **unsigned integer**?', 'A whole number that is zero or positive, stored with every bit used for its size and none for a minus sign.

An integer is a whole number such as 0, 7 or 42. "Unsigned" means the number carries no sign, so it can''t be negative.

Example: With 8 bits, `00000000` is 0 and `11111111` is 128 + 64 + 32 + 16 + 8 + 4 + 2 + 1 = 255. So 8 unsigned bits cover 0 to 255.

Key idea: Later you will see how negative numbers are stored. Until then, every binary number here is unsigned.', null, '{}'::text[], null, 'unsigned integer definition binary non-negative', array['CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-light-switches-example', 'embedded-ai', 'embedded-ai/digital-representation', 5, 'example', 1, false, 'Four light switches in a row read on, off, on, on from left to right. On means 1, and the leftmost switch is worth 8. What number do they show?', '11

Read the switches as the bits `1011`. From the left the place values are 8, 4, 2, 1.

Example: 1 × 8 + 0 × 4 + 1 × 2 + 1 × 1 = 8 + 2 + 1 = 11.

Tip: Add the place value only where there is a 1. The switches that are off contribute nothing.', null, '{}'::text[], null, 'four bits binary 1011 equals 11 decimal', array['CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-msb-lsb-example', 'embedded-ai', 'embedded-ai/digital-representation', 6, 'example', 1, false, 'In the 8-bit number `10010110`, which bits are the **most significant bit (MSB)** and the **least significant bit (LSB)**, and what is each worth?', 'The MSB is the leftmost bit, a 1 worth 128. The LSB is the rightmost bit, a 0 worth 1.

The most significant bit has the biggest place value, so it changes the number the most. The least significant bit has the smallest place value, 1.

Example: `10010110` = 128 + 16 + 4 + 2 = 150. Flip the MSB and you get `00010110` = 22, a change of 128. Flip the LSB and you get `10010111` = 151, a change of 1.

Watch out: "Significant" means how much the bit contributes to the value, not how important it is.', null, '{}'::text[], null, 'most significant bit least significant bit binary', array['CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-binary-to-decimal-problem', 'embedded-ai', 'embedded-ai/digital-representation', 7, 'problem', 1, false, 'Convert the unsigned binary number `11010110` to decimal.', '214

Write the place values 128, 64, 32, 16, 8, 4, 2, 1 above the bits `1 1 0 1 0 1 1 0`.

Example: Keep the places that sit above a 1: 128 + 64 + 16 + 4 + 2 = 214.

Tip: Check by counting the zeros you skipped: 32, 8 and 1 are missing, and 255 − 41 = 214.', '214', '{}'::text[], null, 'convert binary 11010110 to decimal 214', array['CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-decimal-to-binary-problem', 'embedded-ai', 'embedded-ai/digital-representation', 8, 'problem', 1, false, 'Write the decimal number 77 as an 8-bit unsigned binary number.', '`01001101`

Go through the place values from the left. If the place value fits in what remains, write 1 and subtract it; otherwise write 0.

Example: 128 does not fit (0). 64 fits (1), leaving 13. 32 (0). 16 (0). 8 fits (1), leaving 5. 4 fits (1), leaving 1. 2 (0). 1 fits (1), leaving 0. The bits are `01001101`.

Tip: Check by adding the place values that have a 1: 64 + 8 + 4 + 1 = 77.', null, '{}'::text[], null, 'convert decimal 77 to 8-bit binary', array['CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-power-of-two-definition', 'embedded-ai', 'embedded-ai/digital-representation', 9, 'definition', 1, false, 'What is a **power of two**?', 'A number of the form $2^n$: $n$ copies of 2 multiplied together, with $2^0 = 1$.

The small raised number $n$ is called the exponent. For example, $2^3 = 2 \times 2 \times 2 = 8$. Each time the exponent goes up by 1, the number doubles.

Why: $2^0 = 1$ is the starting point before any doubling. It is also the place value of the rightmost bit.

Key idea: Binary place values are exactly the powers of two, which is why they appear everywhere in computing.', null, '{}'::text[], null, 'power of two definition exponent doubling', array['CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-n-bits-distinct-values', 'embedded-ai', 'embedded-ai/digital-representation', 10, 'concept', 1, false, 'How many different values can $n$ bits represent?', '$2^n$

Each extra bit doubles the number of patterns: 1 bit gives 2, 2 bits give 4 (`00`, `01`, `10`, `11`), 3 bits give 8, and so on.

Example: 8 bits give $2^8 = 256$ different patterns.

Watch out: This counts patterns, not the largest number. The next card turns the count into a largest value.', null, '{}'::text[], null, 'n bits distinct values 2^n patterns', array['CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-largest-unsigned-value', 'embedded-ai', 'embedded-ai/digital-representation', 11, 'concept', 1, false, 'What is the largest unsigned integer that fits in $n$ bits?', '$2^n - 1$

The $2^n$ patterns stand for the numbers 0 up to $2^n - 1$, because the count starts at 0 and zero uses one pattern.

Example: 4 bits reach $2^4 - 1 = 15$, since `1111` = 8 + 4 + 2 + 1. 8 bits reach 255.

Watch out: The classic off-by-one slip is to say 8 bits go up to 256. There are 256 values, but the biggest is 255.', null, '{}'::text[], null, 'largest unsigned integer n bits 2^n minus 1', array['CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-powers-2-to-16', 'embedded-ai', 'embedded-ai/digital-representation', 12, 'numbers', 1, false, 'What are the powers of two from $2^0$ up to $2^{16}$?', '1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096, 8192, 16384, 32768, 65536

Each value is double the one before. Anchor points to remember: $2^8 = 256$, $2^{10} = 1024$ and $2^{16} = 65536$. The others follow by doubling or halving.

Example: $2^7 = 128$ is the biggest place value in an 8-bit number, and $2^{16} = 65536$ is how many different values 16 bits can hold.

Tip: Practise saying the list out loud. These exact numbers show up constantly in memory sizes and number ranges.', null, '{}'::text[], null, 'powers of two table 1 2 4 8 16 up to 65536', array['CS:APP 3e, §2.1 Information Storage']::text[], array['powers-of-two']::text[], null, false),
  ('embedded-ai/digital-ten-bits-thousand', 'embedded-ai', 'embedded-ai/digital-representation', 13, 'numbers', 2, false, 'Roughly how big are $2^{20}$, $2^{30}$ and $2^{40}$?', 'About a million, a billion and a trillion: $10^6$, $10^9$ and $10^{12}$.

Because $2^{10} = 1024 \approx 10^3$, every 10 more bits multiplies the size by about a thousand. So $2^{20} = (2^{10})^2 \approx 10^6$, $2^{30} \approx 10^9$ and $2^{40} \approx 10^{12}$.

Example: Exactly, $2^{20} = 1{,}048{,}576$ and $2^{30} = 1{,}073{,}741{,}824$. And $2^{32} = 4 \times 2^{30} = 4{,}294{,}967{,}296$, about 4.3 billion.

Watch out: The estimate drifts: the true value is 2.4% bigger than $10^3$ at $2^{10}$ and about 10% bigger than $10^{12}$ at $2^{40}$. Use it for quick sizing, not for exact counts.', null, '{}'::text[], null, '2^10 approx 1000 estimate 2^20 2^30 2^40 million billion', array['CS:APP 3e, §2.1 Information Storage']::text[], array['powers-of-two']::text[], null, false),
  ('embedded-ai/digital-bits-needed-problem', 'embedded-ai', 'embedded-ai/digital-representation', 14, 'problem', 2, false, 'You want to give each of 100 different items its own unsigned binary code. What is the fewest number of bits that works?', '7

You need $2^n \geq 100$. Since $2^6 = 64$ is too small and $2^7 = 128$ is enough, 7 bits is the minimum.

Why it works: This is $\lceil \log_2 N \rceil$ with $N = 100$. Here $\log_2 100$ is the power you raise 2 to in order to get 100, about 6.64, and the ceiling symbol $\lceil\ \rceil$ means round up to the next whole number, which gives 7.

Watch out: Always round up. 6.64 bits is not a thing, and 6 bits would leave some items without a code.', '7', '{}'::text[], null, 'bits needed to represent 100 values ceiling log2', array['CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-bits-for-a-million-problem', 'embedded-ai', 'embedded-ai/digital-representation', 15, 'problem', 2, false, 'How many bits are needed to give each of one million different items its own unsigned binary code?', '20

You need $2^n \geq 10^6$. Here $2^{19} = 524{,}288$ is too small and $2^{20} = 1{,}048{,}576$ is enough.

Tip: The shortcut from the last cards gives the answer at once: $2^{20} \approx 10^6$, so one million values takes about 20 bits. Always check one step below, since $2^{19}$ falls short.

Key idea: $\lceil \log_2 N \rceil$ grows slowly. Multiplying the number of items by 1000 adds only about 10 bits.', '20', '{}'::text[], null, 'bits needed one million values 2^20', array['CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-hexadecimal-definition', 'embedded-ai', 'embedded-ai/digital-representation', 16, 'definition', 1, false, 'What is **hexadecimal** (base 16), and which digits does it use?', 'A number system with 16 digits: 0 to 9, then A to F, where A = 10, B = 11, C = 12, D = 13, E = 14, F = 15.

Each place is worth 16 times the place to its right, so the place values are 1, 16, 256, 4096 and so on. People often just say "hex".

Example: The hex number `2F` is 2 × 16 + 15 = 47.

Watch out: In hex, A to F are digits, not letters of a word. `F` alone means fifteen.', null, '{}'::text[], null, 'hexadecimal base 16 digits A to F', array['CS50x 2026, Week 4 notes: Hexadecimal', 'CS:APP 3e, §2.1 Information Storage']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/digital-nibble-definition', 'embedded-ai', 'embedded-ai/digital-representation', 17, 'definition', 1, false, 'What is a **nibble**?', 'A group of 4 bits, which is exactly one hexadecimal digit.

Four bits have $2^4 = 16$ patterns, from `0000` to `1111`, and hex has exactly 16 digits, from 0 to F. So one nibble matches one hex digit.

Example: The nibble `1011` is 11, which is the hex digit B.

Key idea: Two nibbles make a group of 8 bits, which gets its own name in a later unit.', null, '{}'::text[], null, 'nibble 4 bits one hex digit', array['CS50x 2026, Week 4 notes: Hexadecimal', 'CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-binary-hex-grouping', 'embedded-ai', 'embedded-ai/digital-representation', 18, 'concept', 1, false, 'How do you convert a binary number to hexadecimal?', 'Split the bits into groups of four, starting from the right, and write each group as one hex digit.

The nibble values to know: `0000` = 0 up to `1001` = 9, then `1010` = A, `1011` = B, `1100` = C, `1101` = D, `1110` = E, `1111` = F.

Example: `101101` has six bits, so pad on the left to `0010 1101`. That is 2 and D, giving `2D`. Check: 45 in decimal, and 2 × 16 + 13 = 45.

Why it works: 16 is $2^4$, so one hex place is worth exactly four binary places, and nibbles never overlap.', null, '{}'::text[], null, 'convert binary to hexadecimal group four bits nibble', array['CS50x 2026, Week 4 notes: Hexadecimal', 'CS:APP 3e, §2.1 Information Storage']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/digital-0x-prefix-example', 'embedded-ai', 'embedded-ai/digital-representation', 19, 'example', 1, false, 'Code marks hex numbers with the **0x prefix**, as in `0x3F`, so they aren''t mistaken for decimal. Write the binary number `11010110` as a hex number with that prefix.', '`0xD6`

Split into nibbles: `1101` and `0110`. The first is 13, which is D. The second is 6. So the hex digits are D and 6.

Why: Without a marker, `11` could be eleven in decimal, three in binary or seventeen in hex. The 0x prefix removes the doubt, and it works in C, C++ and Python.

Tip: Check by converting back: 0xD6 = 13 × 16 + 6 = 214, the same as the binary number.', null, '{}'::text[], null, '0x prefix hex binary 11010110 to 0xD6', array['CS50x 2026, Week 4 notes: Hexadecimal', 'CS:APP 3e, §2.1 Information Storage']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/digital-rgb-colour-example', 'embedded-ai', 'embedded-ai/digital-representation', 20, 'example', 2, false, 'A web **RGB color code** such as `#RRGGBB` gives the amounts of red, green and blue as three two-digit hex numbers, each from 00 (none) to FF (full). What does `#FF8000` mean?', 'Red 255 (full), green 128 (half), blue 0 (none), which looks orange.

Split the code into pairs: `FF`, `80`, `00`. FF = 15 × 16 + 15 = 255. 80 = 8 × 16 = 128. 00 = 0.

Why it matters: Each pair has 256 possible values, so a code can name $256 \times 256 \times 256 = 16{,}777{,}216$ colors.

Tip: `#FFFFFF` is white (all lights full), `#000000` is black (all off).', null, '{}'::text[], null, 'RGB colour code hex FF8000 red green blue', array['CS50x 2026, Week 0 notes: RGB']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/digital-why-hex-in-programs', 'embedded-ai', 'embedded-ai/digital-representation', 21, 'concept', 2, false, 'Why do programmers write memory addresses and register values in hex?', 'Hex is a compact way to write binary: each hex digit is exactly 4 bits, so a long bit pattern shrinks to a few digits that are easy to turn back into bits.

A memory address is the number that says where a piece of data is stored. A register is a tiny, very fast storage spot inside the chip that runs programs, and it holds one value at a time.

Example: A 32-bit value takes 32 binary digits but only 8 hex digits, as in `0xDEADBEEF`.

Watch out: Hex is only a way of writing. The value stored is the same bits whether you show them as binary, decimal or hex. Decimal is awkward here because 10 is not a power of two, so decimal digits don''t line up with bits.', null, '{}'::text[], null, 'why programmers use hexadecimal memory addresses registers', array['CS50x 2026, Week 4 notes: Hexadecimal', 'CS:APP 3e, §2.1 Information Storage']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/digital-hex-3f-problem', 'embedded-ai', 'embedded-ai/digital-representation', 22, 'problem', 2, false, 'Convert `0x3F` to decimal.', '63

The place values are 16 and 1. The digit 3 sits in the 16s place and F is fifteen.

Example: 3 × 16 + 15 × 1 = 48 + 15 = 63.

Tip: Check in binary: `0x3F` is `0011 1111`, six ones, which is $2^6 - 1 = 63$.', '63', '{}'::text[], null, 'convert hex 0x3F to decimal 63', array['CS50x 2026, Week 4 notes: Hexadecimal', 'CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-hex-1a2b-problem', 'embedded-ai', 'embedded-ai/digital-representation', 23, 'problem', 2, true, 'Convert the four-digit hex value `0x1A2B` to decimal.', '6699

Use the place values 4096, 256, 16 and 1, and remember A = 10 and B = 11.

Example: 1 × 4096 + 10 × 256 + 2 × 16 + 11 × 1 = 4096 + 2560 + 32 + 11 = 6699.

Tip: Check the size. Four hex digits are 16 bits, so the value must be below $2^{16} = 65536$, and the top digit 1 puts it near 4096 to 8191.', '6699', '{}'::text[], null, 'convert hex 0x1A2B to decimal 6699', array['CS50x 2026, Week 4 notes: Hexadecimal', 'CS:APP 3e, §2.1 Information Storage']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-byte-definition', 'embedded-ai', 'embedded-ai/digital-representation', 24, 'definition', 1, false, 'What is a **byte**?', 'A group of 8 bits.

A byte has $2^8 = 256$ patterns (0 to 255), and it is written with exactly two hex digits (`00` to `FF`). It is the unit memory is normally counted in.

Example: A plain English letter takes one byte, as the text unit will show.

Watch out: Lowercase b means bit and capital B means byte. A link rated at 100 megabits per second moves at most 12.5 megabytes per second, since 100 ÷ 8 = 12.5.', null, '{}'::text[], null, 'byte definition 8 bits memory unit', array['CS:APP 3e, §2.1 Information Storage', 'NIST Reference on Constants, Units and Uncertainty: Prefixes for binary multiples']::text[], array['units']::text[], null, false),
  ('embedded-ai/digital-word-definition', 'embedded-ai', 'embedded-ai/digital-representation', 25, 'definition', 1, false, 'What is a **word** in computer hardware?', 'The natural chunk of data a processor handles at once, commonly 16, 32 or 64 bits.

A processor is the chip that runs programs. Its word size is the width it works with most easily, so a 32-bit processor has 32-bit words (4 bytes) and a 64-bit processor has 64-bit words (8 bytes).

Example: Adding two 32-bit numbers on a 32-bit processor is one step, because each number fits in a single word.

Watch out: This "word" has nothing to do with English words. Some manuals fix the size no matter how wide the chip is: Intel''s x86 manuals use "word" for 16 bits and Arm''s use it for 32 bits, so check the manual.', null, '{}'::text[], null, 'word size processor 16 32 64 bits definition', array['CS:APP 3e, §2.1 Information Storage']::text[], array['units']::text[], null, false),
  ('embedded-ai/digital-si-vs-iec-prefixes', 'embedded-ai', 'embedded-ai/digital-representation', 26, 'concept', 2, false, 'What is the difference between kB and KiB (and between MB and MiB, GB and GiB)?', 'kB, MB and GB count in powers of 1000 (1 kB = 1000 bytes); KiB, MiB and GiB count in powers of 1024 (1 KiB = 1024 bytes).

The decimal SI prefixes kilo, mega and giga stand for 1000, 1000² and 1000³. The **IEC binary prefixes** kibi, mebi and gibi (short for "kilo binary", "mega binary" and "giga binary") stand for 1024, 1024² and 1024³. The units are the kibibyte (KiB), mebibyte (MiB) and gibibyte (GiB).

Example: 1 MB = 1,000,000 bytes, but 1 MiB = 1,048,576 bytes.

Watch out: The little i marks the binary units (and kB uses a lowercase k while KiB uses a capital K). The difference is about 2.4% for kilo and grows to about 7.4% at giga.', null, '{}'::text[], null, 'kB vs KiB SI prefix IEC binary prefix kibibyte', array['CS:APP 3e, §2.1 Information Storage', 'NIST Reference on Constants, Units and Uncertainty: Prefixes for binary multiples']::text[], array['units']::text[], null, false),
  ('embedded-ai/digital-kib-mib-gib-numbers', 'embedded-ai', 'embedded-ai/digital-representation', 27, 'numbers', 2, false, 'How many bytes are in 1 KiB, 1 MiB and 1 GiB?', '1 KiB = 1024 bytes ($2^{10}$), 1 MiB = 1,048,576 bytes ($2^{20}$), 1 GiB = 1,073,741,824 bytes ($2^{30}$).

Each unit is 1024 times the one before it, so you only need the powers of two from the earlier unit.

Example: 4 KiB is 4 × 1024 = 4096 bytes, which is $2^2 \times 2^{10} = 2^{12}$.

Tip: These are exact by definition of the IEC prefixes. The values are what you get from $2^{10}$, $2^{20}$ and $2^{30}$ in the powers-of-two cards.', null, '{}'::text[], null, 'KiB MiB GiB bytes 1024 1048576 1073741824', array['CS:APP 3e, §2.1 Information Storage', 'NIST Reference on Constants, Units and Uncertainty: Prefixes for binary multiples']::text[], array['units', 'powers-of-two']::text[], null, false),
  ('embedded-ai/digital-drive-capacity-misconception', 'embedded-ai', 'embedded-ai/digital-representation', 28, 'misconception', 2, false, 'Why is it false that a drive sold as 256 GB is missing storage when the computer shows it as about 238 GiB?', 'Nothing is missing: the maker counts in GB (1 GB = $10^9$ bytes) and the computer displays GiB (1 GiB = $2^{30}$ bytes). Same bytes, different unit.

Example: $256 \times 10^9 = 256{,}000{,}000{,}000$ bytes. Dividing by $2^{30} = 1{,}073{,}741{,}824$ gives about 238.4 GiB.

Why it matters: A GiB is bigger than a GB, so the same number of bytes gives a smaller figure in GiB. The gap is about 7% at this size.

Watch out: Some operating systems show GB while still counting in 1024s. The label alone doesn''t tell you which one is used.', null, '{}'::text[], null, '256 GB drive shows 238 GiB why GB vs GiB', array['CS:APP 3e, §2.1 Information Storage', 'NIST Reference on Constants, Units and Uncertainty: Prefixes for binary multiples']::text[], array['units']::text[], null, false),
  ('embedded-ai/digital-kib-to-bytes-problem', 'embedded-ai', 'embedded-ai/digital-representation', 29, 'problem', 2, false, 'A small chip has 64 KiB of memory. How many bytes is that?', '65536

Multiply by 1024 bytes per KiB: 64 × 1024 = 65,536.

Tip: 64 is $2^6$ and 1024 is $2^{10}$, so the answer is $2^{16}$. That is the same number as the count of values in 16 bits.', '65536', '{}'::text[], null, '64 KiB to bytes 65536 convert', array['CS:APP 3e, §2.1 Information Storage', 'NIST Reference on Constants, Units and Uncertainty: Prefixes for binary multiples']::text[], '{}'::text[], null, false),
  ('embedded-ai/digital-files-in-storage-problem', 'embedded-ai', 'embedded-ai/digital-representation', 30, 'problem', 2, false, 'A storage chip holds 1 MiB. Each saved image file is 52 kB (1 kB = 1000 bytes). How many whole image files fit?', '20

Convert both to bytes first: 1 MiB = 1,048,576 bytes and 52 kB = 52,000 bytes.

Example: 1,048,576 ÷ 52,000 is about 20.2, so 20 whole files fit (20 × 52,000 = 1,040,000 bytes).

Watch out: Mixing the units by treating both as 1024 gives 1024 ÷ 52, about 19.7, and you would wrongly say 19.', '20', '{}'::text[], null, 'storage capacity MiB files kB mixed units whole files', array['CS:APP 3e, §2.1 Information Storage', 'NIST Reference on Constants, Units and Uncertainty: Prefixes for binary multiples']::text[], array['units']::text[], null, false),
  ('embedded-ai/digital-character-encoding-definition', 'embedded-ai', 'embedded-ai/digital-representation', 31, 'definition', 1, false, 'What is a **character encoding**?', 'An agreed table that gives each character (letter, digit, symbol) a number, which is then stored as bits.

Computers only store numbers, so text works by agreeing that a certain number stands for a certain character. Any program reading the text must use the same table as the program that wrote it.

Example: If the table says 65 means the letter A, then the bits for 65 (`01000001`) are read as an A.

Watch out: Two different tables can give the same bits different meanings. That is the cause of garbled text.', null, '{}'::text[], null, 'character encoding definition table of characters numbers', array['CS50x 2026, Week 0 notes: ASCII; Unicode']::text[], array['text']::text[], null, false),
  ('embedded-ai/digital-ascii-definition', 'embedded-ai', 'embedded-ai/digital-representation', 32, 'definition', 1, false, 'What is **ASCII**?', 'An early character encoding that gives codes 0 to 127 (7 bits) to English letters, digits, punctuation and control codes.

The name stands for American Standard Code for Information Interchange. Codes 32 to 126 are the 95 printable characters (including the space, code 32). The rest are control codes, such as 10 for a new line.

Example: The code for a space is 32, and the code for the exclamation mark is 33.

Key idea: ASCII fits in one byte with the top bit left at 0. It covers English well but has no accented letters or other alphabets.', null, '{}'::text[], null, 'ASCII definition 128 codes 7 bits printable control', array['CS50x 2026, Week 0 notes: ASCII; Unicode']::text[], array['text']::text[], null, false),
  ('embedded-ai/digital-code-point-definition', 'embedded-ai', 'embedded-ai/digital-representation', 33, 'definition', 1, false, 'In **Unicode**, what is a **code point**?', 'The unique number Unicode gives to one character, written U+ followed by hex digits, such as U+0041 for A.

Unicode is one standard that covers nearly all the world''s writing systems, plus symbols and emoji. Its code points run from U+0000 to U+10FFFF, and the first 128 are the same as ASCII.

Example: The letter é is U+00E9, the euro sign € is U+20AC and the grinning face emoji is U+1F600.

Watch out: A code point is a number for a character, not yet a way of storing it in bytes. That comes next.', null, '{}'::text[], null, 'unicode code point definition U+0041', array['CS50x 2026, Week 0 notes: ASCII; Unicode', 'The Unicode Standard, Core Specification, ch. 2 (General Structure)']::text[], array['text']::text[], null, false),
  ('embedded-ai/digital-ascii-code-patterns', 'embedded-ai', 'embedded-ai/digital-representation', 34, 'numbers', 1, false, 'What are the ASCII codes of the characters `A`, `a` and `0`?', '`A` = 65, `a` = 97 and `0` = 48.

Letters and digits are in order, so `B` = 66, up to `Z` = 90, and `b` = 98, up to `z` = 122. The digits run from `0` = 48 to `9` = 57.

Example: The code of `D` is 65 + 3 = 68. In hex, `A`, `a` and `0` are 0x41, 0x61 and 0x30.

Tip: A lowercase letter is its uppercase letter plus 32. In binary that is just one bit, the 32s place, switched on.', null, '{}'::text[], null, 'ASCII codes A 65 a 97 0 48', array['CS50x 2026, Week 0 notes: ASCII; Unicode']::text[], array['text']::text[], null, false),
  ('embedded-ai/digital-digit-character-example', 'embedded-ai', 'embedded-ai/digital-representation', 35, 'example', 1, false, 'What ASCII code does the character `7` have?', '55

The character `0` has code 48, and the digits are in order, so `7` is 48 + 7 = 55.

Watch out: The character `7` and the number 7 are different things. Code 7 is a control code (the terminal bell), not a digit.

Tip: To turn a digit character into its number, subtract the code of `0`. For `7` that is 55 − 48 = 7.', null, '{}'::text[], null, 'ASCII code of character 7 is 55', array['CS50x 2026, Week 0 notes: ASCII; Unicode']::text[], array['text']::text[], null, false),
  ('embedded-ai/digital-utf8-concept', 'embedded-ai', 'embedded-ai/digital-representation', 36, 'concept', 2, false, 'How does **UTF-8** store a Unicode code point?', 'As 1 to 4 bytes: the 128 ASCII code points take 1 byte, and larger code points take 2, 3 or 4 bytes.

A character that needs more than one byte is called a **multibyte character**. The byte count depends on the code point:

- U+0000 to U+007F: 1 byte
- U+0080 to U+07FF: 2 bytes
- U+0800 to U+FFFF: 3 bytes
- U+10000 to U+10FFFF: 4 bytes

Why it works: Plain ASCII text is already valid UTF-8, byte for byte. The first bits of the first byte tell the reader how many bytes the character uses.', null, '{}'::text[], null, 'UTF-8 variable length 1 to 4 bytes code point', array['CS50x 2026, Week 0 notes: ASCII; Unicode', 'RFC 3629 (UTF-8, a transformation format of ISO 10646)']::text[], array['text']::text[], null, false),
  ('embedded-ai/digital-utf8-byte-counts-numbers', 'embedded-ai', 'embedded-ai/digital-representation', 37, 'numbers', 2, false, 'How many bytes does UTF-8 use for `A`, `é` and the emoji 😀?', '1 byte, 2 bytes and 4 bytes.

A is U+0041, stored as the single byte 0x41. é is U+00E9, stored as the two bytes 0xC3 0xA9. The emoji is U+1F600, stored as the four bytes 0xF0 0x9F 0x98 0x80.

Example: The euro sign € (U+20AC) takes 3 bytes, 0xE2 0x82 0xAC, and most Chinese characters also take 3.

Tip: Rule of thumb: English letters 1 byte, accented Latin letters 2, most other scripts 3, most emoji 4 (a few older symbol-style ones take 3).', null, '{}'::text[], null, 'UTF-8 bytes for A é emoji 1 2 4', array['CS50x 2026, Week 0 notes: ASCII; Unicode', 'RFC 3629 (UTF-8, a transformation format of ISO 10646)']::text[], array['text']::text[], null, false),
  ('embedded-ai/digital-string-length-concept', 'embedded-ai', 'embedded-ai/digital-representation', 38, 'concept', 2, false, 'Why can a string''s length in characters differ from its length in bytes?', 'In UTF-8 some characters take more than one byte, so the byte count can be larger than the character count.

Example: The word `héllo` has 5 characters but 6 bytes, because é takes 2 bytes and the other four letters take 1 each (1 + 2 + 1 + 1 + 1).

Why it matters: Programs that measure text in bytes, such as C''s `strlen`, report 6 here, while Python''s `len` reports 5 characters.

Watch out: Reserving space by the number of characters can overflow a buffer. Reserve by bytes. (A buffer is a block of memory set aside to hold the text.)', null, '{}'::text[], null, 'string length characters vs bytes UTF-8 strlen', array['CS50x 2026, Week 0 notes: ASCII; Unicode', 'RFC 3629 (UTF-8, a transformation format of ISO 10646)']::text[], array['text']::text[], null, false),
  ('embedded-ai/digital-mojibake-example', 'embedded-ai', 'embedded-ai/digital-representation', 39, 'example', 2, false, 'A web page should show `café` but shows `cafÃ©`. What went wrong, and what is this kind of garbled text called?', '**Mojibake**: the UTF-8 bytes were read with the wrong encoding.

In UTF-8, é is the two bytes 0xC3 0xA9. A reader using an older single-byte table called Latin-1 shows each byte as its own character: 0xC3 is Ã and 0xA9 is ©.

Key idea: Neither side made an arithmetic mistake. They disagreed about which table to use.

Tip: The fix is to read the data with the encoding it was written in, usually UTF-8.', null, '{}'::text[], null, 'mojibake garbled text wrong encoding UTF-8 Latin-1', array['CS50x 2026, Week 0 notes: ASCII; Unicode']::text[], array['text']::text[], null, false),
  ('embedded-ai/digital-unicode-vs-utf8-misconception', 'embedded-ai', 'embedded-ai/digital-representation', 40, 'misconception', 2, false, 'Why is it false that Unicode and UTF-8 are the same thing?', 'Unicode assigns the numbers (code points); UTF-8 is just one way to store those numbers as bytes.

Other ways exist, such as UTF-16 and UTF-32. The same character keeps one code point however it is stored.

Example: é is always U+00E9. UTF-8 stores it as the two bytes 0xC3 0xA9, while UTF-16 stores it as one 16-bit unit, 0x00E9.

Key idea: Two layers: Unicode picks the number for each character, an encoding such as UTF-8 turns that number into bytes.', null, '{}'::text[], null, 'Unicode vs UTF-8 difference code point encoding', array['CS50x 2026, Week 0 notes: ASCII; Unicode', 'The Unicode Standard, Core Specification, ch. 2 (General Structure)']::text[], array['text']::text[], null, false),
  ('embedded-ai/digital-twos-complement-definition', 'embedded-ai', 'embedded-ai/digital-representation', 41, 'definition', 2, false, 'How does **two''s complement** store **signed integers** (whole numbers that may be negative) in $n$ bits?', 'The top bit, the **sign bit**, has place value $-2^{n-1}$, and every other bit keeps its usual positive place value.

For 8 bits the place values are −128, 64, 32, 16, 8, 4, 2, 1. A sign bit of 1 means the number is negative.

Example: `11111111` = −128 + 127 = −1. `10000000` = −128. `01111111` = 127.

Why it matters: The same adding circuit works for signed and unsigned numbers, so almost every processor uses two''s complement.', null, '{}'::text[], null, 'two''s complement definition sign bit negative place value', array['CS:APP 3e, §2.2 Integer Representations', 'CS:APP 3e, §2.3 Integer Arithmetic']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/digital-signed-range-concept', 'embedded-ai', 'embedded-ai/digital-representation', 42, 'concept', 2, false, 'What range of values can an $n$-bit two''s-complement integer hold?', '$-2^{n-1}$ to $2^{n-1} - 1$.

Half the patterns have the sign bit set (negative) and half do not. Zero takes one of the non-negative patterns, so there is one more negative value than positive.

Example: 8 bits hold −128 to 127 (256 values in all). 16 bits hold −32,768 to 32,767. 32 bits hold −2,147,483,648 to 2,147,483,647.

Watch out: −128 has no positive partner in 8 bits, since +128 doesn''t fit.', null, '{}'::text[], null, 'signed integer range -2^(n-1) to 2^(n-1)-1 two''s complement', array['CS:APP 3e, §2.2 Integer Representations', 'CS:APP 3e, §2.3 Integer Arithmetic']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/digital-negate-invert-add-one', 'embedded-ai', 'embedded-ai/digital-representation', 43, 'concept', 2, false, 'How do you negate a two''s-complement number?', 'Invert every bit, then add 1.

Why: A number plus its bit-inverted copy gives all ones, which reads as −1. So the inverted copy is −1 − x, and adding 1 gives −x.

Example: To get −3, start from `00000011`. Invert to `11111100`, add 1, and you get `11111101`. Reading it back: −128 + 125 = −3.

Watch out: Negating −128 (`10000000`) gives `10000000` again. Its positive partner doesn''t fit.', null, '{}'::text[], null, 'negate two''s complement invert bits add one', array['CS:APP 3e, §2.2 Integer Representations', 'CS:APP 3e, §2.3 Integer Arithmetic']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/digital-temperature-example', 'embedded-ai', 'embedded-ai/digital-representation', 44, 'example', 2, false, 'A sensor stores −20 as an 8-bit two''s-complement number. What hex value is stored?', '`0xEC`

Start from +20, which is `00010100`. Invert to `11101011`, then add 1 to get `11101100`. In nibbles that is `1110` and `1100`, which is E and C.

Example: Check with decimal: 256 − 20 = 236, and 0xEC = 14 × 16 + 12 = 236. Reading `11101100` directly: −128 + 64 + 32 + 8 + 4 = −20.

Tip: An 8-bit negative number x is stored as 256 + x. This is a handy way to check your work.', null, '{}'::text[], null, '-20 as 8-bit two''s complement hex 0xEC', array['CS:APP 3e, §2.2 Integer Representations', 'CS:APP 3e, §2.3 Integer Arithmetic']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/digital-number-format-misconception', 'embedded-ai', 'embedded-ai/digital-representation', 45, 'misconception', 2, false, 'Why is it false that the bit pattern `11111111` always means 255?', 'A bit pattern has no meaning on its own: the same 8 bits are 255 as an unsigned integer but −1 as a two''s-complement signed integer.

A **number format** is the rule that says how to read bits as a number. Whoever reads the data must know which one was used.

Example: In C, `uint8_t` and `int8_t` are both 8 bits. The pattern 0xFF is 255 in the first and −1 in the second.

Watch out: Mixing up signed and unsigned reads is a common bug source. The bits don''t change, only the reading does.', null, '{}'::text[], null, 'bit pattern meaning depends number format signed unsigned 0xFF', array['CS:APP 3e, §2.2 Integer Representations', 'CS:APP 3e, §2.3 Integer Arithmetic']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/digital-overflow-definition', 'embedded-ai', 'embedded-ai/digital-representation', 46, 'definition', 2, false, 'What is **overflow**: what happens when the result of an addition doesn''t fit in the available bits?', 'A result too big for the available bits: the extra high bit is lost, so the value **wraps around** to the other end of the range.

Example: In 8 unsigned bits, 255 + 1 is `1 00000000`. The ninth bit has nowhere to go, so the result is 0. In 8 signed bits, 127 + 1 wraps to −128.

Key idea: Wrap-around works like a car''s odometer rolling over from 999999 back to 000000.

Watch out: Most processors don''t stop or raise an error by themselves. In C, unsigned wrap-around is defined, but signed overflow is "undefined behavior" (the language promises nothing about the result), so don''t rely on it.', null, '{}'::text[], null, 'integer overflow wrap-around fixed width bits', array['CS:APP 3e, §2.2 Integer Representations', 'CS:APP 3e, §2.3 Integer Arithmetic']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/digital-read-negative-problem', 'embedded-ai', 'embedded-ai/digital-representation', 47, 'problem', 2, false, 'Read `10110100` as an 8-bit two''s-complement number. What decimal value is it?', '-76

The sign bit is 1, so the number is negative. Start from −128 and add the other place values that have a 1: 32, 16 and 4.

Example: −128 + 32 + 16 + 4 = −128 + 52 = −76.

Tip: Check by negating. Invert to `01001011` and add 1 to get `01001100`, which is 64 + 8 + 4 = 76.', '-76', '{}'::text[], null, 'read 10110100 8-bit two''s complement -76', array['CS:APP 3e, §2.2 Integer Representations', 'CS:APP 3e, §2.3 Integer Arithmetic']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/digital-overflow-add-problem', 'embedded-ai', 'embedded-ai/digital-representation', 48, 'problem', 2, true, 'In 8-bit two''s complement, add `01100100` (100) and `00110010` (50). What signed value do the 8 result bits show?', '-106

The true sum, 150, is bigger than the largest 8-bit signed value, 127, so it overflows. The bit sum is `10010110`.

Example: The sign bit is now 1. Reading it: −128 + 16 + 4 + 2 = −106. Check: 150 − 256 = −106.

Key idea: Overflow shifts the answer by exactly 256 (that is $2^8$) for 8 bits. Two positives that add to a negative is the telltale sign.', '-106', '{}'::text[], null, '8-bit signed overflow 100 + 50 gives -106', array['CS:APP 3e, §2.2 Integer Representations', 'CS:APP 3e, §2.3 Integer Arithmetic']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/digital-sign-extension-problem', 'embedded-ai', 'embedded-ai/digital-representation', 49, 'problem', 2, false, '**Sign extension** widens a number by copying its sign bit into the new top bits. Sign-extend the 8-bit two''s-complement value `0xF6` to 16 bits. What is the result in hex?', '`0xFFF6`

0xF6 is `11110110`, and its sign bit is 1, so it is negative: −128 + 64 + 32 + 16 + 4 + 2 = −10. Copy that 1 into the 8 new bits to get `11111111 11110110`.

Example: As 16 bits, 0xFFF6 = −32768 + 32758 = −10, so the value is unchanged.

Watch out: Filling the new bits with zeros gives 0x00F6 = 246, a different number. Zeros are right for unsigned values, copies of the sign bit for signed ones.', null, '{}'::text[], null, 'sign extension 8-bit to 16-bit 0xF6 0xFFF6', array['CS:APP 3e, §2.2 Integer Representations', 'CS:APP 3e, §2.3 Integer Arithmetic']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/numeracy-base-and-exponent', 'embedded-ai', 'embedded-ai/engineering-numeracy', 50, 'definition', 1, false, 'In $5^3$, which number is the **base**, which is the **exponent**, and what is the value?', 'The base $5$ is the number being multiplied, the exponent $3$ counts the copies: $5^3 = 5 \times 5 \times 5 = 125$.

An **exponent** is the small raised number that says how many copies of the **base** to multiply together.

Example: $2^4 = 2 \times 2 \times 2 \times 2 = 16$.

Watch out: $5^3$ is not $5 \times 3 = 15$. The exponent counts multiplications, it does not multiply.

Tip: $b^2$ is read "b squared" and $b^3$ "b cubed"; for larger exponents say "b to the power of $n$".', null, '{}'::text[], null, 'exponent base meaning power repeated multiplication', array['OpenStax College Algebra 2e, §1.2 Exponents and Scientific Notation']::text[], array['exponents']::text[], null, false),
  ('embedded-ai/numeracy-product-rule-exponents', 'embedded-ai', 'embedded-ai/engineering-numeracy', 51, 'formula', 1, false, 'What is the **product rule** for exponents: $b^m \times b^n = {?}$ (same base $b$)', '$b^m \times b^n = b^{m+n}$

Why: Write the copies out. $2^3 \times 2^2 = (2\cdot 2\cdot 2)(2\cdot 2) = 2^5$. Multiplying the two groups just counts all the copies together, so the exponents add.

Example: $10^2 \times 10^4 = 10^6$, which is $100 \times 10{,}000 = 1{,}000{,}000$.

Watch out: The bases must match. $2^3 \times 3^2 = 8 \times 9 = 72$, which is not $6^5 = 7776$.', null, '{}'::text[], null, 'product rule exponents add same base', array['OpenStax College Algebra 2e, §1.2 Exponents and Scientific Notation']::text[], array['exponents']::text[], null, false),
  ('embedded-ai/numeracy-power-rule-exponents', 'embedded-ai', 'embedded-ai/engineering-numeracy', 52, 'formula', 1, false, 'What is the **power rule** for exponents: $(b^m)^n = {?}$', '$(b^m)^n = b^{m \times n}$

Why: $(2^4)^2$ means two copies of $2^4$ multiplied together: $2^4 \times 2^4$. By the product rule that is $2^{4+4} = 2^8$. Adding $4$ twice is the same as multiplying $4 \times 2$.

Example: $(10^3)^2 = 10^6$.

Watch out: Do not mix it up with the product rule. $2^4 \times 2^2 = 2^6$, but $(2^4)^2 = 2^8$.', null, '{}'::text[], null, 'power rule exponents multiply power of a power', array['OpenStax College Algebra 2e, §1.2 Exponents and Scientific Notation']::text[], array['exponents']::text[], null, false),
  ('embedded-ai/numeracy-negative-and-zero-exponents', 'embedded-ai', 'embedded-ai/engineering-numeracy', 53, 'concept', 1, false, 'What does a **negative exponent** mean, and what is $b^0$ for a nonzero $b$?', '$b^{-n} = \dfrac{1}{b^n}$ and $b^0 = 1$.

Look at the pattern as the exponent drops by one: $10^3 = 1000$, $10^2 = 100$, $10^1 = 10$, $10^0 = 1$, $10^{-1} = 0.1$, $10^{-2} = 0.01$. Each step down divides by $10$.

Why: The **quotient rule** says dividing powers of the same base subtracts exponents: $b^m / b^n = b^{m-n}$. Take $b^2 / b^2$: anything divided by itself is $1$, and the rule gives $b^0$. Take $b^2 / b^5 = b^{-3}$, which is also $\frac{1}{b^3}$.

Watch out: A negative exponent does not make the number negative. $2^{-3} = \frac{1}{8}$, not $-8$.', null, '{}'::text[], null, 'negative exponent reciprocal zero exponent equals one', array['OpenStax College Algebra 2e, §1.2 Exponents and Scientific Notation']::text[], array['exponents']::text[], null, false),
  ('embedded-ai/numeracy-fractional-exponent', 'embedded-ai', 'embedded-ai/engineering-numeracy', 54, 'definition', 1, false, 'What does a **fractional exponent** such as $b^{1/n}$ mean (for $b > 0$)?', '$b^{1/n}$ is the $n$th root of $b$, so $b^{1/2} = \sqrt{b}$ and $b^{m/n} = \left(\sqrt[n]{b}\right)^m$.

Why: The power rule gives $(b^{1/2})^2 = b^{(1/2) \times 2} = b^1 = b$. So $b^{1/2}$ is a number that squares to $b$: the square root. The same argument makes $b^{1/3}$ the cube root.

Example: $9^{1/2} = 3$ and $27^{1/3} = 3$, because $3 \times 3 \times 3 = 27$. Also $16^{3/4} = (\sqrt[4]{16})^3 = 2^3 = 8$.

Tip: In $b^{m/n}$, the bottom number $n$ is the root and the top number $m$ is the power.', null, '{}'::text[], null, 'fractional exponent nth root rational exponent meaning', array['OpenStax College Algebra 2e, §1.3 Radicals and Rational Exponents']::text[], array['exponents']::text[], null, false),
  ('embedded-ai/numeracy-simplify-exponent-expressions', 'embedded-ai', 'embedded-ai/engineering-numeracy', 55, 'problem', 1, false, 'Simplify $10^3 \times 10^{-6}$ (as a power of $10$) and $(2^4)^2$ (as a plain number).', '$10^{-3}$ and $256$.

Step 1: The bases match, so add the exponents: $10^3 \times 10^{-6} = 10^{3 + (-6)} = 10^{-3}$, which is $0.001$.

Step 2: Multiply the exponents: $(2^4)^2 = 2^{4 \times 2} = 2^8 = 256$.

Check: $2^4 = 16$ and $16^2 = 256$.

Watch out: $3 + (-6)$ is $-3$, not $+3$. Keep the sign of the negative exponent.', null, '{}'::text[], null, 'simplify 10^3 times 10^-6 exponent rules (2^4)^2', array['OpenStax College Algebra 2e, §1.2 Exponents and Scientific Notation']::text[], array['exponents']::text[], null, false),
  ('embedded-ai/numeracy-evaluate-fractional-exponents', 'embedded-ai', 'embedded-ai/engineering-numeracy', 56, 'problem', 1, false, 'Evaluate $4^{1/2}$ and $8^{2/3}$ without a calculator.', '$2$ and $4$.

Step 1: $4^{1/2}$ is the square root of $4$, which is $2$.

Step 2: In $8^{2/3}$ the root is the bottom number $3$ and the power is the top number $2$: $8^{2/3} = (\sqrt[3]{8})^2 = 2^2 = 4$.

Check: Doing the power first gives the same answer: $8^2 = 64$ and $\sqrt[3]{64} = 4$.

Tip: Take the root first. It keeps the numbers small and easy to square.', null, '{}'::text[], null, 'evaluate 4^(1/2) 8^(2/3) fractional exponents', array['OpenStax College Algebra 2e, §1.3 Radicals and Rational Exponents']::text[], array['exponents']::text[], null, false),
  ('embedded-ai/numeracy-scientific-notation', 'embedded-ai', 'embedded-ai/engineering-numeracy', 57, 'definition', 1, false, 'What is **scientific notation**?', 'A number written as $a \times 10^n$ with $1 \le a < 10$ and $n$ an integer (it may be negative).

The exponent $n$ tells you the size at a glance, and $a$ holds the significant digits.

Example: $4{,}500{,}000 = 4.5 \times 10^6$ and $0.00032 = 3.2 \times 10^{-4}$. Count how many places the decimal point moves: moving it left gives a positive exponent, moving it right a negative one.

Watch out: $45 \times 10^5$ is not scientific notation, because $a$ must be below $10$. The correct form is $4.5 \times 10^6$.', null, '{}'::text[], null, 'scientific notation definition a times 10^n', array['OpenStax College Algebra 2e, §1.2 Exponents and Scientific Notation']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/numeracy-engineering-notation', 'embedded-ai', 'embedded-ai/engineering-numeracy', 58, 'definition', 1, false, 'What is **engineering notation**?', 'Scientific notation whose exponent is always a multiple of $3$: $a \times 10^n$ with $n = \ldots, -6, -3, 0, 3, 6, \ldots$ and $1 \le a < 1000$.

Why: Multiples of three line up with the SI prefixes (milli, kilo, mega and so on), so the exponent translates straight into a prefix.

Example: $47{,}000 = 47 \times 10^3$, $0.0022 = 2.2 \times 10^{-3}$ and $0.00000033 = 330 \times 10^{-9}$.

Tip: To change $4.7 \times 10^4$ into engineering form, lower the exponent to the next multiple of three and shift the decimal point to match: $47 \times 10^3$.', null, '{}'::text[], null, 'engineering notation exponent multiple of three', array['OpenStax College Algebra 2e, §1.2 Exponents and Scientific Notation']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/numeracy-small-si-prefixes', 'embedded-ai', 'embedded-ai/engineering-numeracy', 59, 'numbers', 1, false, 'Give the symbol and power of ten for the SI prefixes **pico**, **nano**, **micro** and **milli**.', 'pico p $= 10^{-12}$, nano n $= 10^{-9}$, micro $\mu = 10^{-6}$, milli m $= 10^{-3}$.

An **SI prefix** is a word-part placed before a unit that multiplies it by a fixed power of ten. Milli plus ampere gives milliampere, one thousandth of an ampere.

Example: $1\,\mathrm{ms} = 10^{-3}\,\mathrm{s}$ and $1\,\mathrm{ns} = 10^{-9}\,\mathrm{s}$, so $1\,\mathrm{ms} = 10^6\,\mathrm{ns}$.

Watch out: Lowercase m is milli and uppercase M is mega. $1\,\mathrm{mW}$ is a thousandth of a watt, $1\,\mathrm{MW}$ is a million watts.', null, '{}'::text[], null, 'SI prefixes pico nano micro milli powers of ten', array['OpenStax University Physics Vol. 1, §1.2 Units and Standards', 'BIPM, The International System of Units (SI Brochure), 9th edition, table of SI prefixes']::text[], array['si-prefixes']::text[], null, false),
  ('embedded-ai/numeracy-large-si-prefixes', 'embedded-ai', 'embedded-ai/engineering-numeracy', 60, 'numbers', 1, false, 'Give the symbol and power of ten for the SI prefixes **kilo**, **mega**, **giga** and **tera**.', 'kilo k $= 10^3$, mega M $= 10^6$, giga G $= 10^9$, tera T $= 10^{12}$.

Each prefix is a factor of $1000$ bigger than the one before.

Example: A processor clock of $2.4\,\mathrm{GHz}$ is $2.4 \times 10^9$ cycles per second.

Watch out: Kilo is a lowercase k. Capital K is the symbol for kelvin, the unit of temperature.

Watch out: For data, this course uses $1\,\mathrm{kB} = 1000$ bytes and $1\,\mathrm{KiB} = 1024$ bytes. The SI prefix always means a power of ten.', null, '{}'::text[], null, 'SI prefixes kilo mega giga tera powers of ten', array['OpenStax University Physics Vol. 1, §1.2 Units and Standards', 'BIPM, The International System of Units (SI Brochure), 9th edition, table of SI prefixes']::text[], array['si-prefixes']::text[], null, false),
  ('embedded-ai/numeracy-convert-kilohms', 'embedded-ai', 'embedded-ai/engineering-numeracy', 61, 'example', 1, false, 'Convert $4.7\,\mathrm{k\Omega}$ to ohms by swapping the prefix for its power of ten.', '$4.7\,\mathrm{k\Omega} = 4.7 \times 10^3\,\Omega = 4700\,\Omega$.

The symbol $\Omega$ stands for the ohm, the unit of electrical resistance (how strongly a part opposes electric current). You will meet it properly later; here it is just a unit with a prefix.

Method: Replace the prefix by its power of ten, then multiply. Kilo is $10^3$, so the decimal point moves three places to the right.

Example: Going back, $2200\,\Omega = 2.2 \times 10^3\,\Omega = 2.2\,\mathrm{k\Omega}$.

Watch out: A prefix that makes the unit bigger makes the number smaller. $4700\,\Omega$ is $4.7$ in kilo-ohms.', null, '{}'::text[], null, 'convert 4.7 kilohm to ohms prefix power of ten', array['OpenStax University Physics Vol. 1, §1.2 Units and Standards', 'OpenStax College Algebra 2e, §1.2 Exponents and Scientific Notation']::text[], array['si-prefixes']::text[], null, false),
  ('embedded-ai/numeracy-convert-milliamps', 'embedded-ai', 'embedded-ai/engineering-numeracy', 62, 'problem', 1, false, 'A sensor draws $20\,\mathrm{mA}$. Express this in amperes (A), the unit of electric current. Give the number only.', '$0.02\,\mathrm{A}$

Milli means $10^{-3}$, so $20\,\mathrm{mA} = 20 \times 10^{-3}\,\mathrm{A} = 0.02\,\mathrm{A}$.

Check: $1000\,\mathrm{mA} = 1\,\mathrm{A}$, so $20\,\mathrm{mA}$ must be a small fraction of an ampere.

Tip: Dividing by $1000$ moves the decimal point three places left: $20.0 \to 0.020$.', '0.02', array['0.02 A', '2e-2', '2x10^-2']::text[], '$0.02\,\mathrm{A}$', '20 mA in amperes milli conversion 0.02', array['OpenStax University Physics Vol. 1, §1.2 Units and Standards', 'OpenStax College Algebra 2e, §1.2 Exponents and Scientific Notation']::text[], array['si-prefixes']::text[], null, false),
  ('embedded-ai/numeracy-convert-microseconds', 'embedded-ai', 'embedded-ai/engineering-numeracy', 63, 'problem', 1, false, 'Convert $250\,\mu\mathrm{s}$ to milliseconds. Give the number only.', '$0.25\,\mathrm{ms}$

Route through seconds: $250\,\mu\mathrm{s} = 250 \times 10^{-6}\,\mathrm{s} = 0.25 \times 10^{-3}\,\mathrm{s} = 0.25\,\mathrm{ms}$.

Why: One millisecond is $1000$ microseconds, so a microsecond is a smaller unit and you need fewer milliseconds than microseconds.

Watch out: The number gets smaller when you move to the bigger unit. An answer of $250{,}000$ has gone the wrong way.', '0.25', array['0.25 ms', '1/4']::text[], '$0.25\,\mathrm{ms}$', '250 microseconds to milliseconds conversion 0.25 ms', array['OpenStax University Physics Vol. 1, §1.2 Units and Standards', 'OpenStax College Algebra 2e, §1.2 Exponents and Scientific Notation']::text[], array['si-prefixes']::text[], null, false),
  ('embedded-ai/numeracy-multiply-scientific-notation', 'embedded-ai', 'embedded-ai/engineering-numeracy', 64, 'problem', 1, false, 'Compute $(4 \times 10^5) \times (5 \times 10^{-8})$ and write the result in scientific notation.', '$2 \times 10^{-2}$

Step 1: Multiply the numbers in front: $4 \times 5 = 20$.

Step 2: Add the exponents, since the powers of ten share a base: $5 + (-8) = -3$. So the product is $20 \times 10^{-3}$.

Step 3: $20$ is not below $10$, so fix the form: $20 \times 10^{-3} = 2 \times 10^{-2}$, which is $0.02$.

Check: $400{,}000 \times 0.00000005 = 0.02$.

Tip: Division works the other way: divide the numbers in front and subtract the exponents.', null, '{}'::text[], null, 'multiply numbers in scientific notation add exponents', array['OpenStax College Algebra 2e, §1.2 Exponents and Scientific Notation']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/numeracy-si-base-units', 'embedded-ai', 'embedded-ai/engineering-numeracy', 65, 'definition', 1, false, 'What are the seven **SI base units**?', 'Second (s), meter (m), kilogram (kg), ampere (A), kelvin (K), mole (mol) and candela (cd): time, length, mass, electric current, temperature, amount of substance and luminous intensity (how strong a light source appears).

Every other SI unit is built by combining these seven. For electronics you will use second, meter, kilogram, ampere and kelvin the most.

Watch out: The base unit of mass is the kilogram, not the gram. It is the only base unit with a prefix built in.', null, '{}'::text[], null, 'seven SI base units second meter kilogram ampere kelvin mole candela', array['OpenStax University Physics Vol. 1, §1.2 Units and Standards']::text[], array['units']::text[], null, false),
  ('embedded-ai/numeracy-derived-units', 'embedded-ai', 'embedded-ai/engineering-numeracy', 66, 'definition', 1, false, 'What is an SI **derived unit**? Give hertz and coulomb as examples.', 'A derived unit is a combination of base units: $1\,\mathrm{Hz} = 1/\mathrm{s}$ and $1\,\mathrm{C} = 1\,\mathrm{A \cdot s}$.

- **hertz (Hz)**: repeats per second, $1/\mathrm{s}$. A $1\,\mathrm{Hz}$ signal repeats once every second.
- **coulomb (C)**: a quantity of electric charge, the charge carried by $1\,\mathrm{A}$ flowing for $1\,\mathrm{s}$.
- **joule (J)**: the unit of energy, $1\,\mathrm{J} = 1\,\mathrm{kg \cdot m^2/s^2}$.
- **watt (W)**: the unit of power (energy per second), $1\,\mathrm{W} = 1\,\mathrm{J/s}$.

Key idea: Volt and ohm are derived units too; you will build them up when you reach electricity.

Watch out: Units named after people are spelled in lowercase (watt) but their symbols are capitalized (W).', null, '{}'::text[], null, 'SI derived units hertz coulomb joule watt definition', array['OpenStax University Physics Vol. 1, §1.2 Units and Standards']::text[], array['units']::text[], null, false),
  ('embedded-ai/numeracy-conversion-factor', 'embedded-ai', 'embedded-ai/engineering-numeracy', 67, 'concept', 1, false, 'What is a **conversion factor**, and why can you multiply by one without changing the quantity?', 'A conversion factor is a fraction equal to $1$, such as $\dfrac{1000\,\mathrm{m}}{1\,\mathrm{km}}$, so multiplying by it changes the units but not the quantity.

The top and bottom are the same length written in two units, so the fraction is exactly $1$.

Example: $3\,\mathrm{km} \times \dfrac{1000\,\mathrm{m}}{1\,\mathrm{km}} = 3000\,\mathrm{m}$. The kilometers cancel like a common factor in a fraction.

Tip: Put the unit you want to get rid of on the bottom of the factor, so it cancels.

Watch out: Flip the fraction and the units do not cancel: $3\,\mathrm{km} \times \frac{1\,\mathrm{km}}{1000\,\mathrm{m}}$ leaves $\mathrm{km^2/m}$, a sign you used the wrong form.', null, '{}'::text[], null, 'conversion factor fraction equal to one unit conversion cancel', array['OpenStax University Physics Vol. 1, §1.3 Unit Conversion']::text[], array['units']::text[], null, false),
  ('embedded-ai/numeracy-convert-kmh-to-ms', 'embedded-ai', 'embedded-ai/engineering-numeracy', 68, 'problem', 1, false, 'A car travels at $72\,\mathrm{km/h}$. What is its speed in $\mathrm{m/s}$? Give the number only.', '$20\,\mathrm{m/s}$

Multiply by two conversion factors, one for the distance and one for the time:

$$72\,\frac{\mathrm{km}}{\mathrm{h}} \times \frac{1000\,\mathrm{m}}{1\,\mathrm{km}} \times \frac{1\,\mathrm{h}}{3600\,\mathrm{s}} = \frac{72000}{3600}\,\frac{\mathrm{m}}{\mathrm{s}} = 20\,\frac{\mathrm{m}}{\mathrm{s}}$$

Check: Kilometers and hours both cancel, leaving meters per second.

Tip: Dividing a speed in $\mathrm{km/h}$ by $3.6$ gives $\mathrm{m/s}$, because $3600 / 1000 = 3.6$.', '20', array['20 m/s']::text[], '$20\,\mathrm{m/s}$', 'convert 72 km/h to m/s conversion factors', array['OpenStax University Physics Vol. 1, §1.3 Unit Conversion']::text[], array['units']::text[], null, false),
  ('embedded-ai/numeracy-check-units-both-sides', 'embedded-ai', 'embedded-ai/engineering-numeracy', 69, 'problem', 2, false, 'A student writes $d = v\,t^2$ for distance $d$ in meters, speed $v$ in $\mathrm{m/s}$ and time $t$ in seconds. Using **dimensional analysis** (tracking the units through the equation like algebra), is it consistent?', 'No: the right side has units $\mathrm{m \cdot s}$, but the left side is in meters.

Dimensional analysis means treating units like algebra symbols and checking that both sides of an equation end up with the same unit.

Step 1: Left side: $d$ is in $\mathrm{m}$.

Step 2: Right side: $v\,t^2 \to \dfrac{\mathrm{m}}{\mathrm{s}} \times \mathrm{s}^2 = \mathrm{m \cdot s}$.

Step 3: $\mathrm{m}$ and $\mathrm{m \cdot s}$ differ, so the equation cannot be right.

Fix: $d = v\,t$ works, because $\dfrac{\mathrm{m}}{\mathrm{s}} \times \mathrm{s} = \mathrm{m}$.

Tip: Run this check on any formula you are unsure of.', null, '{}'::text[], null, 'dimensional analysis check equation units both sides consistent', array['OpenStax University Physics Vol. 1, §1.4 Dimensional Analysis']::text[], array['units']::text[], null, false),
  ('embedded-ai/numeracy-units-check-misconception', 'embedded-ai', 'embedded-ai/engineering-numeracy', 70, 'misconception', 2, false, 'Why is it false that an equation passing a units check must be correct?', 'Dimensional analysis checks only the units, and it cannot see pure numbers, so a wrong constant such as $2$ or $\frac{1}{2}$ still passes.

Example: $d = vt$ and $d = 2vt$ both come out in meters. For a car at $10\,\mathrm{m/s}$ for $5\,\mathrm{s}$, only the first gives the right $50\,\mathrm{m}$; the second says $100\,\mathrm{m}$.

Key idea: A failed units check proves the equation is wrong. A passed check proves only that it is not wrong in its units.

Tip: Use the units check to catch structure errors, such as a missing time or an added quantity with the wrong unit, and test the numbers with a case you can compute by hand.', null, '{}'::text[], null, 'dimensional analysis limitations wrong constant passes units check', array['OpenStax University Physics Vol. 1, §1.4 Dimensional Analysis']::text[], array['units']::text[], null, false),
  ('embedded-ai/numeracy-charge-from-current-time', 'embedded-ai', 'embedded-ai/engineering-numeracy', 71, 'problem', 2, false, 'A current of $0.5\,\mathrm{A}$ flows for $200\,\mathrm{ms}$. Since $1\,\mathrm{C} = 1\,\mathrm{A \cdot s}$, the charge in coulombs is the current in amperes times the time in seconds. How much charge flows? Give the number of coulombs only.', '$0.1\,\mathrm{C}$

Step 1: Convert the time to seconds first: $200\,\mathrm{ms} = 200 \times 10^{-3}\,\mathrm{s} = 0.2\,\mathrm{s}$.

Step 2: Multiply: $0.5\,\mathrm{A} \times 0.2\,\mathrm{s} = 0.1\,\mathrm{A \cdot s} = 0.1\,\mathrm{C}$.

Watch out: Multiplying $0.5 \times 200 = 100$ mixes amperes with milliseconds. That $100$ is in $\mathrm{A \cdot ms}$, and $100\,\mathrm{A \cdot ms} = 0.1\,\mathrm{C}$, so it is not $100\,\mathrm{C}$. The answer would be $1000$ times too large.

Tip: Before you multiply, write every quantity in base units (A, s, m, kg).', '0.1', array['0.1 C', '1/10']::text[], '$0.1\,\mathrm{C}$', 'charge coulomb ampere times seconds milliseconds unit error', array['OpenStax University Physics Vol. 1, §1.3 Unit Conversion', 'OpenStax University Physics Vol. 1, §1.4 Dimensional Analysis']::text[], array['units']::text[], null, false),
  ('embedded-ai/numeracy-logarithm-definition', 'embedded-ai', 'embedded-ai/engineering-numeracy', 72, 'definition', 1, false, 'What does $\log_b(x) = y$ mean?', '$\log_b(x) = y$ means $b^y = x$: the logarithm is the exponent you must raise $b$ to in order to get $x$.

Example: $\log_2(8) = 3$ because $2^3 = 8$. Likewise $\log_{10}(1000) = 3$, and $\log_{10}(0.01) = -2$ because $10^{-2} = 0.01$.

Key idea: A logarithm counts how many times you multiply by the base.

Watch out: The input $x$ must be positive. No power of a positive base gives zero or a negative number, so $\log_b(0)$ and $\log_b(-5)$ do not exist.', null, '{}'::text[], null, 'logarithm definition exponent to get x log base b', array['OpenStax College Algebra 2e, §6.3 Logarithmic Functions']::text[], array['logarithms']::text[], null, false),
  ('embedded-ai/numeracy-named-logarithms', 'embedded-ai', 'embedded-ai/engineering-numeracy', 73, 'definition', 1, false, 'Name the **common logarithm**, the **natural logarithm** and the **binary logarithm**: which base does each use and how is each written?', 'Common: $\log_{10}$, base $10$. Natural: $\ln$, base $e \approx 2.718$. Binary: $\log_2$, base $2$.

The number $e$ is introduced later in this module. For now, treat $\ln$ as a button on the calculator.

Why it matters: Base $10$ fits powers of ten and decibels. Base $2$ fits bits and halving. Base $e$ fits natural growth and decay.

Watch out: A bare "log" is ambiguous. Calculators usually mean $\log_{10}$, computer science often means $\log_2$, and in Python `math.log(x)` is the natural logarithm. Write the base.', null, '{}'::text[], null, 'common natural binary logarithm log10 ln log2 base', array['OpenStax College Algebra 2e, §6.3 Logarithmic Functions']::text[], array['logarithms']::text[], null, false),
  ('embedded-ai/numeracy-inverse-function-log', 'embedded-ai', 'embedded-ai/engineering-numeracy', 74, 'concept', 1, false, 'Why do exponentials and logarithms undo each other? State $\log_b(b^x)$ and $b^{\log_b(x)}$.', 'They are **inverse functions**: $\log_b(b^x) = x$ and $b^{\log_b(x)} = x$ (for $x > 0$ in the second).

An inverse function is a rule that undoes another rule, like subtracting $5$ undoes adding $5$.

Why: By definition, $\log_b(x)$ is the exponent that turns $b$ into $x$. Raising $b$ to that exponent gives $x$ back. Going the other way, raising $b$ to $x$ and then asking "what exponent?" returns $x$.

Example: $\log_{10}(10^5) = 5$ and $2^{\log_2(7)} = 7$.

Tip: To solve $2^n = 1000$, take $\log_2$ of both sides: $n = \log_2(1000) \approx 9.97$.', null, '{}'::text[], null, 'logarithm inverse of exponential log_b(b^x) = x', array['OpenStax College Algebra 2e, §6.3 Logarithmic Functions']::text[], array['logarithms']::text[], null, false),
  ('embedded-ai/numeracy-log-product-rule', 'embedded-ai', 'embedded-ai/engineering-numeracy', 75, 'formula', 1, false, 'What is the **product rule** for logarithms: $\log_b(xy) = {?}$ (for $x, y > 0$)', '$\log_b(xy) = \log_b(x) + \log_b(y)$

Why: Logarithms are exponents, and exponents add when you multiply powers of the same base: $b^m \times b^n = b^{m+n}$.

Example: $\log_{10}(100 \times 1000) = \log_{10}(10^5) = 5$, and $2 + 3 = 5$.

Key idea: Logarithms turn multiplication into addition. The **quotient rule** is the mirror image: $\log_b(x/y) = \log_b(x) - \log_b(y)$.

Watch out: There is no simple rule for $\log_b(x + y)$. $\log_{10}(10 + 10) = \log_{10}(20) \approx 1.30$, which is not $1 + 1$.', null, '{}'::text[], null, 'logarithm product rule log of product equals sum of logs', array['OpenStax College Algebra 2e, §6.5 Logarithmic Properties']::text[], array['logarithms']::text[], null, false),
  ('embedded-ai/numeracy-evaluate-log2-1024', 'embedded-ai', 'embedded-ai/engineering-numeracy', 76, 'problem', 1, false, 'Evaluate $\log_2(1024)$ without a calculator. Give the number only.', '$10$

Ask: what power of $2$ gives $1024$? Double repeatedly: $2, 4, 8, 16, 32, 64, 128, 256, 512, 1024$. That is $10$ doublings, so $2^{10} = 1024$.

Why it matters: This is the same fact as "$10$ bits give $1024$ distinct values". The binary logarithm of the number of values is the number of bits.

Tip: Memorize $2^{10} = 1024 \approx 10^3$. It lets you estimate many logs quickly.', '10', array['ten']::text[], null, 'log2 1024 equals 10 binary logarithm powers of two', array['OpenStax College Algebra 2e, §6.3 Logarithmic Functions']::text[], array['logarithms']::text[], null, false),
  ('embedded-ai/numeracy-log-power-rule-digits', 'embedded-ai', 'embedded-ai/engineering-numeracy', 77, 'problem', 2, false, 'Given $\log_{10}(2) \approx 0.301$, estimate how many decimal digits $2^{64}$ has (the number of values of a 64-bit unsigned integer).', 'About $20$ digits: $2^{64} \approx 1.8 \times 10^{19}$.

The **power rule** for logarithms: $\log_b(x^k) = k \log_b(x)$. It follows from the exponent power rule.

Step 1: $\log_{10}(2^{64}) = 64 \times \log_{10}(2) \approx 64 \times 0.301 = 19.26$.

Step 2: So $2^{64} \approx 10^{19.26} = 10^{0.26} \times 10^{19}$, and $10^{0.26} \approx 1.8$.

Step 3: Every number from $10^{19}$ up to just below $10^{20}$ has $20$ digits ($10^{19}$ is a $1$ followed by $19$ zeros). So the count is $19 + 1 = 20$.

Check: The exact value is $18{,}446{,}744{,}073{,}709{,}551{,}616$, which has $20$ digits.', null, '{}'::text[], null, 'digits of 2^64 logarithm power rule log10 2 0.301', array['OpenStax College Algebra 2e, §6.5 Logarithmic Properties']::text[], array['logarithms']::text[], null, false),
  ('embedded-ai/numeracy-change-of-base', 'embedded-ai', 'embedded-ai/engineering-numeracy', 78, 'formula', 2, false, 'What is the **change of base** formula for $\log_b(x)$, using logarithms in a new base $c$?', '$\log_b(x) = \dfrac{\log_c(x)}{\log_c(b)}$

Why: Let $y = \log_b(x)$, so $b^y = x$. Take $\log_c$ of both sides and use the power rule: $y \log_c(b) = \log_c(x)$. Divide by $\log_c(b)$.

Example: A calculator with only $\log_{10}$ can find $\log_2(1000) = \dfrac{\log_{10}(1000)}{\log_{10}(2)} = \dfrac{3}{0.301} \approx 9.97$.

Watch out: This is a ratio of logs, not the log of a ratio. $\frac{\log_c(x)}{\log_c(b)}$ is not $\log_c(x/b)$.

Tip: Any base $c$ works for the new logs, so use whichever your calculator has, usually $10$ or $e$.', null, '{}'::text[], null, 'change of base formula logarithm log_b x = log x / log b', array['OpenStax College Algebra 2e, §6.5 Logarithmic Properties']::text[], array['logarithms']::text[], null, false),
  ('embedded-ai/numeracy-halvings-to-one', 'embedded-ai', 'embedded-ai/engineering-numeracy', 79, 'problem', 2, true, 'A list has $1000$ candidates. Each test splits the remaining candidates in half (rounding up when the count is odd) and keeps the larger half. At most how many tests leave a single candidate?', '$10$ tests, which is $\lceil \log_2(1000) \rceil = 10$.

Halve repeatedly, rounding up: $1000 \to 500 \to 250 \to 125 \to 63 \to 32 \to 16 \to 8 \to 4 \to 2 \to 1$. Counting the arrows gives $10$.

Why: Each test divides the count by $2$, so after $n$ tests about $1000 / 2^n$ remain. We need $2^n \ge 1000$. Since $2^9 = 512 < 1000 \le 1024 = 2^{10}$, $n = 10$.

Check: The change of base formula gives $\log_2(1000) \approx 9.97$, and rounding up gives $10$.

Key idea: This is also how many bits you need to number $1000$ items: $\lceil \log_2(1000) \rceil = 10$.', null, '{}'::text[], null, 'halvings to reach one ceiling log2 1000 equals 10', array['OpenStax College Algebra 2e, §6.3 Logarithmic Functions', 'OpenStax College Algebra 2e, §6.5 Logarithmic Properties']::text[], array['logarithms']::text[], null, false),
  ('embedded-ai/numeracy-decibel-power-ratio', 'embedded-ai', 'embedded-ai/engineering-numeracy', 80, 'definition', 2, false, 'What is a **decibel** (dB)? Give the formula that turns a **power ratio** $P_2/P_1$ into decibels.', '$L = 10\log_{10}\!\left(\dfrac{P_2}{P_1}\right)$ dB, where $P_2/P_1$ is the power ratio.

A **ratio** compares two quantities by dividing one by the other. A **power ratio** compares two powers, measured in watts. The decibel expresses that ratio on a log scale.

Example: Ratio $1$ is $0$ dB, ratio $10$ is $10$ dB, ratio $1000$ is $30$ dB, and ratio $0.1$ is $-10$ dB.

Watch out: A decibel is a ratio, not a unit of anything physical on its own. Negative dB means a loss (output weaker than input), $0$ dB means no change.

Why "deci": A bel is $\log_{10}$ of the ratio, and a decibel is one tenth of a bel.', null, '{}'::text[], null, 'decibel formula 10 log10 power ratio definition', array['OpenStax College Physics 2e, §17.3 Sound Intensity and Sound Level', 'OpenStax College Algebra 2e, §6.3 Logarithmic Functions']::text[], array['decibels']::text[], null, false),
  ('embedded-ai/numeracy-decibel-amplitude-ratio', 'embedded-ai', 'embedded-ai/engineering-numeracy', 81, 'formula', 2, false, 'What is the decibel formula for an **amplitude ratio** $A_2/A_1$ (amplitude: the strength of a signal, for example its voltage)?', '$L = 20\log_{10}\!\left(\dfrac{A_2}{A_1}\right)$ dB

Why: For the same circuit, power goes with the square of the amplitude: $P \propto A^2$. So $10\log_{10}\!\left(\frac{A_2^2}{A_1^2}\right) = 10 \times 2\log_{10}\!\left(\frac{A_2}{A_1}\right) = 20\log_{10}\!\left(\frac{A_2}{A_1}\right)$, by the power rule for logs.

Example: An amplitude ratio of $10$ is $+20$ dB. The power ratio is $10^2 = 100$ and $10\log_{10}(100) = 20$, so the two formulas agree.

Watch out: Using $10$ instead of $20$ for amplitudes gives half the right answer.', null, '{}'::text[], null, 'decibel formula 20 log10 amplitude ratio voltage', array['OpenStax College Physics 2e, §17.3 Sound Intensity and Sound Level', 'OpenStax College Algebra 2e, §6.3 Logarithmic Functions']::text[], array['decibels']::text[], null, false),
  ('embedded-ai/numeracy-3db-6db-rule', 'embedded-ai', 'embedded-ai/engineering-numeracy', 82, 'concept', 2, false, 'Roughly what power ratio is $+3$ dB, and what amplitude ratio is $+6$ dB?', '$+3$ dB is about twice the power, and $+6$ dB is about twice the amplitude.

Why: $10\log_{10}(2) \approx 3.01$ and $20\log_{10}(2) \approx 6.02$.

Example: $-3$ dB halves the power. $+6$ dB is two $+3$ dB steps, so power is $\times 4$, which is the same as amplitude $\times 2$ (power goes with amplitude squared).

Tip: Decibels add where ratios multiply. $+3$ dB then $+10$ dB means power $\times 2 \times 10 = \times 20$, which is about $+13$ dB.', null, '{}'::text[], null, '3 dB double power 6 dB double amplitude rule of thumb', array['OpenStax College Physics 2e, §17.3 Sound Intensity and Sound Level']::text[], array['decibels']::text[], null, false),
  ('embedded-ai/numeracy-why-decibels-dynamic-range', 'embedded-ai', 'embedded-ai/engineering-numeracy', 83, 'concept', 2, false, 'Why do engineers use decibels to describe quantities such as **dynamic range**?', 'A log scale squeezes huge ratios into small numbers, and when gains multiply, their decibel values simply add.

**Dynamic range** is the ratio between the largest and the smallest value a system can handle, often quoted in dB.

Example: An unsigned $16$-bit integer runs from $0$ to $65{,}535$, and its smallest nonzero step is $1$. The ratio $65{,}535$ is $20\log_{10}(65{,}535) \approx 96$ dB. Writing "$96$ dB" is far easier than "a ratio of $65{,}535$".

Key idea: A chain of an amplifier giving $+20$ dB and a filter giving $-6$ dB gives $+14$ dB in total. No multiplication is needed.', null, '{}'::text[], null, 'why decibels log scale dynamic range 16 bit 96 dB', array['OpenStax College Physics 2e, §17.3 Sound Intensity and Sound Level', 'OpenStax College Algebra 2e, §6.3 Logarithmic Functions']::text[], array['decibels']::text[], null, false),
  ('embedded-ai/numeracy-percent-error', 'embedded-ai', 'embedded-ai/engineering-numeracy', 84, 'problem', 2, false, 'A timer should last $250\,\mathrm{ms}$ but measures $262\,\mathrm{ms}$. What is the **percent error**, to one decimal place? Give the percent value only.', '$4.8\%$

Percent error compares the size of the mistake to the true value: $\dfrac{|\text{measured} - \text{true}|}{\text{true}} \times 100\%$.

Step 1: Size of the mistake: $|262 - 250| = 12$.

Step 2: Divide by the true value: $12 / 250 = 0.048$.

Step 3: Multiply by $100\%$ to get $4.8\%$.

Watch out: Divide by the true (reference) value. Dividing by the measured value gives $12/262 \approx 4.6\%$, which is wrong.

Tip: **Percent change** has the same shape: $\frac{\text{new} - \text{old}}{\text{old}} \times 100\%$, where a negative result is a decrease.', '4.8', array['4.8%', '+4.8%']::text[], '$4.8\%$', 'percent error formula measured true value 262 250', array['OpenStax University Physics Vol. 1, §1.3 Unit Conversion']::text[], array['ratios']::text[], null, false),
  ('embedded-ai/numeracy-amplifier-gain-db', 'embedded-ai', 'embedded-ai/engineering-numeracy', 85, 'problem', 2, true, 'An amplifier raises a signal''s power from $2\,\mathrm{mW}$ to $200\,\mathrm{mW}$. By how many decibels?', '$+20$ dB

Step 1: Find the power ratio: $200\,\mathrm{mW} / 2\,\mathrm{mW} = 100$. The units cancel.

Step 2: Apply the power formula: $10\log_{10}(100) = 10 \times 2 = 20$ dB.

Check: $\times 100$ is $\times 10 \times 10$, and each $\times 10$ is $10$ dB, so $10 + 10 = 20$.

Watch out: Use the ratio, not the difference ($200 - 2 = 198$). Also, these are powers, so the factor is $10$. Using $20$ would give $40$ dB.', null, '{}'::text[], null, 'amplifier gain decibels 2 mW to 200 mW 20 dB', array['OpenStax College Physics 2e, §17.3 Sound Intensity and Sound Level', 'OpenStax College Algebra 2e, §6.3 Logarithmic Functions']::text[], array['decibels']::text[], null, false),
  ('embedded-ai/numeracy-exponential-growth-doubling', 'embedded-ai', 'embedded-ai/engineering-numeracy', 86, 'definition', 2, false, 'What is **exponential growth**, and what is its **doubling time**?', 'A quantity that is multiplied by the same factor in every equal time step; the doubling time $T$ is how long one doubling takes, so $N = N_0 \cdot 2^{t/T}$.

Here $N_0$ is the starting value and $N$ the value after time $t$.

Example: A count starts at $3$ and doubles every hour. It goes $3, 6, 12, 24, 48, 96$, so after $5$ hours it is $3 \times 2^5 = 96$.

Watch out: After $n$ doublings the value is $N_0 \times 2^n$, not $N_0 \times 2n$.

Key idea: Exponential growth looks slow at first, then explodes.', null, '{}'::text[], null, 'exponential growth definition doubling time formula N0 2^(t/T)', array['OpenStax College Algebra 2e, §6.7 Exponential and Logarithmic Models']::text[], array['exponentials']::text[], null, false),
  ('embedded-ai/numeracy-eulers-number', 'embedded-ai', 'embedded-ai/engineering-numeracy', 87, 'definition', 2, false, 'What is **Euler''s number** $e$, and roughly how big is it?', '$e \approx 2.71828$, the base of the natural logarithm $\ln$ and of the growth and decay curve $e^t$.

Where it comes from: Compute $(1 + 1/n)^n$ for larger and larger $n$. For $n = 1$ you get $2$, for $n = 2$ you get $2.25$, for $n = 10$ about $2.594$, and for $n = 1000$ about $2.717$. The values settle toward $e$.

Why it matters: Curves built on $e$ describe natural processes, such as a capacitor discharging, with the neat property that the curve''s steepness at any point is proportional to its height.

Key idea: $\ln(x)$ means $\log_e(x)$, so $\ln(e) = 1$.

Tip: Remember $e^1 \approx 2.7$ and $e^{-1} \approx 0.37$.', null, '{}'::text[], null, 'Euler''s number e 2.71828 natural logarithm base definition', array['OpenStax College Algebra 2e, §6.7 Exponential and Logarithmic Models']::text[], array['exponentials']::text[], null, false),
  ('embedded-ai/numeracy-exponential-decay-time-constant', 'embedded-ai', 'embedded-ai/engineering-numeracy', 88, 'concept', 2, false, 'In **exponential decay** $N = N_0\,e^{-t/\tau}$, what does the **time constant** $\tau$ mean, and how much of $N_0$ is left at $t = \tau$?', '$\tau$ is the time for the quantity to fall to $1/e \approx 37\%$ of its starting value, a drop of about $63\%$.

Exponential decay means the quantity shrinks by the same factor in every equal time step. The curve starts steep and flattens out.

Example: Fraction left after $1\tau$, $2\tau$, $3\tau$, $5\tau$: $e^{-1} \approx 0.368$, $e^{-2} \approx 0.135$, $e^{-3} \approx 0.050$, $e^{-5} \approx 0.007$. After about $5\tau$ the quantity is nearly gone.

Watch out: The curve never reaches exactly zero. Also $\tau$ is not the half-time: the quantity halves after $\tau \ln 2 \approx 0.69\,\tau$.

Why it matters: The charge or voltage in a resistor-capacitor (RC) circuit decays with this shape; you will see this later.', null, '{}'::text[], null, 'exponential decay time constant tau e^(-t/tau) 37 percent', array['OpenStax College Algebra 2e, §6.7 Exponential and Logarithmic Models']::text[], array['exponentials']::text[], null, false),
  ('embedded-ai/numeracy-linear-quadratic-exponential-table', 'embedded-ai', 'embedded-ai/engineering-numeracy', 89, 'concept', 2, false, 'From a table of equally spaced inputs, how can you tell **linear**, **quadratic** and **exponential** growth apart?', 'Linear: equal differences between neighboring outputs. Quadratic: the differences themselves change by a constant amount. Exponential: equal ratios between neighboring outputs.

Example, for $x = 0, 1, 2, 3, 4$:

- Linear $3, 5, 7, 9, 11$: differences $2, 2, 2, 2$.
- Quadratic $0, 1, 4, 9, 16$: differences $1, 3, 5, 7$, which grow by $2$ each time.
- Exponential $1, 2, 4, 8, 16$: ratios $2, 2, 2, 2$.

Watch out: Exponential growth beats quadratic growth eventually, even if it starts lower. At $x = 3$, $x^2 = 9$ beats $2^x = 8$, but from $x = 5$ onward $2^x$ is larger ($32$ against $25$).

Tip: Check differences first, then ratios.', null, '{}'::text[], null, 'linear quadratic exponential growth table differences ratios', array['OpenStax College Algebra 2e, §6.7 Exponential and Logarithmic Models']::text[], array['exponentials']::text[], null, false),
  ('embedded-ai/numeracy-fermi-estimate-novel', 'embedded-ai', 'embedded-ai/engineering-numeracy', 90, 'example', 2, false, 'Make a **Fermi estimate** (a quick estimate from rough guesses) of how many bytes of plain text are in a $300$-page novel. Say which two powers of ten it lies between.', 'About $5 \times 10^5$ bytes, which lies between $10^5$ and $10^6$ (roughly $500\,\mathrm{kB}$).

Guess each piece to one digit: $300$ pages $\times$ $300$ words per page $\approx 90{,}000$ words. A word plus its space is about $6$ characters, and one ASCII character is one byte. So $90{,}000 \times 6 = 540{,}000 \approx 5 \times 10^5$ bytes.

The **order of magnitude** of a number is its power of ten. Two values within one order of magnitude differ by less than a factor of $10$.

Why it matters: A Fermi estimate tells you whether an answer is plausible before you build anything. A text file of this book should not be $5\,\mathrm{GB}$.

Tip: Individual guesses may be off, but errors above and below tend to cancel.', null, '{}'::text[], null, 'Fermi estimate order of magnitude bytes in a novel', array['OpenStax University Physics Vol. 1, §1.5 Estimates and Fermi Calculations']::text[], array['estimation']::text[], null, false),
  ('embedded-ai/numeracy-doublings-to-a-million', 'embedded-ai', 'embedded-ai/engineering-numeracy', 91, 'problem', 2, false, 'Start at $1$ and double at every step. How many doublings until the value first exceeds one million ($10^6$)? Give the number only.', '$20$

After $n$ doublings the value is $2^n$. We need $2^n > 10^6$.

Step 1: $2^{10} = 1024 \approx 10^3$, so $2^{20} \approx (10^3)^2 = 10^6$.

Step 2: Check exactly: $2^{19} = 524{,}288 < 10^6$ and $2^{20} = 1{,}048{,}576 > 10^6$. So $20$ is the first step that exceeds one million.

Check: $\log_2(10^6) = 6 \times 3.32 \approx 19.93$, and the next whole number is $20$.', '20', array['20 doublings', 'twenty']::text[], null, 'doublings to reach one million 2^20 exponential growth', array['OpenStax College Algebra 2e, §6.7 Exponential and Logarithmic Models']::text[], array['exponentials']::text[], null, false),
  ('embedded-ai/numeracy-function-definition', 'embedded-ai', 'embedded-ai/engineering-numeracy', 92, 'definition', 2, false, 'What is a **function** $f$, and what does $f(3)$ mean?', 'A function is a rule that gives exactly one output for each input; $f(3)$ is the output when the input is $3$.

Example: If $f(x) = 2x + 1$, then $f(3) = 2 \times 3 + 1 = 7$.

Why it matters: Engineers describe how one quantity depends on another, such as temperature as a function of time. A graph plots each input against its output.

Watch out: $f(3)$ does not mean $f \times 3$. The parentheses hold the input.

Tip: A graph is a function of $x$ if no vertical line crosses it more than once, because each input has only one output.', null, '{}'::text[], null, 'function definition one output for each input f(x) notation', array['OpenStax College Algebra 2e, §3.1 Functions and Function Notation']::text[], array['graphs']::text[], null, false),
  ('embedded-ai/numeracy-slope-definition', 'embedded-ai', 'embedded-ai/engineering-numeracy', 93, 'definition', 2, false, 'What is the **slope** of the straight line through the points $(x_1, y_1)$ and $(x_2, y_2)$?', '$\text{slope} = \dfrac{y_2 - y_1}{x_2 - x_1}$, the rise over the run.

The "rise" is the change in the vertical value and the "run" is the change in the horizontal value.

Example: Through $(1, 2)$ and $(5, 10)$ the slope is $\dfrac{10 - 2}{5 - 1} = \dfrac{8}{4} = 2$.

Key idea: Slope has units: the unit of $y$ per unit of $x$. If $y$ is meters and $x$ is seconds, slope is in $\mathrm{m/s}$.

Watch out: Subtract in the same order on top and bottom. Mixing the order flips the sign.', null, '{}'::text[], null, 'slope formula rise over run two points', array['OpenStax College Algebra 2e, §4.1 Linear Functions', 'OpenStax College Algebra 2e, §3.3 Rates of Change and Behavior of Graphs']::text[], array['graphs']::text[], null, false),
  ('embedded-ai/numeracy-slope-intercept-meaning', 'embedded-ai', 'embedded-ai/engineering-numeracy', 94, 'concept', 2, false, 'In the straight-line equation $y = mx + b$, what do $m$ and $b$ mean on a graph?', '$m$ is the slope, the **rate of change** of $y$ per unit of $x$; $b$ is the **intercept**, the value of $y$ where the line crosses the vertical axis (at $x = 0$).

An **axis** is a number line along an edge of the graph. The horizontal axis usually shows the input and the vertical axis the output, each labeled with units.

Example: A heater warms a room as $T = 22 + 3t$ in degrees Celsius with $t$ in minutes. The intercept $22\,^\circ\mathrm{C}$ is the starting temperature and the slope $3\,^\circ\mathrm{C}$ per minute is the rate of change.

Watch out: The intercept $b$ is the value at $x = 0$, not where the line meets the horizontal axis.', null, '{}'::text[], null, 'y = mx + b slope intercept rate of change meaning graph', array['OpenStax College Algebra 2e, §4.1 Linear Functions', 'OpenStax College Algebra 2e, §3.3 Rates of Change and Behavior of Graphs']::text[], array['graphs']::text[], null, false),
  ('embedded-ai/numeracy-reading-rise-fall-peak', 'embedded-ai', 'embedded-ai/engineering-numeracy', 95, 'example', 2, false, 'A temperature log reads $30\,^\circ\mathrm{C}$ at $0\,\mathrm{s}$, $45\,^\circ\mathrm{C}$ at $10\,\mathrm{s}$, $60\,^\circ\mathrm{C}$ at $20\,\mathrm{s}$, $55\,^\circ\mathrm{C}$ at $30\,\mathrm{s}$ and $50\,^\circ\mathrm{C}$ at $40\,\mathrm{s}$. Join the points with straight lines. Where is the graph increasing, decreasing and at its peak, and what is the rate of change in the first $20\,\mathrm{s}$?', 'Increasing from $0$ to $20\,\mathrm{s}$ at $1.5\,^\circ\mathrm{C/s}$, peak at $20\,\mathrm{s}$ ($60\,^\circ\mathrm{C}$), decreasing afterwards at $-0.5\,^\circ\mathrm{C/s}$.

A graph is increasing where it rises as you move right (positive slope) and decreasing where it falls (negative slope). The peak is the highest point, where it switches from rising to falling.

Step 1: Rise: $\dfrac{60 - 30}{20 - 0} = 1.5\,^\circ\mathrm{C/s}$.

Step 2: Fall: $\dfrac{50 - 60}{40 - 20} = -0.5\,^\circ\mathrm{C/s}$ (the same as $\frac{55 - 60}{10}$).

Watch out: The sign of the slope gives the direction, and the units tell you what it measures: degrees per second.', null, '{}'::text[], null, 'graph increasing decreasing peak slope rate of change temperature', array['OpenStax College Algebra 2e, §3.3 Rates of Change and Behavior of Graphs', 'OpenStax College Algebra 2e, §4.1 Linear Functions']::text[], array['graphs']::text[], null, false),
  ('embedded-ai/numeracy-log-scale-axis', 'embedded-ai', 'embedded-ai/engineering-numeracy', 96, 'concept', 2, false, 'On a **log scale** axis, what does each major gridline represent, and what do equal distances mean?', 'Each major gridline is ten times the previous one, and equal distances mean equal ratios, not equal differences.

Example: Gridlines labeled $1, 10, 100, 1000, 10{,}000$ are evenly spaced. The step from $10$ to $100$ looks as long as the step from $1000$ to $10{,}000$, although the second is $9000$ units and the first is $90$.

Why: The position along the axis is proportional to $\log_{10}$ of the value.

Watch out: Zero and negative numbers cannot appear on a log axis, because their logarithm does not exist.

Tip: Between two gridlines the labels $2, 3, \ldots, 9$ get closer and closer together. Reading values there is not linear.', null, '{}'::text[], null, 'log scale axis gridlines factor of ten equal ratios', array['OpenStax College Algebra 2e, §6.8 Fitting Exponential Models to Data']::text[], array['graphs']::text[], null, false),
  ('embedded-ai/numeracy-log-axis-midpoint-misconception', 'embedded-ai', 'embedded-ai/engineering-numeracy', 97, 'misconception', 2, false, 'Why is it false that on a log axis the point halfway (in distance) between $10^2$ and $10^4$ is the average, $5050$?', 'Equal distance means equal ratio, so the halfway point is $10^3 = 1000$, not the average $5050$.

From $100$ to $1000$ the value is multiplied by $10$, and from $1000$ to $10{,}000$ it is multiplied by $10$ again. Both steps take the same distance on the axis, so $1000$ sits in the middle.

Key idea: On an ordinary axis, equal distances are equal differences. On a log axis they are equal factors.

Watch out: Reading a log axis as if it were linear is a common cause of wrong answers. The point $5050$ would sit much closer to the $10^4$ end.', null, '{}'::text[], null, 'log axis midpoint halfway equal ratio not average misconception', array['OpenStax College Algebra 2e, §6.8 Fitting Exponential Models to Data']::text[], array['graphs']::text[], null, false),
  ('embedded-ai/numeracy-semi-log-straight-line', 'embedded-ai', 'embedded-ai/engineering-numeracy', 98, 'concept', 2, false, 'Why do exponential data plot as a straight line on a **semi-log plot** (a log axis for $y$, an ordinary axis for $x$)?', 'Because $y = y_0\,b^x$ gives $\log_{10}(y) = \log_{10}(y_0) + x\,\log_{10}(b)$, a straight line in $x$ with slope $\log_{10}(b)$.

On a semi-log plot only one axis is logarithmic. On a **log-log plot** both are, and power laws $y = k x^p$ become straight lines there.

Example: Doubling data $1, 2, 4, 8, 16$ has $\log_{10}$ values $0, 0.30, 0.60, 0.90, 1.20$: equal steps, so a straight line.

Tip: A steeper line means a bigger growth factor. A line that curves upward on a semi-log plot is growing faster than exponentially.

Why it matters: A straight line on semi-log paper is the quickest check that data are exponential.', null, '{}'::text[], null, 'semi-log plot exponential straight line log-log plot power law', array['OpenStax College Algebra 2e, §6.8 Fitting Exponential Models to Data']::text[], array['graphs']::text[], null, false),
  ('embedded-ai/numeracy-semi-log-read-value', 'embedded-ai', 'embedded-ai/engineering-numeracy', 99, 'problem', 2, false, 'On a semi-log plot (log axis for $y$), a straight line passes through $(t, y) = (0\,\mathrm{s}, 10)$ and $(2\,\mathrm{s}, 1000)$. What is $y$ at $t = 3\,\mathrm{s}$?', '$y = 10{,}000$, because $y$ is multiplied by $10$ every second.

A straight line on a semi-log plot means $y$ is multiplied by the same factor in every equal time step.

Step 1: From $t = 0$ to $t = 2\,\mathrm{s}$, $y$ grows from $10$ to $1000$, a factor of $100$.

Step 2: Two equal steps multiply to $100$, so each one-second step is $\times 10$, because $10 \times 10 = 100$.

Step 3: At $3\,\mathrm{s}$: $1000 \times 10 = 10{,}000$.

Check: $\log_{10}(y)$ goes $1 \to 3$ in $2\,\mathrm{s}$, a slope of $1$ per second, so at $3\,\mathrm{s}$ it is $4$ and $y = 10^4$.', null, '{}'::text[], null, 'semi-log plot straight line read value factor per second', array['OpenStax College Algebra 2e, §6.8 Fitting Exponential Models to Data']::text[], array['graphs']::text[], null, false),
  ('embedded-ai/electricity-electric-charge', 'embedded-ai', 'embedded-ai/electricity-basics', 100, 'definition', 1, false, 'What is **electric charge**, and what are its two kinds?', 'A property of matter that makes it push or pull on other charged matter; it comes in two kinds, positive and negative.

Like charges repel each other and opposite charges attract. Matter is made of atoms, which contain tiny particles: electrons carry negative charge and protons carry positive charge. Most objects hold equal amounts of both, so they are neutral overall.

Example: Rub a balloon on your hair. Electrons move from the hair to the balloon, so the balloon ends up negative and the hair positive. The hair lifts toward the balloon because opposite charges attract.

Key idea: Electronics is the craft of controlling how charge moves.', null, '{}'::text[], null, 'electric charge positive negative attract repel', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-coulomb', 'embedded-ai', 'embedded-ai/electricity-basics', 101, 'definition', 1, false, 'What is a **coulomb** (C), the unit of electric charge, in terms of electrons?', 'The unit of charge; $1\,\mathrm{C}$ is the charge of about $6.24 \times 10^{18}$ electrons.

Why: One electron carries a charge of size $1.602 \times 10^{-19}\,\mathrm{C}$. Dividing $1$ by that number gives about $6.24 \times 10^{18}$ electrons per coulomb.

Tip: Static charge, like the charge on a rubbed balloon, is only a tiny fraction of a coulomb. Charge flowing through a wire adds up quickly, though: $1\,\mathrm{A}$ moves $1\,\mathrm{C}$ past a point every second.', null, '{}'::text[], null, 'coulomb unit of charge electrons 6.24e18', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-current-ampere', 'embedded-ai', 'embedded-ai/electricity-basics', 102, 'definition', 1, false, 'What is **current**, and what does 1 **ampere** (A) mean?', 'Current is the rate at which charge flows, $I = Q/t$; $1\,\mathrm{A} = 1\,\mathrm{C/s}$.

Here $Q$ is the charge in coulombs that passes a point in the wire and $t$ is the time in seconds. If the flow is not steady, $Q/t$ gives the average current over that time. People often say "amp" for ampere.

Example: If $3\,\mathrm{C}$ passes a point in $2\,\mathrm{s}$, the current is $3/2 = 1.5\,\mathrm{A}$.

Watch out: Current is a rate, like speed. It tells you how much charge passes per second, not how much has passed in total.', null, '{}'::text[], null, 'current definition ampere coulomb per second', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §9.1']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-voltage-volt', 'embedded-ai', 'embedded-ai/electricity-basics', 103, 'definition', 1, false, 'What is **voltage** (potential difference), and what does 1 **volt** (V) mean?', 'Voltage is the energy per unit charge between two points; $1\,\mathrm{V} = 1\,\mathrm{J/C}$.

It tells you how much energy each coulomb gains or loses when it moves from one point to the other.

Example: A $9\,\mathrm{V}$ battery gives every coulomb that moves through it $9\,\mathrm{J}$. The charge then hands that energy to whatever is in the loop, such as a lamp.

Watch out: Voltage always exists between two points. "The voltage at a point" really means the voltage between that point and an agreed reference point.', null, '{}'::text[], null, 'voltage potential difference volt joule per coulomb', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-charge-from-current', 'embedded-ai', 'embedded-ai/electricity-basics', 104, 'example', 1, false, 'A sensor draws a steady $20\,\mathrm{mA}$ for one minute. How much charge flows through it?', '$1.2\,\mathrm{C}$

Rearrange $I = Q/t$ into $Q = I \cdot t$. Convert to base units first: $20\,\mathrm{mA} = 0.020\,\mathrm{A}$ and one minute is $60\,\mathrm{s}$, so $Q = 0.020 \times 60 = 1.2\,\mathrm{C}$. That is about $1.2 \times 6.24 \times 10^{18} \approx 7.5 \times 10^{18}$ electrons.

Key idea: Current multiplied by time is charge. The same idea later turns a battery''s milliamp-hours into a running time.

Watch out: Convert milliamps to amps and minutes to seconds before multiplying. Skipping the first step makes the answer $1000$ times too big.', null, '{}'::text[], null, 'charge equals current times time worked example', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-water-pipe-analogy', 'embedded-ai', 'embedded-ai/electricity-basics', 105, 'concept', 1, false, 'In the water-pipe analogy, what do voltage and current correspond to, and how does a break in a wire differ from a cut pipe?', 'Voltage is like the water pressure difference and current like the flow rate; but a cut pipe spills water, while a break in a wire spills no charge and stops the current everywhere in the loop.

A pump (the battery) creates a pressure difference (voltage), water moves through the pipe (current), and a narrow pipe holds the flow back (resistance, coming up next). More pressure gives more flow.

Watch out: Charge only moves around a complete, unbroken loop, called a **circuit**. That is why one break stops the current everywhere, not just at the gap.

Tip: Use the analogy for intuition and use the units (V, A, C) for numbers.', null, '{}'::text[], null, 'water pipe analogy voltage current electricity', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-ground-reference', 'embedded-ai', 'embedded-ai/electricity-basics', 106, 'concept', 1, false, 'What is **ground** in a circuit, and why do we need a 0 V reference?', 'Ground is the point chosen as $0\,\mathrm{V}$; every other voltage in the circuit is measured relative to it.

Voltage only exists between two points. Naming one point $0\,\mathrm{V}$ lets us say "this wire is at $5\,\mathrm{V}$" and mean "$5\,\mathrm{V}$ above ground".

Example: In a battery-powered gadget, ground is usually the battery''s negative terminal, the − end where wires connect. A wire at $3.3\,\mathrm{V}$ is then $3.3\,\mathrm{V}$ above that terminal.

Watch out: Which point you call ground is a convention. Picking a different point changes the voltage labels, but not the currents or the voltage between any two points.', null, '{}'::text[], null, 'ground 0 V reference point circuit', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-current-not-used-up', 'embedded-ai', 'embedded-ai/electricity-basics', 107, 'misconception', 1, false, 'Why is it false that a lamp “uses up” current, so less current returns to the battery than left it?', 'False: the same current flows through every part of a single loop; charge passes through the lamp and gives up energy there, but no charge is used up.

Why: In a steady circuit, charge can''t vanish or pile up, so the same number of coulombs per second pass every point of a single loop. What changes along the loop is the energy each coulomb carries.

Example: In a closed water loop with a water wheel, the same amount of water per second reaches the wheel and leaves it. The water just arrives with higher pressure than it leaves.

Key idea: Current is conserved around a single loop; energy is what gets used.', null, '{}'::text[], null, 'current used up lamp misconception same current loop', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-conventional-current', 'embedded-ai', 'embedded-ai/electricity-basics', 108, 'misconception', 1, false, 'Why is it false that the current arrow on a circuit diagram points the way electrons move?', 'False: **conventional current** is the direction positive charge would move, from + to − through the circuit outside the battery, which is opposite to the way electrons move in a metal wire.

The convention was set before electrons were discovered. Positive charge moving one way has the same effect on a circuit as negative charge moving the other way, so the math works either way. Inside the battery, conventional current continues from − back to +, completing the loop.

Tip: Almost every formula, diagram and textbook in electronics uses conventional current. Follow the current from the + terminal, around the loop, back to the − terminal, and forget the electrons.', null, '{}'::text[], null, 'conventional current direction electron flow opposite', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §9.1']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-resistance-ohm', 'embedded-ai', 'embedded-ai/electricity-basics', 109, 'definition', 1, false, 'What is **resistance**, and what unit measures it?', 'How strongly a part opposes current; measured in ohms ($\Omega$), where $1\,\Omega = 1\,\mathrm{V/A}$.

For the same voltage, more resistance means less current. One ohm lets $1\,\mathrm{A}$ flow when $1\,\mathrm{V}$ is applied.

A **conductor**, such as copper, is a material that lets charge move through it easily, so a copper wire has very low resistance. An **insulator**, such as rubber, plastic or air, lets almost no charge through, so its resistance is extremely high.

Tip: Larger values use prefixes: $1\,\mathrm{k\Omega} = 1000\,\Omega$ and $1\,\mathrm{M\Omega} = 10^6\,\Omega$.', null, '{}'::text[], null, 'resistance definition ohm conductor insulator', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §9.3']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-resistor-part', 'embedded-ai', 'embedded-ai/electricity-basics', 110, 'definition', 1, false, 'What is a **resistor**?', 'A two-terminal part built to have a specific, steady resistance, used to control how much current flows.

Resistors come in values from fractions of an ohm to many megohms. On resistors with wire legs, the value is usually shown as colored bands.

Example: Putting a $330\,\Omega$ resistor in a loop with a battery limits the current; the larger the resistance, the smaller the current.

Watch out: A fixed resistor has no polarity. It works the same whichever way round you connect it.', null, '{}'::text[], null, 'resistor definition fixed resistance part current limit', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 3']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-ohms-law', 'embedded-ai', 'embedded-ai/electricity-basics', 111, 'formula', 1, false, 'State **Ohm''s law** relating voltage, current and resistance.', '$V = I \cdot R$, where $R$ stays constant for a given resistor; $V$ in volts, $I$ in amps, $R$ in ohms.

Rearranged: $I = V/R$ and $R = V/I$. Pick the form that has your unknown alone on the left.

Key idea: $R = V/I$ is just what resistance means. Ohm''s law adds that for a resistor this ratio stays the same whatever the voltage (at a steady temperature), so the current is proportional to the voltage. Some parts break this rule, as a later card shows.

Tip: Volts, kilohms and milliamps fit together: $1\,\mathrm{k\Omega} \times 1\,\mathrm{mA} = 1\,\mathrm{V}$. Use this to skip the conversion to base units.', null, '{}'::text[], null, 'Ohm''s law V equals I R formula', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §9.4']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-ohms-law-proportional', 'embedded-ai', 'embedded-ai/electricity-basics', 112, 'example', 1, false, 'A resistor carries $2\,\mathrm{mA}$ when $2\,\mathrm{V}$ is across it. Assuming it follows Ohm''s law, what current flows at $6\,\mathrm{V}$?', '$6\,\mathrm{mA}$

The resistance is $R = V/I = 2\,\mathrm{V} / 2\,\mathrm{mA} = 1\,\mathrm{k\Omega}$. At $6\,\mathrm{V}$, $I = 6\,\mathrm{V} / 1\,\mathrm{k\Omega} = 6\,\mathrm{mA}$.

Key idea: For a resistor, current is proportional to voltage. Triple the voltage and the current triples.

Tip: You can skip the resistance. The voltage tripled, so the current triples to $6\,\mathrm{mA}$.', null, '{}'::text[], null, 'Ohm''s law current proportional to voltage example', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §9.4']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-open-short-circuit', 'embedded-ai', 'embedded-ai/electricity-basics', 113, 'concept', 2, false, 'What are an **open circuit** and a **short circuit**, and why can a short damage the supply?', 'An open circuit has a break, so no current flows; a short circuit is a near-zero-resistance path that lets current bypass parts, and one straight across the supply draws a huge current that overheats the wires and the supply.

The **supply** is the battery or other source that powers the circuit. An open circuit has an air gap, and air is an insulator. In a short across the supply, $I = V/R$ with $R$ close to zero gives a very large current, limited only by the supply itself and the wires, which heat up and can be damaged.

Example: A loose wire leaves the loop open, so the lamp stays off. A stray wire laid straight across a battery''s terminals is a short: the wire and the battery get hot, and with a big battery, such as a car battery, the wire can get hot enough to start a fire.

Watch out: A short around a part also starves that part. The current takes the easy path and the part gets almost none.', null, '{}'::text[], null, 'open circuit short circuit difference damage supply', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-led-not-ohmic', 'embedded-ai', 'embedded-ai/electricity-basics', 114, 'misconception', 2, false, 'Why is it false that an LED behaves like a fixed resistance, so its current is always its voltage divided by a constant?', 'False: connected the right way round, an LED passes almost no current until its voltage nears a threshold, then the current rises very steeply, so $V/I$ is not constant.

A **diode** is a part that lets current flow easily in one direction only. An **LED** is a light-emitting diode. A typical red LED needs about $2\,\mathrm{V}$ to pass its usual working current of about $20\,\mathrm{mA}$; half a volt less, it passes almost nothing.

Why: Above the threshold a small voltage increase causes a large current increase. Connected straight to a supply such as $5\,\mathrm{V}$, an LED can draw so much current that it burns out.

Tip: Ohm''s law still holds for a resistor placed in the same loop. Use that resistor to set the current through the LED.', null, '{}'::text[], null, 'LED diode not obey Ohm''s law threshold voltage', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 3']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-problem-current-250-ohm', 'embedded-ai', 'embedded-ai/electricity-basics', 115, 'problem', 1, false, 'A $250\,\Omega$ resistor has $5\,\mathrm{V}$ across it. How many milliamps flow through it? (Give the number only.)', '$20\,\mathrm{mA}$

Use $I = V/R = 5\,\mathrm{V} / 250\,\Omega = 0.02\,\mathrm{A}$. Multiply by $1000$ to get $20\,\mathrm{mA}$.

Watch out: Amps times 1000 is milliamps. $0.02\,\mathrm{A}$ is $20\,\mathrm{mA}$, not $2\,\mathrm{mA}$.', '20', array['20 mA']::text[], '$20\,\mathrm{mA}$', 'current through 250 ohm resistor 5 volts', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-problem-current-10k', 'embedded-ai', 'embedded-ai/electricity-basics', 116, 'problem', 2, false, 'A $3.3\,\mathrm{V}$ supply is connected across a $10\,\mathrm{k\Omega}$ resistor. What current flows, in microamps?', '$330\,\mu\mathrm{A}$

$I = V/R = 3.3\,\mathrm{V} / 10\,000\,\Omega = 0.00033\,\mathrm{A}$. Since $1\,\mathrm{A} = 10^6\,\mu\mathrm{A}$, that is $330\,\mu\mathrm{A}$.

Tip: With kilohms and volts the answer comes out in milliamps: $3.3 / 10 = 0.33\,\mathrm{mA}$. Convert to microamps by multiplying by $1000$.', null, '{}'::text[], null, '3.3 volts 10 kilohm resistor current microamps', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-problem-resistance-from-vi', 'embedded-ai', 'embedded-ai/electricity-basics', 117, 'problem', 2, false, 'A resistor passes $40\,\mathrm{mA}$ when $12\,\mathrm{V}$ is across it. What is its resistance in ohms? (Give the number only.)', '$300\,\Omega$

Use $R = V/I = 12\,\mathrm{V} / 0.040\,\mathrm{A} = 300\,\Omega$.

Check: $300\,\Omega \times 0.040\,\mathrm{A} = 12\,\mathrm{V}$, which matches.

Watch out: Divide by $0.040\,\mathrm{A}$, not $40$. Using $40$ gives $0.3\,\Omega$, which is wrong by a factor of 1000.', '300', array['300 ohm', '300 ohms', '300 Ω']::text[], '$300\,\Omega$', 'resistance from voltage and current 12 V 40 mA', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-power-watt', 'embedded-ai', 'embedded-ai/electricity-basics', 118, 'definition', 1, false, 'What is **electrical power**, and what does 1 **watt** (W) mean?', 'Power is the rate at which energy is transferred; $1\,\mathrm{W} = 1\,\mathrm{J/s}$.

A device that uses $60\,\mathrm{W}$ converts $60\,\mathrm{J}$ of electrical energy every second into light, heat, motion or similar.

Watch out: Power is a rate, not an amount of energy. Higher power drains the same battery faster.', null, '{}'::text[], null, 'electrical power watt joule per second definition', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §9.5']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-power-vi', 'embedded-ai', 'embedded-ai/electricity-basics', 119, 'formula', 1, false, 'How do you calculate electrical power from voltage and current?', '$P = V \cdot I$ (watts = volts × amps).

Why: Voltage is energy per coulomb ($\mathrm{J/C}$) and current is coulombs per second ($\mathrm{C/s}$). Multiplying them gives joules per second, which is watts.

Example: A $12\,\mathrm{V}$ motor drawing $2\,\mathrm{A}$ uses $12 \times 2 = 24\,\mathrm{W}$.', null, '{}'::text[], null, 'power formula P equals V times I watts', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §9.5']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-power-vs-energy', 'embedded-ai', 'embedded-ai/electricity-basics', 120, 'concept', 1, false, 'What is the difference between power and **energy**, and how are they linked?', 'Power is the rate (W = J/s); energy is the total amount transferred, $E = P \cdot t$ for a steady power, measured in joules or **watt-hours** (Wh).

One watt-hour is the energy used by $1\,\mathrm{W}$ running for one hour: $1\,\mathrm{W} \times 3600\,\mathrm{s} = 3600\,\mathrm{J}$.

Example: A $5\,\mathrm{W}$ device running for $3\,\mathrm{h}$ uses $15\,\mathrm{Wh}$.

Watch out: "Watts per hour" is a common error. Power is already a rate, so energy is watts times hours, written Wh.', null, '{}'::text[], null, 'power versus energy watt hour joule 3600', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §9.5']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-power-i2r-v2r', 'embedded-ai', 'embedded-ai/electricity-basics', 121, 'formula', 2, false, 'Using Ohm''s law, write the power dissipated in a resistor using only $I$ and $R$, and using only $V$ and $R$.', '$P = I^2 R$ (no $V$ needed) and $P = V^2 / R$ (no $I$ needed).

Substitute $V = IR$ into $P = VI$ to get $P = I^2 R$. Substitute $I = V/R$ to get $P = V^2/R$.

**Power dissipation** is the electrical power a part turns into heat. A resistor turns all of its $V \cdot I$ into heat.

Example: A $100\,\Omega$ resistor across $12\,\mathrm{V}$ dissipates $12^2/100 = 1.44\,\mathrm{W}$.

Watch out: Current and voltage are squared. In the same resistor, doubling the current quadruples the heat.', null, '{}'::text[], null, 'power I squared R V squared over R dissipation', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §9.5']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-power-rating', 'embedded-ai', 'embedded-ai/electricity-basics', 122, 'definition', 2, false, 'What is a resistor''s **power rating**, and how much margin should you leave?', 'The maximum power it can dissipate continuously without overheating; choose a rating comfortably above the calculated dissipation, such as double.

Common ratings are $1/8$, $1/4$, $1/2$, $1$ and $2\,\mathrm{W}$. A bigger rating usually means a physically bigger resistor. The rating assumes the resistor can shed its heat into cool air; inside a hot case it can safely handle less.

Watch out: The rating is a limit, not what the resistor uses. A $1/4\,\mathrm{W}$ resistor dissipates only what its voltage and current dictate.

Tip: Compute $P$ first, then pick the next standard rating that gives about $2\times$ headroom (spare margin).', null, '{}'::text[], null, 'resistor power rating watt margin overheating', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 3']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-problem-power-150ma', 'embedded-ai', 'embedded-ai/electricity-basics', 123, 'problem', 1, false, 'A device draws $150\,\mathrm{mA}$ from a $3.3\,\mathrm{V}$ supply. What power does it use, in milliwatts? (Give the number only.)', '$495\,\mathrm{mW}$

$P = V \cdot I = 3.3\,\mathrm{V} \times 0.150\,\mathrm{A} = 0.495\,\mathrm{W} = 495\,\mathrm{mW}$.

Tip: Volts times milliamps gives milliwatts directly: $3.3 \times 150 = 495$.', '495', array['495 mW']::text[], '$495\,\mathrm{mW}$', 'power 3.3 V 150 mA milliwatts', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-problem-wh-to-joules', 'embedded-ai', 'embedded-ai/electricity-basics', 124, 'problem', 2, false, 'How many joules are in $2.5\,\mathrm{Wh}$? (Give the number only.)', '$9000\,\mathrm{J}$

Use $1\,\mathrm{Wh} = 3600\,\mathrm{J}$, so $2.5 \times 3600 = 9000\,\mathrm{J}$.

Why: One watt-hour is $1\,\mathrm{J/s}$ for $3600\,\mathrm{s}$, which is $3600\,\mathrm{J}$.

Watch out: Going from joules to watt-hours means dividing by $3600$.', '9000', array['9000 J']::text[], '$9000\,\mathrm{J}$', 'convert watt hours to joules 3600', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-problem-resistor-rating', 'embedded-ai', 'embedded-ai/electricity-basics', 125, 'problem', 2, false, 'A $330\,\Omega$ resistor will have $12\,\mathrm{V}$ across it. How much power does it dissipate, and which standard rating should you use from $1/8$, $1/4$, $1/2$, $1$ and $2\,\mathrm{W}$, leaving about double headroom?', 'About $0.44\,\mathrm{W}$, so use a $1\,\mathrm{W}$ resistor.

$P = V^2/R = 144/330 \approx 0.436\,\mathrm{W}$. Double headroom means a rating of at least about $0.87\,\mathrm{W}$, and the smallest standard rating above that is $1\,\mathrm{W}$.

Watch out: A $1/4\,\mathrm{W}$ resistor would be overloaded and could burn out. A $1/2\,\mathrm{W}$ one would be within its rating but run hot, with almost no margin.', null, '{}'::text[], null, 'resistor power dissipation 330 ohm 12 V rating choice', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-series-circuit', 'embedded-ai', 'embedded-ai/electricity-basics', 126, 'definition', 1, false, 'What is a **series circuit**?', 'A circuit whose parts are connected end to end in a single chain, so the same current flows through each of them.

There is only one path for the charge to follow, so every part sees the same current.

Example: A battery, a switch and a resistor wired one after another in one loop form a series circuit.

Watch out: A break anywhere in a series chain stops the current in every part. Old strings of lights failed this way when one bulb burned out.', null, '{}'::text[], null, 'series circuit definition single path same current', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §10.2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-parallel-circuit', 'embedded-ai', 'embedded-ai/electricity-basics', 127, 'definition', 1, false, 'What is a **parallel circuit**, and what are **nodes** and **branches**?', 'A circuit whose parts each connect across the same two nodes, each on its own branch; a node is a point where parts connect, and a branch is a path between two nodes that holds one part.

Every point joined by plain wire, with no part in between, counts as the same **node**. So however many junctions the wiring has, a parallel circuit has just two nodes, and every **branch** runs from one to the other. Current can take any branch.

Key idea: Each part in parallel is connected straight across the same two nodes, so each gets the full voltage between them.

Watch out: A break in one branch leaves the other branches working.', null, '{}'::text[], null, 'parallel circuit definition node branch', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §10.2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-same-current-same-voltage', 'embedded-ai', 'embedded-ai/electricity-basics', 128, 'concept', 1, false, 'Which quantity is the same for every part in series, and which is the same for every part in parallel?', 'Series parts share the same current; parallel parts share the same voltage.

In series the voltage divides. Each part''s share is its **voltage drop**, the voltage across it, and the drops add up to the voltage across the whole chain (the supply voltage, when the chain is the only loop).

In parallel the current divides among the branches. Such a split is a **current divider**, and the branch currents add up to the total. The branch with the lowest resistance takes the biggest share.

Mnemonic: Series: same current. Parallel: same voltage.', null, '{}'::text[], null, 'series same current parallel same voltage drop current divider', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §10.2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-series-resistance-sum', 'embedded-ai', 'embedded-ai/electricity-basics', 129, 'example', 1, false, 'Resistors of $1\,\mathrm{k\Omega}$, $2.2\,\mathrm{k\Omega}$ and $4.7\,\mathrm{k\Omega}$ are connected in series. What is the **equivalent resistance**?', '$7.9\,\mathrm{k\Omega}$

The equivalent resistance is the single resistor that would draw the same current from the same supply. In series, resistances add: $1 + 2.2 + 4.7 = 7.9\,\mathrm{k\Omega}$.

Why: The same current passes through all three, and each one adds its own voltage drop. The total voltage over the current ($V/I$) is the sum.

Key idea: A series total is always larger than the biggest resistor in the chain.', null, '{}'::text[], null, 'series resistors add equivalent resistance example', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §10.2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-equivalent-resistance-parallel', 'embedded-ai', 'embedded-ai/electricity-basics', 130, 'formula', 2, false, 'Give the **equivalent resistance** of two resistors $R_1$ and $R_2$ in parallel (the product-over-sum form).', '$R_{\mathrm{eq}} = \dfrac{R_1 R_2}{R_1 + R_2}$, from $\dfrac{1}{R_{\mathrm{eq}}} = \dfrac{1}{R_1} + \dfrac{1}{R_2}$.

In parallel the equivalent resistance is always smaller than the smallest resistor, because adding a branch gives the current another path.

Tip: Two equal resistors in parallel give half the value: $R_{\mathrm{eq}} = R/2$.

Watch out: The product-over-sum shortcut works for two resistors only. For three or more, add the reciprocals.', null, '{}'::text[], null, 'parallel resistance formula product over sum equivalent', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §10.2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-household-parallel', 'embedded-ai', 'embedded-ai/electricity-basics', 131, 'concept', 2, false, 'Why are household loads such as lamps and kettles wired in parallel rather than in series?', 'Parallel gives every load the full supply voltage, and one load switching off doesn''t affect the others.

A **load** is anything that draws power from the supply, such as a lamp or a kettle. Each appliance is designed for the supply voltage. In series they would share that voltage and each get less. Switching one off would also break the loop for all of them.

Example: Turn off your lamp and the fridge keeps running, since each is on its own branch.

Watch out: More loads in parallel means more total current from the supply, because each branch adds its own current.', null, '{}'::text[], null, 'household appliances wired in parallel not series why', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §10.2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-problem-series-drop', 'embedded-ai', 'embedded-ai/electricity-basics', 132, 'problem', 2, true, 'A $9\,\mathrm{V}$ supply drives a $1\,\mathrm{k\Omega}$ resistor and a $2\,\mathrm{k\Omega}$ resistor in series. What is the voltage drop across the $2\,\mathrm{k\Omega}$ resistor, in volts? (Give the number only.)', '$6\,\mathrm{V}$

The total resistance is $3\,\mathrm{k\Omega}$, so the current is $9\,\mathrm{V}/3\,\mathrm{k\Omega} = 3\,\mathrm{mA}$. The drop across $2\,\mathrm{k\Omega}$ is $3\,\mathrm{mA} \times 2\,\mathrm{k\Omega} = 6\,\mathrm{V}$.

Check: The other drop is $3\,\mathrm{mA} \times 1\,\mathrm{k\Omega} = 3\,\mathrm{V}$, and $3 + 6 = 9\,\mathrm{V}$.

Key idea: In series the drops share the supply in proportion to the resistances: $2/3$ of $9\,\mathrm{V}$ is $6\,\mathrm{V}$.', '6', array['6 V']::text[], '$6\,\mathrm{V}$', 'series resistors voltage drop 9 V 1k 2k', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §10.2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-problem-parallel-resistance', 'embedded-ai', 'embedded-ai/electricity-basics', 133, 'problem', 2, false, 'A $6\,\mathrm{k\Omega}$ resistor and a $3\,\mathrm{k\Omega}$ resistor are connected in parallel. What is the equivalent resistance, in kilohms? (Give the number only.)', '$2\,\mathrm{k\Omega}$

Product over sum: $\dfrac{6 \times 3}{6 + 3} = \dfrac{18}{9} = 2\,\mathrm{k\Omega}$.

Check: The result is smaller than the smaller resistor ($3\,\mathrm{k\Omega}$), as it must be in parallel.', '2', array['2 kohm', '2k', '2 kΩ']::text[], '$2\,\mathrm{k\Omega}$', 'parallel resistors 6k 3k equivalent resistance', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §10.2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-problem-current-divider', 'embedded-ai', 'embedded-ai/electricity-basics', 134, 'problem', 2, false, 'A total of $12\,\mathrm{mA}$ enters a parallel pair of a $1\,\mathrm{k\Omega}$ and a $3\,\mathrm{k\Omega}$ resistor. What current flows in each?', '$9\,\mathrm{mA}$ in the $1\,\mathrm{k\Omega}$ resistor and $3\,\mathrm{mA}$ in the $3\,\mathrm{k\Omega}$ resistor.

Branch currents split in inverse proportion to resistance, so the ratio is $3:1$. Of the $12\,\mathrm{mA}$, three quarters ($9\,\mathrm{mA}$) take the smaller resistor.

Check: Both branches have $9\,\mathrm{V}$ across them: $9\,\mathrm{mA} \times 1\,\mathrm{k\Omega} = 9\,\mathrm{V}$ and $3\,\mathrm{mA} \times 3\,\mathrm{k\Omega} = 9\,\mathrm{V}$. They match, as parallel branches must.', null, '{}'::text[], null, 'current divider parallel 12 mA 1k 3k branch currents', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 2', 'OpenStax University Physics Vol. 2 §10.2']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-cell-vs-battery', 'embedded-ai', 'embedded-ai/electricity-basics', 135, 'definition', 2, false, 'What is the difference between a **cell** and a **battery**?', 'A cell is a single unit that turns stored chemical energy into electrical energy; a battery is strictly a group of cells connected together.

Everyday speech calls a single AA cell a "battery". A 9 V battery is really several small cells in series inside one case.

Key idea: A cell''s voltage is set by its chemistry. Wiring cells together raises the total voltage or the total charge they can deliver, as later cards show.', null, '{}'::text[], null, 'cell versus battery difference group of cells', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 3']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-capacity-mah', 'embedded-ai', 'embedded-ai/electricity-basics', 136, 'definition', 2, false, 'What is a battery''s **capacity** in mAh?', 'The amount of charge the battery can deliver, in milliamp-hours; $1000\,\mathrm{mAh} = 1\,\mathrm{Ah} = 3600\,\mathrm{C}$.

A $1000\,\mathrm{mAh}$ cell can ideally supply $1000\,\mathrm{mA}$ for one hour, or $100\,\mathrm{mA}$ for ten hours.

Why: Charge is current times time, $Q = I \cdot t$, and one amp for one hour is $3600\,\mathrm{C}$.

Watch out: Real capacity depends on the load current, the temperature, the cell''s age and how low a voltage your device can still run on. The label is measured under the maker''s gentle test conditions, so real devices often get less.', null, '{}'::text[], null, 'battery capacity mAh milliamp hour charge definition', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 3']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-wh-from-mah', 'embedded-ai', 'embedded-ai/electricity-basics', 137, 'formula', 2, false, 'How do you convert a battery''s capacity in mAh to stored energy in Wh?', '$E\,(\mathrm{Wh}) = \dfrac{\mathrm{mAh} \times V}{1000}$, using the cell''s nominal voltage $V$, the typical voltage printed on its label.

Why: Energy is charge times voltage. One amp-hour at $V$ volts is $3600 \cdot V$ joules, and that equals $V$ watt-hours. Using the nominal voltage makes the result an estimate, because the real voltage drifts as the cell drains.

Example: A $2000\,\mathrm{mAh}$ cell at $3.7\,\mathrm{V}$ stores $2000 \times 3.7 / 1000 = 7.4\,\mathrm{Wh}$.

Tip: Compare batteries of different voltages in Wh, not mAh. Two batteries with the same mAh but different voltages hold different energy.', null, '{}'::text[], null, 'convert mAh to Wh formula battery energy voltage', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 3']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-nominal-voltage-discharge-curve', 'embedded-ai', 'embedded-ai/electricity-basics', 138, 'misconception', 2, false, 'Why is it false that a battery stays at its labeled voltage until it is empty?', 'False: the label is the **nominal voltage**, a typical value, and the real voltage slides down along the **discharge curve** as the cell drains.

The discharge curve is a graph of cell voltage against how much charge has been drawn.

Example: A fresh alkaline AA cell (the common disposable kind) measures about $1.5$ to $1.6\,\mathrm{V}$ and falls gradually to about $1\,\mathrm{V}$ or below as it empties.

Tip: A device has to work over the whole range of voltages, not just the label value.', null, '{}'::text[], null, 'nominal voltage discharge curve battery voltage drops', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 3']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-numbers-cr2032', 'embedded-ai', 'embedded-ai/electricity-basics', 139, 'numbers', 2, false, 'What are the nominal voltage and typical capacity of a CR2032 **coin cell**?', '$3\,\mathrm{V}$ nominal and about $225\,\mathrm{mAh}$, rated at a light load of about $0.2\,\mathrm{mA}$ down to $2.0\,\mathrm{V}$ at room temperature.

A **coin cell** is a small, flat, round cell. The CR2032 is the common non-rechargeable lithium one, and its name encodes its size: $20\,\mathrm{mm}$ across and $3.2\,\mathrm{mm}$ thick. Its energy is about $225 \times 3/1000 \approx 0.68\,\mathrm{Wh}$.

Watch out: Coin cells are meant for tiny currents. At tens of milliamps the voltage sags a lot and the cell delivers far less than its rated capacity. Makers'' ratings vary a little by brand (roughly $210$ to $240\,\mathrm{mAh}$).', null, '{}'::text[], null, 'CR2032 coin cell 3 V 225 mAh capacity', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 3', 'https://energy.panasonic.com/dam/master/pdf/en/datasheet/lithium/CR2032_Datasheet_EN.pdf']::text[], '{}'::text[], '2026-11-26'::date, false),
  ('embedded-ai/electricity-numbers-li-ion', 'embedded-ai', 'embedded-ai/electricity-basics', 140, 'numbers', 2, false, 'What is the nominal voltage of a typical **lithium-ion (Li-ion)** cell, and what are its full and empty voltages?', '$3.6$ to $3.7\,\mathrm{V}$ nominal; about $4.2\,\mathrm{V}$ when full and roughly $3.0\,\mathrm{V}$ when considered empty.

A Li-ion cell is a rechargeable cell that stores energy by moving lithium ions (electrically charged lithium atoms) between its two electrodes, the conducting plates inside it. Unlike an alkaline AA, it can be recharged hundreds of times. These figures are for the most common cobalt- and nickel-based types.

Watch out: Not every lithium-ion chemistry matches them. Lithium iron phosphate (LiFePO4) cells, also lithium-ion, are about $3.2\,\mathrm{V}$ nominal and $3.65\,\mathrm{V}$ full. Li-ion cells also need protection from overcharge and from being drained too far.', null, '{}'::text[], null, 'lithium ion cell nominal voltage 3.7 V 4.2 V full', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 3', 'https://batteryuniversity.com/article/bu-216-summary-table-of-lithium-based-batteries']::text[], '{}'::text[], '2026-11-26'::date, false),
  ('embedded-ai/electricity-internal-resistance-sag', 'embedded-ai', 'embedded-ai/electricity-basics', 141, 'concept', 2, false, 'What is a cell''s **internal resistance**, and why does its voltage sag under heavy load?', 'Internal resistance is the small resistance inside the cell itself; the load current flows through it and drops some of the voltage, so the terminal voltage sags.

Think of the cell as a perfect voltage source, one that always gives the same voltage, with a small resistor in series. The drop across that resistor is $I \times R_{\mathrm{internal}}$.

Example: Suppose a cell is $1.5\,\mathrm{V}$ with no load and has $0.5\,\Omega$ internal resistance. Drawing $1\,\mathrm{A}$ drops $0.5\,\mathrm{V}$ inside it, so the output is $1.0\,\mathrm{V}$.

Watch out: Internal resistance rises as a cell drains, and it is much larger in coin cells than in AA cells: about $0.2\,\Omega$ for a fresh alkaline AA, but roughly $10$ to $20\,\Omega$ for a fresh CR2032. Heavy loads can make a nearly full coin cell look empty.', null, '{}'::text[], null, 'battery internal resistance voltage sag under load', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 3']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-cells-series-parallel', 'embedded-ai', 'embedded-ai/electricity-basics', 142, 'concept', 2, false, 'What happens to voltage and capacity when identical cells are wired in series, and when they are wired in parallel?', 'Series adds the voltages and keeps the capacity of one cell; parallel keeps the voltage and adds the capacities.

Example: Four $1.5\,\mathrm{V}$ AA cells in series give $6\,\mathrm{V}$ with the capacity of one cell. Two $3.7\,\mathrm{V}$ Li-ion cells in parallel give $3.7\,\mathrm{V}$ with double the mAh.

Watch out: Only connect cells that match in type and charge level. Mismatched cells can push current into each other or be overdrained.', null, '{}'::text[], null, 'battery cells in series parallel voltage capacity', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 3']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-problem-runtime', 'embedded-ai', 'embedded-ai/electricity-basics', 143, 'problem', 2, true, 'A device averages $120\,\mathrm{mA}$ from a $2400\,\mathrm{mAh}$ battery, and you only count on $80\%$ of the rated capacity. How many hours will it run? (Give the number only.)', '$16\,\mathrm{h}$

Usable capacity is $0.8 \times 2400 = 1920\,\mathrm{mAh}$. Runtime is capacity divided by current: $1920/120 = 16\,\mathrm{h}$.

Why: The ideal runtime without a margin is $2400/120 = 20\,\mathrm{h}$. Real batteries deliver less than their label under load, age and cold.

Tip: Always apply a margin to a runtime estimate. Counting on $70\%$ to $80\%$ of the rated capacity is a common planning choice.', '16', array['16 h', '16 hours']::text[], '$16\,\mathrm{h}$', 'battery runtime capacity divided by current margin', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 3']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-problem-c-rate', 'embedded-ai', 'embedded-ai/electricity-basics', 144, 'problem', 2, false, 'A battery''s **C-rate** is its discharge current divided by its capacity (in matching units), so $1\mathrm{C}$ means the current in amps equals the capacity in Ah. What C-rate is a $500\,\mathrm{mA}$ draw from a $2000\,\mathrm{mAh}$ cell?', '$0.25\mathrm{C}$

$500\,\mathrm{mA} / 2000\,\mathrm{mAh} = 0.25$ per hour, which is written $0.25\mathrm{C}$. This C has nothing to do with coulombs. At that rate an ideal cell would last $1/0.25 = 4\,\mathrm{h}$.

Why: C-rate lets you compare loads across batteries of different sizes. Ideally, $1\mathrm{C}$ drains the cell in one hour and $2\mathrm{C}$ in half an hour.

Watch out: Higher C-rates make internal resistance matter more, so the voltage sags more and less capacity is delivered.', null, '{}'::text[], null, 'battery C-rate discharge current capacity 0.25C', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 3']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-schematic-symbols', 'embedded-ai', 'embedded-ai/electricity-basics', 145, 'definition', 2, false, 'What is a **schematic**, and what are **circuit symbols**?', 'A schematic is a drawing that shows how parts connect; circuit symbols are the standard little shapes that stand for each part.

Lines are wires. A dot where lines meet means they are joined; lines that cross without a dot are not. Common symbols: a cell is a long and a short parallel line (the long one is +), and a battery is drawn the same way or as several such pairs; a resistor is a zigzag or a small rectangle; a switch is a gap with a lever; an LED is a triangle pointing at a bar with two small arrows leaving it; and ground is a stack of shortening horizontal lines.

Key idea: A schematic shows connections, not where the parts physically sit.', null, '{}'::text[], null, 'schematic circuit symbols battery resistor LED switch ground', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 7']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-breadboard-power-rail', 'embedded-ai', 'embedded-ai/electricity-basics', 146, 'definition', 2, false, 'What is a **breadboard**, and what is a **power rail**?', 'A breadboard is a reusable board of spring-clip holes for building circuits without soldering (joining parts with melted metal); a power rail is a long strip of linked holes along its edge for supply and ground.

You push part legs and wires into the holes. Metal strips under the board link certain holes together.

Tip: By convention the red rail is for the positive supply and the blue (or black) rail is for ground.', null, '{}'::text[], null, 'breadboard definition power rail solderless prototyping', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 7']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-multimeter', 'embedded-ai', 'embedded-ai/electricity-basics', 147, 'definition', 2, false, 'What is a **multimeter**?', 'An instrument, often handheld, that measures voltage, current and resistance, and usually has a continuity setting that beeps when two points are connected.

A dial selects what to measure, and two **probes** (insulated test leads with metal tips) plug into labeled sockets. The black probe usually goes in the COM socket and the red probe in the socket for what you measure.

Watch out: Set the dial and the sockets for the right quantity before you touch the probes to a circuit. A wrong setting gives nonsense readings and can damage the meter.', null, '{}'::text[], null, 'multimeter definition measures voltage current resistance', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 7']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-read-schematic-example', 'embedded-ai', 'embedded-ai/electricity-basics', 148, 'example', 2, false, 'A schematic shows: battery + → switch → resistor → LED → battery −. Describe the circuit and what happens when the switch opens.', 'It is a series circuit: one loop with the battery, switch, resistor and LED in a chain; opening the switch (turning it off) breaks the loop, so the current stops and the LED goes out.

Follow the line from the battery''s + side, through the switch and resistor, through the LED, and back to the − side. That is the path of conventional current.

Why: The resistor limits the current so the LED is not overloaded. The switch opens or closes the loop: an open switch is off and a closed one is on, the reverse of a water tap.

Tip: To read a schematic, trace one wire at a time from + to − and name each part you pass.', null, '{}'::text[], null, 'reading schematic battery switch resistor LED loop', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 7']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-breadboard-connected-holes', 'embedded-ai', 'embedded-ai/electricity-basics', 149, 'concept', 2, false, 'On a typical breadboard, which holes are connected to each other?', 'The five holes of each short row on one side of the center gap are connected, and each power rail is connected along its length.

The center gap splits the board into two halves with no link between them. This is why a chip (a small package of circuitry with two rows of metal legs, called pins) can straddle the gap without its pins on opposite sides being joined.

Watch out: On some full-size boards each power rail is split in the middle. Check the board''s layout, or bridge the break with a jumper wire (a short wire for linking holes).', null, '{}'::text[], null, 'breadboard which holes connected row strip centre gap rails', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 7']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-voltmeter-ammeter', 'embedded-ai', 'embedded-ai/electricity-basics', 150, 'concept', 2, false, 'How do you connect a **voltmeter** and an **ammeter** to measure a part''s voltage and current?', 'Connect a voltmeter across the part (in parallel); connect an ammeter in the path of the current (in series), by breaking the loop and putting the meter in the gap.

A voltmeter is any meter that measures voltage, such as a multimeter on its voltage setting. It has very high resistance, so it takes almost no current from the circuit. An ammeter is any meter that measures current, such as a multimeter on a current setting. It has very low resistance, so it hardly changes the current it measures.

Mnemonic: Voltage is measured across; current is measured through.', null, '{}'::text[], null, 'voltmeter in parallel ammeter in series how to connect', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 7', 'OpenStax University Physics Vol. 2 §10.4']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-continuity-test-example', 'embedded-ai', 'embedded-ai/electricity-basics', 151, 'example', 2, false, 'How can you use a multimeter''s **continuity test** to check whether a jumper wire is unbroken?', 'Switch to continuity mode and touch one probe to each end of the wire; a beep means there is a low-resistance path, so the wire is intact.

A continuity test checks whether two points are connected by a low-resistance path. The meter beeps when the resistance is below a threshold, typically some tens of ohms (it varies by meter).

Tip: No beep on a wire you expected to conduct means a break inside it or a poor contact. The same test finds which breadboard holes are joined.

Watch out: Do the test with the circuit powered off.', null, '{}'::text[], null, 'continuity test multimeter beep check wire unbroken', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 7']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-ammeter-across-supply', 'embedded-ai', 'embedded-ai/electricity-basics', 152, 'misconception', 2, false, 'Why is it false that you can safely connect a multimeter in current mode straight across a battery to see how much current it gives?', 'False: in current mode the meter has almost no resistance, so across a supply it forms a short circuit, and the huge current usually blows the meter''s fuse.

A **fuse** is a thin metal link that melts, breaking the circuit, when too much current flows. By Ohm''s law $I = V/R$, so a tiny $R$ means a huge current, and the fuse inside the meter gives way before the meter is damaged.

Example: On its milliamp socket, a meter placed straight across a $9\,\mathrm{V}$ battery asks for far more current than its fuse allows, and the fuse opens.

Watch out: Many cheap meters have no fuse at all on their $10\,\mathrm{A}$ socket, so a short through it can damage the meter or overheat the battery. Leaving the red probe in a current socket and then measuring a voltage causes the same short.

To measure current, put the meter in series with a load, so the load limits the current.', null, '{}'::text[], null, 'ammeter across battery blows fuse short circuit multimeter', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 7', 'OpenStax University Physics Vol. 2 §10.4']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-rails-not-powered', 'embedded-ai', 'embedded-ai/electricity-basics', 153, 'misconception', 2, false, 'Why is it false that a breadboard''s red and blue rails are powered automatically?', 'False: the rails are just linked strips of metal, and they carry voltage only after you wire a supply to them.

The red and blue colors are a convention that tells you which rail to connect to + and which to ground. Nothing inside the board supplies any voltage.

Watch out: The rail pairs along the two long edges are not connected to each other. Wire the supply to every rail you use.', null, '{}'::text[], null, 'breadboard rails not powered automatically red blue', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 7']::text[], '{}'::text[], null, false),
  ('embedded-ai/electricity-resistance-power-off', 'embedded-ai', 'embedded-ai/electricity-basics', 154, 'misconception', 2, false, 'Why is it false that you can measure a resistor''s value with a multimeter while the circuit is powered and the resistor is still wired in?', 'False: the meter measures resistance by sending its own small current, so other power sources spoil the reading and other parts in parallel change it.

Turn the power off first. If the resistor is still connected to other parts, you read the equivalent resistance of everything in parallel with it.

Example: A $10\,\mathrm{k\Omega}$ resistor in parallel with a $10\,\mathrm{k\Omega}$ path measures about $5\,\mathrm{k\Omega}$.

Tip: Lift one leg of the part out of the circuit to measure it alone.', null, '{}'::text[], null, 'measure resistance power off multimeter in circuit wrong reading', array['Scherz & Monk, Practical Electronics for Inventors 4e, ch. 7']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-interpreter', 'embedded-ai', 'embedded-ai/python-1', 155, 'definition', 1, false, 'What is the Python **interpreter**, and how do you run a Python script with it?', 'The interpreter is the program that reads your Python code and carries it out, and you run a script with `python script.py` in the terminal.

A **script** is a plain text file of Python instructions, usually named with `.py` at the end. The interpreter reads it from the top and does each instruction in order.

Example: If `hello.py` holds the single line `print("hello")`, then typing `python hello.py` shows `hello` on the screen. On some computers the command is `python3`.

Tip: Typing just `python` opens an interactive prompt (`>>>`) where every line you type is run at once. It is a handy scratchpad for trying small ideas.

Watch out: Saving a script does not run it. After every edit you must call the interpreter on the file again to see the change.', null, '{}'::text[], null, 'python interpreter run script python hello.py', array['CS50P, Lecture 0 (Functions, Variables)', 'The Python Tutorial, ch. 3 (An Informal Introduction to Python)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-variable-assignment', 'embedded-ai', 'embedded-ai/python-1', 156, 'definition', 1, false, 'What is a **variable** in Python, and what does the **assignment** `score = 10` do?', 'A variable is a name that refers to a value, and an assignment (`=`) makes the name on the left refer to the value on the right.

Python works out the right-hand side first, then attaches the name to the result. That is why `score = score + 1` makes sense: it takes the current value of `score`, adds 1, and points the name at the new value.

Example: After `score = 10` and then `score = score + 1`, the name `score` refers to `11`.

Tip: Names can use letters, digits and underscores, cannot start with a digit, and are case-sensitive, so `Score` and `score` are different names. Choose names that say what the value means, such as `battery_volts`.

Watch out: In Python, `=` is an instruction ("make this name refer to that value"), not a statement that two things are equal.', null, '{}'::text[], null, 'python variable assignment name refers to value', array['CS50P, Lecture 0 (Functions, Variables)', 'The Python Tutorial, ch. 3 (An Informal Introduction to Python)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-basic-types', 'embedded-ai', 'embedded-ai/python-1', 157, 'concept', 1, false, 'What are Python''s four basic value types, and how do you check which one a value has?', '`int` (whole numbers), `float` (numbers with a decimal point), `str` (text) and `bool` (`True` or `False`); the function `type(value)` reports which one a value has.

Every value has a **type** that decides what you can do with it. `7` is an **int**. `7.0` is a **float**, even though it stands for the same amount. `"7"` is a **str** (short for string, a piece of text): the quotes make it text, not a number. `True` and `False` are **bool** values, named after the mathematician George Boole, and must start with a capital letter.

Example: `7 + 1` is `8`, but `"7" + "1"` is `"71"`, because adding two pieces of text joins them.

Watch out: Quotes change the type. `"7"` looks like a number on the screen but behaves like text.', null, '{}'::text[], null, 'python int float str bool basic types type()', array['CS50P, Lecture 0 (Functions, Variables)', 'The Python Tutorial, ch. 3 (An Informal Introduction to Python)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-type-conversion', 'embedded-ai', 'embedded-ai/python-1', 158, 'definition', 1, false, 'What is **type conversion** in Python, and which functions convert to `int`, `float` and `str`?', 'Type conversion builds a value of one type from a value of another type, using `int()`, `float()` and `str()`.

The conversion functions return a new value. They do not change the variable you passed in.

Example:
- `int("42")` gives the whole number `42`.
- `float(3)` gives `3.0`.
- `str(3.5)` gives the text `"3.5"`.
- `int(3.9)` gives `3`: converting a float to an int cuts off the decimal part and does not round.

Watch out: `int(-3.9)` is `-3`, because cutting off moves toward zero. If you need rounding, use `round()` instead.', null, '{}'::text[], null, 'python type conversion int float str functions', array['CS50P, Lecture 0 (Functions, Variables)', 'The Python Tutorial, ch. 3 (An Informal Introduction to Python)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-int-string-decimal', 'embedded-ai', 'embedded-ai/python-1', 159, 'misconception', 1, false, 'Why is it false that `int("3.5")` gives `3` because `int()` can convert any text that looks like a number?', '`int()` on text accepts only whole-number text, so `int("3.5")` raises an error (a `ValueError`); convert in two steps with `int(float("3.5"))`, which gives `3`.

Python reads the text strictly: `"3.5"` contains a decimal point, so it is not a whole number, and Python refuses to guess. A `ValueError` means "this is the right kind of value, but its content is not acceptable here".

Example: `float("3.5")` turns the text into the float `3.5`, and `int(3.5)` then cuts it off to `3`. So `int(float("3.5"))` is `3`.

Watch out: The rule is about text only. `int(3.5)` (a float, not text) works fine and gives `3`.', null, '{}'::text[], null, 'python int(''3.5'') ValueError convert string float', array['CS50P, Lecture 0 (Functions, Variables)', 'The Python Tutorial, ch. 3 (An Informal Introduction to Python)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-type-output', 'embedded-ai', 'embedded-ai/python-1', 160, 'code', 1, false, 'What does this print?

```python
print(type(7), type(7.0), type("7"), type(True))
```', '`<class ''int''> <class ''float''> <class ''str''> <class ''bool''>`

`print` shows its values on one line with a space between them. `type(...)` reports each value''s type, and Python writes a type as `<class ''int''>`, `<class ''float''>` and so on.

Key idea: The type depends on how the value is written, not on its amount. `7` and `7.0` are equal in size but different types, and `"7"` in quotes is text.

Tip: When a program misbehaves, add `print(type(x))` to see what you really have. This is the fastest way to catch a number that is secretly text.', null, '{}'::text[], null, 'python type() print int float str bool class', array['CS50P, Lecture 0 (Functions, Variables)', 'The Python Tutorial, ch. 3 (An Informal Introduction to Python)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-input-string', 'embedded-ai', 'embedded-ai/python-1', 161, 'code', 1, false, 'A user runs this script, types `4` and presses Enter. What does the last line print?

```python
n = input("Number? ")
print(n + n)
```', '`44`

`input()` shows its prompt, waits for the user to type a line, and always returns that line as a **str**, even when the user typed digits. So `n` is the text `"4"`, and `+` between two pieces of text joins them: `"4" + "4"` is `"44"`.

Why it matters: Any program that does arithmetic on typed input must convert first.

Example: With `n = int(input("Number? "))`, typing `4` makes `n + n` equal `8`.

Watch out: A typed answer such as `4` and the number `4` look the same on screen but are different types.', '44', '{}'::text[], null, 'python input() returns string n + n 44', array['CS50P, Lecture 0 (Functions, Variables)', 'The Python Tutorial, ch. 3 (An Informal Introduction to Python)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-conversion', 'embedded-ai', 'embedded-ai/python-1', 162, 'code', 1, false, 'What does this print?

```python
age = "12"
print(int(age) + 3)
print(age + "3")
```', '`15` on the first line and `123` on the second.

`int(age)` builds a new whole number, `12`, so adding `3` gives `15`. The variable `age` itself is never changed: it still refers to the text `"12"`. So `age + "3"` joins two pieces of text and gives `"123"`.

Watch out: Converting inside an expression does not convert the variable. To keep the number, assign it: `age = int(age)`.

Tip: When you see `+` between two names, ask whether they are both numbers or both text. Mixing them, as in `"12" + 3`, is an error.', null, '{}'::text[], null, 'python int() convert string to number print age', array['CS50P, Lecture 0 (Functions, Variables)', 'The Python Tutorial, ch. 3 (An Informal Introduction to Python)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-fstring', 'embedded-ai', 'embedded-ai/python-1', 163, 'code', 1, false, 'A string with an `f` right before its opening quote is an **f-string**: Python replaces each `{...}` with the value of the expression inside. What does this print?

```python
price = 4
print(f"{price * 3} items at {price:.2f} each")
```', '`12 items at 4.00 each`

Inside the braces Python works out `price * 3`, which is `12`, and puts it in the text. The part after the colon, `:.2f`, is a format instruction: show the number as a float with exactly 2 digits after the decimal point, so `4` becomes `4.00`.

Why it matters: F-strings are the easiest way to build readable output from several values without converting each one to text.

Watch out: Without the leading `f`, Python prints the braces literally, as `{price * 3} items ...`.', null, '{}'::text[], null, 'python f-string format .2f print expression', array['CS50P, Lecture 0 (Functions, Variables)', 'The Python Tutorial, ch. 3 (An Informal Introduction to Python)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-operators', 'embedded-ai', 'embedded-ai/python-1', 164, 'definition', 1, false, 'What is an **operator**, and what do `+`, `-`, `*`, `/` and `**` do?', 'An operator is a symbol that combines values (its operands) into a new value: `+`, `-` and `*` add, subtract and multiply, `/` divides and always gives a float, and `**` is **exponentiation**, raising to a power.

Example:
- `2 ** 5` is `32`, which is 2 multiplied by itself 5 times.
- `7 / 2` is `3.5`.
- `6 / 3` is `2.0`, a float, not `2`.

Watch out: The symbol `^` is not "to the power of" in Python. It does something unrelated, so `2 ^ 5` does not give `32`. Always use `**`.', null, '{}'::text[], null, 'python arithmetic operators exponentiation division returns float', array['CS50x 2026, Week 6 notes: Truncation and Floating Point Imprecision', 'The Python Tutorial, ch. 15 (Floating-Point Arithmetic: Issues and Limitations)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-floor-modulo', 'embedded-ai', 'embedded-ai/python-1', 165, 'definition', 1, false, 'What do the **floor division** operator `//` and the **modulo** operator `%` compute?', '`a // b` divides and rounds down to a whole number (the quotient), and `a % b` gives what is left over (the remainder).

Example: `17 // 5` is `3` because 5 fits into 17 three times, and `17 % 5` is `2` because 17 - 3 × 5 = 2.

Key idea: The two always fit together as `a == (a // b) * b + a % b`. Here that is 17 = 3 × 5 + 2.

Watch out: "Rounds down" means toward minus infinity, not toward zero. `-7 // 2` is `-4`, and `-7 % 2` is `1`, so the identity above still holds.', null, '{}'::text[], null, 'python floor division // modulo % quotient remainder', array['CS50x 2026, Week 6 notes: Truncation and Floating Point Imprecision', 'The Python Tutorial, ch. 15 (Floating-Point Arithmetic: Issues and Limitations)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-int-float-limits', 'embedded-ai', 'embedded-ai/python-1', 166, 'concept', 1, false, 'How do Python''s `int` and `float` differ when numbers get very large or need many digits?', 'A Python `int` is exact and never overflows because it grows as needed, while a `float` is stored in 64 bits and keeps only about 16 significant decimal digits.

In C, a 32-bit integer wraps around once it passes about 2.1 billion (the overflow you met earlier). A Python `int` has no such limit: `2 ** 100` prints `1267650600228229401496703205376`, every digit correct, and the only limit is the computer''s memory.

A `float` is fixed in size. `float(2 ** 100)` shows `1.2676506002282294e+30`: the size is right, but only the first 16 or so digits are meaningful. The largest float is about $1.8 \times 10^{308}$.

Key idea: Use ints when you need exact counts, and expect small errors when you use floats.', null, '{}'::text[], null, 'python int never overflow float precision 64-bit', array['CS50x 2026, Week 6 notes: Truncation and Floating Point Imprecision', 'The Python Tutorial, ch. 15 (Floating-Point Arithmetic: Issues and Limitations)']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/py1-float-equality', 'embedded-ai', 'embedded-ai/python-1', 167, 'misconception', 1, false, 'Why is it false that `0.1 + 0.2 == 0.3` evaluates to `True` in Python?', '`0.1 + 0.2` is actually `0.30000000000000004`, because floats store binary approximations (a **floating-point rounding error**), so the comparison is `False`.

A computer stores a float in binary. Just as 1/3 cannot be written exactly with a finite number of decimal digits, 0.1 cannot be written exactly with a finite number of binary digits. The stored value is a tiny bit off, and the tiny errors show up after arithmetic.

Example: `print(0.1 + 0.2)` shows `0.30000000000000004`.

Watch out: This is not a Python bug. C, JavaScript and the processor hardware itself behave the same way. The fix is to never test floats with `==`, but to ask whether they are close, as the code card on `math.isclose` shows.', null, '{}'::text[], null, 'python 0.1 + 0.2 == 0.3 False floating point rounding', array['CS50x 2026, Week 6 notes: Truncation and Floating Point Imprecision', 'The Python Tutorial, ch. 15 (Floating-Point Arithmetic: Issues and Limitations)']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/py1-code-precedence', 'embedded-ai', 'embedded-ai/python-1', 168, 'code', 1, false, '**Operator precedence** is the order in which Python applies operators when brackets do not say otherwise: `**` first, then `*`, `/`, `//`, `%`, and last `+` and `-`. What does this print on one line?

```python
print(2 + 3 * 4 ** 2, (2 + 3) * 4)
```', '`50 20`

For the first value, `4 ** 2` is `16`, then `3 * 16` is `48`, then `2 + 48` is `50`. For the second, the brackets force `2 + 3` first, so it is `5 * 4`, which is `20`.

Tip: When in doubt, add brackets. They cost nothing and make your intent clear to the next reader.

Watch out: `-2 ** 2` is `-4`, not `4`, because `**` binds tighter than the minus sign, so it means `-(2 ** 2)`.', '50 20', '{}'::text[], null, 'python operator precedence exponent before multiplication', array['CS50x 2026, Week 6 notes: Truncation and Floating Point Imprecision', 'The Python Tutorial, ch. 15 (Floating-Point Arithmetic: Issues and Limitations)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-digits', 'embedded-ai', 'embedded-ai/python-1', 169, 'code', 1, false, 'What does this print?

```python
n = 4827
print(n // 100 % 10, n % 10)
```', '`8 7`

`//` and `%` have the same precedence and run left to right, so `n // 100 % 10` is `(n // 100) % 10`. First `4827 // 100` is `48`, which drops the last two digits. Then `48 % 10` is `8`, the last digit of 48. Finally `4827 % 10` is `7`.

Key idea: Dividing by 10 with `//` removes the last digit, and `% 10` reads it.

Example: To get the tens digit of any whole number `n`, write `n // 10 % 10`.', null, '{}'::text[], null, 'python extract digits floor division modulo 10', array['CS50x 2026, Week 6 notes: Truncation and Floating Point Imprecision', 'The Python Tutorial, ch. 15 (Floating-Point Arithmetic: Issues and Limitations)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-wrap', 'embedded-ai', 'embedded-ai/python-1', 170, 'code', 1, false, 'A 24-hour clock shows hour `22`. What does this print?

```python
hour = 22
print((hour + 5) % 24)
```', '`3`

`22 + 5` is `27`, and `27 % 24` is `3`. The remainder after dividing by 24 can never reach 24, so the counter wraps from 23 back to 0.

Why it matters: This is the standard way to make a counter go around, such as hours, array positions in a circular buffer, or days of the week. It is the same wrap-around you saw with fixed-size integers, but you choose the size.

Tip: To wrap around a counter of size `n`, use `% n`; the result is always between 0 and `n - 1`.', '3', '{}'::text[], null, 'python modulo wrap around counter clock % 24', array['CS50x 2026, Week 6 notes: Truncation and Floating Point Imprecision', 'The Python Tutorial, ch. 15 (Floating-Point Arithmetic: Issues and Limitations)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-isclose', 'embedded-ai', 'embedded-ai/python-1', 171, 'code', 1, false, '`import math` makes Python''s toolbox of math functions available (a later unit explains `import`). What does this print?

```python
import math
a = 0.1 + 0.2
print(a == 0.3, math.isclose(a, 0.3))
```', '`False True`

`a == 0.3` is `False` because `a` is `0.30000000000000004`. `math.isclose(a, 0.3)` asks whether the two numbers are within a tiny relative distance of each other (by default one part in a billion), and they are.

Tip: Use `math.isclose` whenever you compare floats that came from calculations.

Watch out: By default the tolerance is relative, so comparing to exactly `0` never counts as close: `math.isclose(1e-12, 0)` is `False`. For values near zero, add an absolute tolerance, as in `math.isclose(1e-12, 0, abs_tol=1e-9)`, which is `True`.', null, '{}'::text[], null, 'python math.isclose compare floats tolerance', array['CS50x 2026, Week 6 notes: Truncation and Floating Point Imprecision', 'The Python Tutorial, ch. 15 (Floating-Point Arithmetic: Issues and Limitations)']::text[], array['number-formats']::text[], null, false),
  ('embedded-ai/py1-boolean-comparison', 'embedded-ai', 'embedded-ai/python-1', 172, 'definition', 1, false, 'What is a **Boolean expression**, and what do the **comparison operators** `==`, `!=`, `<`, `>`, `<=` and `>=` do?', 'A Boolean expression is one whose value is `True` or `False`, and a comparison operator compares two values to make one: `==` equal, `!=` not equal, `<` less, `>` greater, `<=` less or equal, `>=` greater or equal.

Example: `5 >= 5` is `True`, `5 != 5` is `False`, and `"a" == "A"` is `False` because upper and lower case are different characters.

Watch out: `=` assigns and `==` compares. Writing `if x = 5:` is a mistake, and Python refuses to run it. You want `if x == 5:`.', null, '{}'::text[], null, 'python boolean expression comparison operators == != < >', array['CS50P, Lecture 1 (Conditionals)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-if-elif-else', 'embedded-ai', 'embedded-ai/python-1', 173, 'definition', 1, false, 'How does an **if/elif/else** chain decide which block of code to run?', 'Python tests the conditions from top to bottom, runs only the block of the first one that is `True`, and runs the `else` block only if none of them was.

```python
if temp > 30:
    print("hot")
elif temp > 15:
    print("mild")
else:
    print("cold")
```

Each condition ends with a colon, and the indented lines below it are its block. With `temp = 20` this prints `mild`.

Watch out: Once one branch has run, all the later `elif` and `else` branches are skipped, even if their conditions would also be true. So the order of the conditions matters.', null, '{}'::text[], null, 'python if elif else chain first true branch runs', array['CS50P, Lecture 1 (Conditionals)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-and-or-not', 'embedded-ai', 'embedded-ai/python-1', 174, 'concept', 1, false, 'How do `and`, `or` and `not` combine conditions, and what is **short-circuit evaluation**?', '`and` is `True` only when both sides are, `or` is `True` when at least one side is, and `not` flips a bool; Python stops as soon as the answer is settled, which is called short-circuit evaluation.

With `A and B`, if `A` is `False` the whole thing must be `False`, so `B` is never looked at. With `A or B`, if `A` is `True` the answer is already `True`, so `B` is skipped.

Example: `True or print("hi")` prints nothing, because the `print` on the right never runs.

Tip: `not` is applied first, then `and`, then `or`. Add brackets when you mix them, such as `(a or b) and c`.', null, '{}'::text[], null, 'python and or not short-circuit evaluation precedence', array['CS50P, Lecture 1 (Conditionals)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-truthiness', 'embedded-ai', 'embedded-ai/python-1', 175, 'concept', 1, false, 'Which values count as **falsy** and which as **truthy** when used as an `if` condition?', '`False`, `0`, `0.0`, the empty string `""` and the empty list `[]` are falsy; almost every other value is truthy.

**Truthiness** is how a non-bool value behaves in a condition. A falsy value acts like `False`, a truthy one like `True`. A list is an ordered collection written with square brackets, such as `[1, 2]`, and a later unit covers it in full.

Example: `if items:` is a short way to ask "is the list non-empty?". It is `False` for `[]` and `True` for `[5]`.

Watch out: Non-empty text is always truthy, even `"0"` and `"False"`. `bool("0")` is `True`, because the string has a character in it.', null, '{}'::text[], null, 'python truthiness falsy truthy empty string list zero', array['CS50P, Lecture 1 (Conditionals)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-elif-order', 'embedded-ai', 'embedded-ai/python-1', 176, 'code', 1, false, 'What does this print?

```python
score = 95
if score >= 70:
    print("C")
elif score >= 90:
    print("A")
else:
    print("F")
```', '`C`

`95 >= 70` is `True`, so the first block runs and prints `C`. The `elif` is never tested, even though `95 >= 90` is also true.

Key idea: In an if/elif chain, the first true condition wins, so test the most specific condition first.

Example: Putting the tests in the order `>= 90`, then `>= 70` prints `A` for a score of 95, which is what was meant.', null, '{}'::text[], null, 'python if elif order first true condition wins grade', array['CS50P, Lecture 1 (Conditionals)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-compare', 'embedded-ai', 'embedded-ai/python-1', 177, 'code', 1, false, 'What does this print on one line?

```python
print(3 == 3.0, "a" < "b", "Z" < "a", "10" < "9")
```', '`True True True True`

`3 == 3.0` is `True`, since an int and a float with the same value compare equal. Text is compared character by character using each character''s code point: `"a"` comes before `"b"`, and `"Z"` (code 90) comes before `"a"` (code 97), so capital letters sort before lowercase ones. For `"10" < "9"`, only the first characters count, `"1"` (49) against `"9"` (57), so it is `True`.

Watch out: Comparing text that holds digits compares characters, not numbers. To compare as numbers, convert first: `int("10") < int("9")` is `False`.', null, '{}'::text[], null, 'python compare strings numbers == < code point order', array['CS50P, Lecture 1 (Conditionals)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-short-circuit', 'embedded-ai', 'embedded-ai/python-1', 178, 'code', 1, false, 'What does this print?

```python
x = 0
if x != 0 and 10 / x > 2:
    print("big")
else:
    print("safe")
```', '`safe`

`x != 0` is `False`, so `and` short-circuits: the right side `10 / x > 2` is never evaluated. If it were, dividing by zero would stop the program with an error.

Why it matters: Putting a safety check on the left of `and` protects the right side. This pattern guards against dividing by zero, or using a value that is not there.

Watch out: Reverse the order, `10 / x > 2 and x != 0`, and the division runs first and crashes. The order of the two conditions matters.', null, '{}'::text[], null, 'python short-circuit and guard divide by zero condition', array['CS50P, Lecture 1 (Conditionals)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-match', 'embedded-ai', 'embedded-ai/python-1', 179, 'code', 1, false, 'A **match statement** compares one value against each `case` in turn and runs the first one that fits. The case `_` fits anything, and `|` means "or". It needs Python 3.10 or newer. What does this print?

```python
command = "stop"
match command:
    case "go":
        print("moving")
    case "stop" | "halt":
        print("stopping")
    case _:
        print("unknown")
```', '`stopping`

`command` is `"stop"`. The first case, `"go"`, does not fit. The second case lists two choices separated by `|`, and `"stop"` is one of them, so it prints `stopping` and the match statement ends. The `case _:` block would only run if nothing before it had fit.

Tip: A match statement is a tidy replacement for a long `if/elif` chain that compares one value against many exact options.

Watch out: Only the first matching case runs, and there is no need for `break`.', null, '{}'::text[], null, 'python match statement case wildcard underscore 3.10', array['CS50P, Lecture 1 (Conditionals)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-while-loop', 'embedded-ai', 'embedded-ai/python-1', 180, 'definition', 1, false, 'What is a **while loop**, and what is one **iteration**?', 'A while loop repeats its indented block for as long as its condition is `True`, and each pass through the block is one iteration.

```python
n = 3
while n > 0:
    print(n)
    n = n - 1
```

This prints `3`, `2`, `1`. Python checks the condition `n > 0` before every iteration, and stops as soon as it is `False`.

Key idea: The body must change something the condition depends on, here `n`, or the loop never finishes.

Watch out: The condition is checked first, so if it is `False` from the start, the body runs zero times.', null, '{}'::text[], null, 'python while loop condition iteration repeat', array['CS50P, Lecture 2 (Loops)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-for-range', 'embedded-ai', 'embedded-ai/python-1', 181, 'definition', 1, false, 'What is a **for loop**, and which numbers does `range(a, b)` produce?', 'A for loop runs its block once for each item of a sequence, and `range(a, b)` produces the whole numbers from `a` up to but not including `b`.

`range(2, 5)` produces `2`, `3`, `4`. The shorter `range(b)` starts at 0, so `range(3)` produces `0`, `1`, `2`.

Example: `for i in range(3): print(i)` prints `0`, `1`, `2` on separate lines. The same loop works over text: `for ch in "hi":` runs once for `"h"` and once for `"i"`.

Tip: `range(a, b)` produces exactly `b - a` numbers, which is a quick way to count them.', null, '{}'::text[], null, 'python for loop range(a, b) stop excluded sequence', array['CS50P, Lecture 2 (Loops)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-break-continue', 'embedded-ai', 'embedded-ai/python-1', 182, 'concept', 1, false, 'What do `break` and `continue` do inside a loop?', '`break` ends the loop immediately, while `continue` skips the rest of the current iteration and jumps to the next one.

Example: To stop at the first multiple of 7, loop upward and run `break` as soon as `i % 7 == 0`. To skip every odd number but keep looping, run `continue` when `i % 2 == 1`.

Watch out: `break` leaves only the innermost loop it sits in, and `continue` does not leave the loop at all. It only moves on to the next iteration, where the loop condition is checked again.', null, '{}'::text[], null, 'python break continue loop skip exit iteration', array['CS50P, Lecture 2 (Loops)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-range-misconception', 'embedded-ai', 'embedded-ai/python-1', 183, 'misconception', 1, false, 'Why is it false that `range(5)` produces the numbers 1 to 5?', '`range(5)` produces `0, 1, 2, 3, 4`: it starts at 0 and stops before 5, so it gives five numbers.

An **off-by-one error** is a bug where a loop runs one time too many or one too few, usually because of a boundary like this one. Counting from 0 and excluding the end is the cause of most of them.

Example: To loop over 1 to 5, write `range(1, 6)`. The stop value must be one past the last number you want.

Tip: `range(a, b)` gives `b - a` numbers. If the count is wrong, check both the start and the stop.', null, '{}'::text[], null, 'python range(5) 0 to 4 off-by-one error', array['CS50P, Lecture 2 (Loops)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-infinite', 'embedded-ai', 'embedded-ai/python-1', 184, 'code', 1, false, 'An **infinite loop** is a loop whose condition never becomes `False`. This one should print 3, 2, 1 and stop, but it never ends. What line fixes it, and where does it go?

```python
n = 3
while n > 0:
    print(n)
```', 'Add `n = n - 1` as the last line inside the loop.

The condition `n > 0` depends on `n`, but nothing in the body ever changes `n`, so the condition is `True` forever and the program prints `3` without end. With `n = n - 1` at the end of the body, `n` goes 3, 2, 1, 0, and the loop stops.

Tip: In a terminal, press Ctrl+C to stop a runaway program.

Watch out: The new line must be indented so it is inside the loop. At the left margin, it would run only after the loop, which never ends.', null, '{}'::text[], null, 'python infinite loop while never changes condition fix', array['CS50P, Lecture 2 (Loops)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-range-step', 'embedded-ai', 'embedded-ai/python-1', 185, 'code', 1, false, '`range(start, stop, step)` moves by `step` each time. What does this print?

```python
for i in range(2, 10, 3):
    print(i)
```', '`2`, `5` and `8`, each on its own line.

The loop starts at 2 and adds 3 each time: 2, 5, 8, and the next would be 11, which is past the stop value 10. The stop value 10 itself is never reached, because `range` stops before it.

Example: `range(10, 0, -2)` counts down by 2, giving 10, 8, 6, 4, 2. Notice that 0 is excluded again.', null, '{}'::text[], null, 'python range start stop step loop output', array['CS50P, Lecture 2 (Loops)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-break-continue', 'embedded-ai', 'embedded-ai/python-1', 186, 'code', 2, false, 'What does this print?

```python
for i in range(1, 8):
    if i % 2 == 0:
        continue
    if i > 5:
        break
    print(i)
```', '`1`, `3` and `5`, each on its own line.

Trace it. For `i` equal to 1, 3 and 5 the number is odd and not above 5, so it prints. For 2, 4 and 6, `i % 2 == 0` is true, so `continue` skips the print. For 7 the number is odd but above 5, so `break` ends the loop.

Watch out: The order of the two checks matters. Because `continue` comes first, `6` is skipped before the `break` test is ever reached.', null, '{}'::text[], null, 'python break continue trace for loop odd numbers output', array['CS50P, Lecture 2 (Loops)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-off-by-one', 'embedded-ai', 'embedded-ai/python-1', 187, 'code', 2, false, 'This code was meant to add up the numbers 1 through 4. What does it print, and what one change makes it do what was meant?

```python
total = 0
i = 1
while i < 4:
    total = total + i
    i = i + 1
print(total)
```', 'It prints `6`, and changing `i < 4` to `i <= 4` makes it print `10`.

The loop runs for `i` equal to 1, 2 and 3, and stops when `i` reaches 4, so the total is 1 + 2 + 3 = 6. The number 4 is never added: this is an off-by-one error in the condition.

Tip: When a loop is wrong by exactly one step, check each boundary: does `<` need to be `<=`, and does the starting value need to change?

Example: Another fix is `while i < 5`. Both versions add 4 and give `10`.', null, '{}'::text[], null, 'python while loop off-by-one error total sum condition', array['CS50P, Lecture 2 (Loops)', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-function', 'embedded-ai', 'embedded-ai/python-1', 188, 'definition', 1, false, 'What is a **function**, and how do you define it and call it?', 'A function is a named, reusable block of code: `def name():` defines it, and `name()` calls it, which runs the block.

```python
def greet():
    print("hello")

greet()
greet()
```

This prints `hello` twice. The `def` line only teaches Python the name. The code inside runs each time you call the function.

Why it matters: Functions let you write a piece of logic once and use it many times, and they give it a name that says what it does.

Watch out: `greet` without the brackets only refers to the function. It is the brackets, `greet()`, that run it.', null, '{}'::text[], null, 'python function def call reusable block of code', array['CS50P, Lecture 0 (Functions, Variables)', 'CS50P, Lecture 9 (Et Cetera): Global Variables; Type Hints; Docstrings', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-parameter-argument', 'embedded-ai', 'embedded-ai/python-1', 189, 'definition', 1, false, 'What is the difference between a **parameter** and an **argument**?', 'A parameter is the name listed in a function''s definition, and an argument is the actual value you pass in when you call the function.

Example: In `def square(n):`, the name `n` is the parameter. In `square(4)`, the value `4` is the argument. While the function runs, `n` refers to `4`.

Tip: You can also pass an argument by name, as in `square(n=4)`.

Watch out: Passing the wrong number of arguments is an error. A function that needs two values cannot be called with one, unless the missing one has a default.', null, '{}'::text[], null, 'python parameter vs argument function definition call', array['CS50P, Lecture 0 (Functions, Variables)', 'CS50P, Lecture 9 (Et Cetera): Global Variables; Type Hints; Docstrings', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-scope', 'embedded-ai', 'embedded-ai/python-1', 190, 'definition', 1, false, 'What are **scope**, a **local variable** and a **global variable**?', 'Scope is the part of a program where a name can be used; a local variable exists only inside the function that assigned it, and a global variable is assigned at the top level of the file.

Assigning to a name inside a function always creates a new local variable, even when a global with the same name exists. The global is left alone. To really change a global from inside a function, you must declare it first with the line `global name`.

Example: A function can read a global variable freely. It is only assigning that makes the name local.

Key idea: Prefer passing values in as arguments and sending results back to the caller (the next card covers `return`). Functions that depend on globals are harder to test and to reuse.', null, '{}'::text[], null, 'python scope local variable global variable function', array['CS50P, Lecture 0 (Functions, Variables)', 'CS50P, Lecture 9 (Et Cetera): Global Variables; Type Hints; Docstrings', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-return-value', 'embedded-ai', 'embedded-ai/python-1', 191, 'concept', 1, false, 'What is a **return value**, and how does `return` differ from `print`?', '`return` hands a value back to the code that called the function and ends the function, whereas `print` only shows text on the screen.

The value sent back is the function''s **return value**. The caller can store it, calculate with it or pass it on.

Example: With `def add(a, b): return a + b`, the line `total = add(2, 3)` stores `5` in `total`. Had the function only printed `5`, `total` would hold nothing useful.

Watch out: A `return` ends the function at once, so any lines after it inside the function never run.', null, '{}'::text[], null, 'python return value vs print function returns', array['CS50P, Lecture 0 (Functions, Variables)', 'CS50P, Lecture 9 (Et Cetera): Global Variables; Type Hints; Docstrings', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-print-not-return', 'embedded-ai', 'embedded-ai/python-1', 192, 'misconception', 1, false, 'Why is it false that a function that **prints** its result also gives that result back to the caller?', 'A function with no `return` hands back `None`, Python''s "no value" value, so the caller gets `None` even though the function printed something.

```python
def double(n):
    print(n * 2)

x = double(4)
print(x)
```

The first `print` inside the function shows `8`. But `x` is `None`, so the last line shows `None`.

Watch out: Using `x` later, as in `x + 1`, then raises an error, because you cannot add a number to `None`. If the caller needs the value, use `return n * 2`.', null, '{}'::text[], null, 'python function print vs return None missing return', array['CS50P, Lecture 0 (Functions, Variables)', 'CS50P, Lecture 9 (Et Cetera): Global Variables; Type Hints; Docstrings', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-default-arg', 'embedded-ai', 'embedded-ai/python-1', 193, 'code', 1, false, 'A **default argument** is a value written in the definition that is used when the caller leaves that argument out. What does this print?

```python
def greet(name="world"):
    return "hi " + name

print(greet(), greet("Ada"))
```', '`hi world hi Ada`

`greet()` passes nothing, so `name` takes its default, `"world"`, and the function returns `"hi world"`. `greet("Ada")` supplies an argument, which replaces the default, giving `"hi Ada"`. `print` puts a space between the two.

Tip: Defaults make a function easy to call in the common case while still allowing a change. Parameters with defaults go after the ones without.', null, '{}'::text[], null, 'python default argument function def greet output', array['CS50P, Lecture 0 (Functions, Variables)', 'CS50P, Lecture 9 (Et Cetera): Global Variables; Type Hints; Docstrings', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-scope', 'embedded-ai', 'embedded-ai/python-1', 194, 'code', 2, false, 'Which values does this print?

```python
x = 5

def f():
    x = 99
    return x

print(f(), x)
```', '`99 5`

Inside `f`, the line `x = 99` creates a new local variable that exists only while `f` runs. The global `x` still refers to `5`. So `f()` returns `99`, and the global `x` printed afterwards is still `5`.

Key idea: Assigning inside a function never changes a global. The name on the left of `=` becomes local unless you declare it with `global x`.

Watch out: If the function had no assignment, it could read the global `x`. The assignment is what makes `x` local for the whole function.', null, '{}'::text[], null, 'python local vs global variable same name function output', array['CS50P, Lecture 0 (Functions, Variables)', 'CS50P, Lecture 9 (Et Cetera): Global Variables; Type Hints; Docstrings', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-docstring-hints', 'embedded-ai', 'embedded-ai/python-1', 195, 'code', 2, false, 'The `: float` and `-> float` parts are **type hints**, which say what types are expected, and the triple-quoted line is a **docstring**, which describes the function. What does this print?

```python
def area(w: float, h: float) -> float:
    """Return the area of a w by h rectangle."""
    return w * h

print(area(2, 3.5))
```', '`7.0`

The function multiplies `2` by `3.5`, and an int times a float is a float, so the result is `7.0`.

The docstring is text placed first in the function, to explain what it does. Tools and the `help()` function show it. The type hints document the intended types, but Python does not enforce them when the code runs.

Watch out: `area("a", 2)` is not blocked by the hints. It would run and give `"aa"`. The hints help readers and checking tools only.', null, '{}'::text[], null, 'python docstring type hints function annotation float', array['CS50P, Lecture 0 (Functions, Variables)', 'CS50P, Lecture 9 (Et Cetera): Global Variables; Type Hints; Docstrings', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-main-idiom', 'embedded-ai', 'embedded-ai/python-1', 196, 'code', 2, false, 'The file `tool.py` below is saved. What does `python tool.py` print, and what does it print when some other program loads `tool.py` as a library?

```python
# tool.py
def main():
    print("running")

if __name__ == "__main__":
    main()
```', 'It prints `running` when run directly, and nothing when loaded by another program.

Python sets a special variable called `__name__` in every file. For the file you run directly it is `"__main__"`, so the `if` test is true and `main()` runs. When another file loads this one as a library, `__name__` is the file''s own name, `"tool"`, so the test is false and nothing is printed.

Why it matters: This lets a file work both as a program and as a library of functions other code can borrow, without running the program part by accident.

Tip: Putting the program''s steps in `main()` keeps the file tidy and easy to test.', null, '{}'::text[], null, 'python if __name__ == __main__ main() idiom run directly', array['CS50P, Lecture 0 (Functions, Variables)', 'CS50P, Lecture 9 (Et Cetera): Global Variables; Type Hints; Docstrings', 'The Python Tutorial, ch. 4 (More Control Flow Tools)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-list-index', 'embedded-ai', 'embedded-ai/python-1', 197, 'definition', 1, false, 'What is a **list** in Python, and what is an **index**?', 'A list is an ordered, changeable collection written `[a, b, c]`, and an index is an item''s position in it, counted from 0 (or from -1 for the last item, going backward).

Example: With `colors = ["red", "green", "blue"]`:
- `colors[0]` is `"red"`.
- `colors[2]` and `colors[-1]` are both `"blue"`.
- `len(colors)` is `3`.

Watch out: A list of 3 items has indexes 0, 1 and 2. Asking for `colors[3]` is an error (an `IndexError`), because there is no item 3.', null, '{}'::text[], null, 'python list index zero-based negative index len', array['CS50P, Lecture 2 (Loops)', 'CS50P, Lecture 9 (Et Cetera): set; List Comprehensions; Dictionary Comprehensions; enumerate', 'The Python Tutorial, ch. 5 (Data Structures)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-dictionary', 'embedded-ai', 'embedded-ai/python-1', 198, 'definition', 1, false, 'What is a **dictionary** (dict) in Python, and what are its **keys** and **values**?', 'A dictionary stores pairs in which each key maps to a value, so `ages = {"Ada": 36}` lets you look up `ages["Ada"]` and get `36`.

The **key** (`"Ada"`) is what you look up by, and the **value** (`36`) is what you get back. Keys are unique, and you find an entry by its key, not by a position number.

Example: `ages["Cy"] = 20` adds a new pair, and `ages["Ada"] = 37` replaces an existing value.

Watch out: Looking up a key that is not there is an error (a `KeyError`). The call `ages.get("Zed", 0)` returns `0` instead of failing.', null, '{}'::text[], null, 'python dictionary key value pairs lookup get', array['CS50P, Lecture 2 (Loops)', 'CS50P, Lecture 9 (Et Cetera): set; List Comprehensions; Dictionary Comprehensions; enumerate', 'The Python Tutorial, ch. 5 (Data Structures)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-slice', 'embedded-ai', 'embedded-ai/python-1', 199, 'definition', 1, false, 'What does the **slice** `items[a:b]` return?', 'A new list (or piece of text) containing the items from index `a` up to but not including index `b`.

Example: `[10, 20, 30, 40][1:3]` is `[20, 30]`. Leaving out a number means "from the start" or "to the end": `[:2]` is the first two items, and `[2:]` is everything from index 2 on.

Key idea: Like `range`, the stop index is excluded, and the slice has `b - a` items.

Tip: A third number sets the step: `items[::2]` takes every second item.', null, '{}'::text[], null, 'python slice list a:b stop excluded [1:3]', array['CS50P, Lecture 2 (Loops)', 'CS50P, Lecture 9 (Et Cetera): set; List Comprehensions; Dictionary Comprehensions; enumerate', 'The Python Tutorial, ch. 5 (Data Structures)']::text[], '{}'::text[], null, false);
insert into profession_card_rows_0d4cbcc197 (id, profession_id, module_id, position, kind, difficulty, checkpoint, title, body, answer, accepted_answers, answer_display, search_query, refs, tags, as_of, retired) values
  ('embedded-ai/py1-choose-collection', 'embedded-ai', 'embedded-ai/python-1', 200, 'concept', 1, false, 'How do you choose between a list, a tuple, a set and a dict?', 'Use a list for an ordered, changeable sequence, a tuple for a fixed sequence, a set for unique items, and a dict to look values up by key.

An object is **mutable** if it can be changed in place. Lists, sets and dicts are mutable. A **tuple**, written `(3, 4)`, is like a list that cannot be changed after it is made. A **set**, written `{1, 2, 3}`, keeps each item only once and has no positions.

Example: Readings in order are a list. A point `(3, 4)` is a tuple. The IDs seen so far are a set, because `set([1, 2, 2, 3])` is just `{1, 2, 3}`. Names with ages are a dict.

Watch out: `{}` is an empty dict, not an empty set. For an empty set, write `set()`.', null, '{}'::text[], null, 'python list tuple set dict difference mutable choose', array['CS50P, Lecture 2 (Loops)', 'CS50P, Lecture 9 (Et Cetera): set; List Comprehensions; Dictionary Comprehensions; enumerate', 'The Python Tutorial, ch. 5 (Data Structures)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-list-alias', 'embedded-ai', 'embedded-ai/python-1', 201, 'misconception', 2, false, 'Why is it false that `b = a` makes a separate copy of the list `a`?', '`b = a` makes a second name for the same list, called **aliasing**, so a change made through `b` is also seen through `a`; use `a.copy()` to get a real copy.

```python
a = [1, 2, 3]
b = a
b.append(4)
print(a)
```

This prints `[1, 2, 3, 4]`. There is only one list, with two names attached. Because a list is mutable, changing it in place shows up under every name.

Watch out: With immutable values such as ints and text, aliasing is invisible, because they cannot be changed in place. It bites only with mutable ones such as lists and dicts. `a[:]` also makes a copy.', null, '{}'::text[], null, 'python list aliasing b = a copy mutable same list', array['CS50P, Lecture 2 (Loops)', 'CS50P, Lecture 9 (Et Cetera): set; List Comprehensions; Dictionary Comprehensions; enumerate', 'The Python Tutorial, ch. 5 (Data Structures)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-list-ops', 'embedded-ai', 'embedded-ai/python-1', 202, 'code', 1, false, 'What does this print?

```python
nums = [10, 20, 30, 40]
nums[0] = 99
nums.append(50)
print(nums[0], nums[-1], len(nums))
```', '`99 50 5`

`nums[0] = 99` replaces the first item, which is allowed because lists are mutable. `nums.append(50)` adds a new item at the end, so the list is `[99, 20, 30, 40, 50]`. Its first item is `99`, its last is `50`, and it holds `5` items.

Tip: `append` adds to the end, and `nums.pop()` removes and returns the last item.', null, '{}'::text[], null, 'python list assign index append len output', array['CS50P, Lecture 2 (Loops)', 'CS50P, Lecture 9 (Et Cetera): set; List Comprehensions; Dictionary Comprehensions; enumerate', 'The Python Tutorial, ch. 5 (Data Structures)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-enumerate', 'embedded-ai', 'embedded-ai/python-1', 203, 'code', 1, false, '`enumerate(items)` gives the position and the item together on each pass of a loop. What does this print?

```python
for i, color in enumerate(["red", "green"]):
    print(i, color)
```', '`0 red` on the first line and `1 green` on the second.

On each pass, `enumerate` hands over a pair: the index and the item. The line `for i, color in ...` unpacks the pair into the two names. Counting starts at 0.

Tip: `enumerate(items, start=1)` counts from 1 instead, which suits numbered output.

Why it matters: It replaces the clumsy `for i in range(len(items))` pattern and is less likely to cause an off-by-one error.', null, '{}'::text[], null, 'python enumerate loop index and item for i, x', array['CS50P, Lecture 2 (Loops)', 'CS50P, Lecture 9 (Et Cetera): set; List Comprehensions; Dictionary Comprehensions; enumerate', 'The Python Tutorial, ch. 5 (Data Structures)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-dict-items', 'embedded-ai', 'embedded-ai/python-1', 204, 'code', 1, false, '`.items()` gives each key and its value as a pair. What does this print?

```python
ages = {"Ada": 36, "Bo": 5}
ages["Cy"] = 20
for name, age in ages.items():
    print(name, age)
print(ages["Bo"], len(ages))
```', '`Ada 36`, `Bo 5` and `Cy 20` on three lines, then `5 3`.

Assigning to a new key adds a pair, so the dict now holds three. The loop visits the pairs in the order they were added, which Python guarantees for dicts. The last line looks up `"Bo"` to get `5`, and `len(ages)` counts the pairs, which is `3`.

Watch out: Looping over `ages` with a plain `for name in ages:` gives only the keys. Add `.items()` to get both parts.', null, '{}'::text[], null, 'python dict items loop key value pairs len', array['CS50P, Lecture 2 (Loops)', 'CS50P, Lecture 9 (Et Cetera): set; List Comprehensions; Dictionary Comprehensions; enumerate', 'The Python Tutorial, ch. 5 (Data Structures)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-list-comp', 'embedded-ai', 'embedded-ai/python-1', 205, 'code', 2, false, 'A **list comprehension** builds a new list in one line: `[expression for name in sequence if condition]`. What does this print?

```python
squares = [n * n for n in range(5) if n % 2 == 0]
print(squares)
```', '`[0, 4, 16]`

The loop part takes `n` from `0, 1, 2, 3, 4`. The `if` part keeps only the even ones: `0`, `2` and `4`. For each one kept, the expression `n * n` gives the new item: `0`, `4` and `16`.

Tip: Read it left to right as "the square of n, for each n in range(5), if n is even".

Watch out: The `if` filters which items are used. It does not choose between two results.', null, '{}'::text[], null, 'python list comprehension squares if condition output', array['CS50P, Lecture 2 (Loops)', 'CS50P, Lecture 9 (Et Cetera): set; List Comprehensions; Dictionary Comprehensions; enumerate', 'The Python Tutorial, ch. 5 (Data Structures)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-code-dict-comp', 'embedded-ai', 'embedded-ai/python-1', 206, 'code', 2, false, 'A **dictionary comprehension** builds a dict in one line: `{key: value for name in sequence}`. What does this print?

```python
words = ["hi", "hello"]
lengths = {w: len(w) for w in words}
print(lengths)
```', '`{''hi'': 2, ''hello'': 5}`

For each word `w` in the list, the comprehension makes one pair with the word as the key and its length as the value. Python prints text inside a dict with single quotes.

Example: Swapping keys and values of a dict `d` is `{v: k for k, v in d.items()}`.

Why it matters: It is a compact way to build a lookup table from existing data.', null, '{}'::text[], null, 'python dictionary comprehension key value len words', array['CS50P, Lecture 2 (Loops)', 'CS50P, Lecture 9 (Et Cetera): set; List Comprehensions; Dictionary Comprehensions; enumerate', 'The Python Tutorial, ch. 5 (Data Structures)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-with-open', 'embedded-ai', 'embedded-ai/python-1', 207, 'definition', 2, false, 'What does `with open("data.txt") as f:` do, and what is a **file object**?', '`open` returns a file object, your handle for reading or writing the file, and the `with` statement closes the file automatically when its indented block ends.

```python
with open("data.txt") as f:
    text = f.read()
```

Here `f` is the **file object**, and `f.read()` returns the whole contents as one string. The **with statement** guarantees the file is closed afterwards, even if an error happens inside the block.

Why it matters: A file left open can lose written data that has not yet been saved to disk.

Watch out: Using `f` after the `with` block has ended is an error, because the file is already closed.', null, '{}'::text[], null, 'python with open as f file object read close automatically', array['CS50P, Lecture 4 (Libraries)', 'CS50P, Lecture 6 (File I/O)', 'The Python Tutorial, ch. 6 (Modules)', 'The Python Tutorial, ch. 7 (Input and Output)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-file-modes', 'embedded-ai', 'embedded-ai/python-1', 208, 'definition', 2, false, 'What do the **file modes** `''r''`, `''w''` and `''a''` do in `open(name, mode)`?', '`''r''` reads (the default), `''w''` writes after erasing any existing content, and `''a''` appends to the end of the file.

A **file mode** is the text that tells `open` what you intend to do with the file. Both `''w''` and `''a''` create the file if it does not exist, while `''r''` on a missing file is an error (a `FileNotFoundError`).

Watch out: `''w''` erases the old contents the moment the file is opened, even if you never write anything. Use `''a''` when you want to keep what is already there.', null, '{}'::text[], null, 'python file modes r w a open write append read', array['CS50P, Lecture 4 (Libraries)', 'CS50P, Lecture 6 (File I/O)', 'The Python Tutorial, ch. 6 (Modules)', 'The Python Tutorial, ch. 7 (Input and Output)']::text[], '{}'::text[], null, false),
  ('embedded-ai/py1-modules-import', 'embedded-ai', 'embedded-ai/python-1', 209, 'concept', 2, false, 'What are a **module**, `import` and the **standard library**?', 'A module is a file of ready-made Python code, `import name` makes it available to your program, and the standard library is the collection of modules that comes with Python.

Example: After `import math`, the call `math.sqrt(16)` gives `4.0`. After `import random`, `random.randint(1, 6)` gives a whole number from 1 to 6, both ends included. Other standard modules include `statistics`, `csv` and `sys`.

